      const header = box.createDiv("bases-toolbar-section-header");
      header.createDiv({ cls: "collapse-icon" + (open ? "" : " is-collapsed"), text: "▸" });
      header.createDiv({ cls: "bases-toolbar-section-header-text", text: title });
