// Runnable / ButtonModal (shared bases; Runnable and DialogModal already exist as clean-room modules)
// =====================================================================================================================

function ng08DefineBookmarkRunnable() {
  return Runnable;
}

function ng08DefineButtonModal(host) {
  return defineDialogModal(host);
}

