// ---- factory exports for the manifest ---------------------------------------------------------------

function ng11DefineSearchMatchResult(host) {
  ng11BindHost(host);
  ng11SearchViewClasses.SearchMatchResult = SearchMatchResult;
  return SearchMatchResult;
}
function ng11DefineSearchPropertyResult(host) {
  ng11BindHost(host);
  ng11SearchViewClasses.SearchPropertyResult = SearchPropertyResult;
  return SearchPropertyResult;
}
function ng11DefineSearchFileResult(host) {
  ng11BindHost(host);
  ng11SearchViewClasses.SearchFileResult = SearchFileResult;
  return SearchFileResult;
}
function ng11DefineSearchResults(host) {
  ng11BindHost(host);
  ng11SearchViewClasses.SearchResults = SearchResults;
  return SearchResults;
}

// ---- n-g11-view.js ----
// g11 clean-room: the global "search" view — query input with autocomplete, option
// toggles, sort dropdown, virtualised results, incremental queue search, keyboard
// navigation, copy-results modal, explain panel and recent-searches persistence.


const V = ng11SearchViewClasses;
let ng11ViewHost = null;
function VH() { return ng11ViewHost; }
function ng11SearchStrings() { return VH().t.plugins.search; }

// Contract-name aliases consumed by sibling modules (flat-scope compat).
const searchViewClasses = ng11SearchViewClasses;
const compareSearchText = ng11CompareSearchText;
const countSearchMatches = ng11CountSearchMatches;
const renderMatchRanges = ng11RenderMatchRanges;
const indexOfPositionOffset = ng11IndexOfPositionOffset;
const preventMiddleClick = ng11PreventMiddleClick;
const contextLineBounds = ng11ContextLineBounds;
const SEARCH_SORT_ORDERS = ng11SearchSortOrders;
const SEARCH_SORT_GROUPS = ng11SearchSortGroups;
const searchSortLabel = ng11SearchSortLabel;
const sortOrderComparator = ng11SortOrderComparator;
const toggleElementVisibility = ng11ToggleElementVisibility;
const batchedIteration = ng11BatchedIteration;
const runSearchOverFiles = ng11RunSearchOverFiles;
const copyTextToClipboard = ng11CopyTextToClipboard;
const defineFileQueue = (host) => ng11DefineFileQueue(host);
const defineSearchMatchResult = (host) => host && (V.SearchMatchResult = (V.SearchMatchResult || ng11LazyMatchResult(host)));
const defineSearchPropertyResult = (host) => host && (V.SearchPropertyResult = (V.SearchPropertyResult || ng11LazyPropResult(host)));
const defineSearchFileResult = (host) => host && (V.SearchFileResult = (V.SearchFileResult || ng11LazyFileResult(host)));
