const ng12PubOptSiteName = "siteName";
const ng12PubOptLogo = "logo";
const ng12PubOptNoindex = "noindex";
const ng12PubOptDefaultTheme = "defaultTheme";
const ng12PubOptShowThemeToggle = "showThemeToggle";
const ng12PubOptShowNavigation = "showNavigation";
const ng12PubOptShowGraph = "showGraph";
const ng12PubOptShowOutline = "showOutline";
const ng12PubOptShowSearch = "showSearch";
const ng12PubOptGoogleAnalytics = "googleAnalytics";
