    "editor:insert-link": [{ modifiers: ["Mod"], key: "K" }],
    "editor:insert-wikilink": [{ modifiers: ["Mod"], key: "[" }],
    "editor:insert-embed": [{ modifiers: ["Mod", "Shift"], key: "[" }],
    "editor:insert-tag": [{ modifiers: ["Mod"], key: "#" }],
