// ---- n-g20-node.js ----
// g20 clean-room: canvas node classes — base node, content-mounting node, dummy
// node, editable node, text node and link (webpage) node.
//
// Replaces orig S5/x5/T5/A5/I5/F5 (canvas-node.js).

const NG20_COLOR_RE = /^(#[0-9a-f]{3,8}|rgba?\([^)]*\))$/i;
const NG20_PALETTE_MAX = 6;

function ng20NormalColor(color) {
  color = (color || "").trim();
  if (!color) return "";
  if (/^\d+$/.test(color)) {
    const n = +color;
    return n >= 1 && n <= NG20_PALETTE_MAX ? String(n) : "";
  }
  const hex = rgbTripleToHex(color);
  if (hex) return hex;
  if (NG20_COLOR_RE.test(color)) return color;
  return "";
}

function ng20Num(v, fallback) { return ng20Finite(v) ? v : fallback; }

// ---- base node (S5) ---------------------------------------------------------------------------

function defineNg20CanvasNode(host) {
  class CanvasNode {
    constructor(canvas_, id) {
      this.canvas = canvas_;
      this.app = canvas_.app;
      this.id = id || randomHex(16);
      this.type = "";
      this.x = 0;
      this.y = 0;
      this.width = 100;
      this.height = 100;
      this.color = "";
      this.zIndex = canvas_.getZIndex();
      this.aspectRatio = null;
      this.isEditing = false;
      this.destroyed = false;
      this.initialized = false;
      this.unknownData = {};
      this.child = null;

      this.nodeEl = createDiv("canvas-node");
      this.nodeEl.setAttr("data-node-id", this.id);
      this.containerEl = this.nodeEl.createDiv("canvas-node-container");
      this.contentEl = this.containerEl.createDiv("canvas-node-content");
      this.contentBlockerEl = this.containerEl.createDiv("canvas-node-content-blocker");
      this.contentBlockerEl.hide();
      this.placeholderEl = this.containerEl.createDiv("canvas-node-placeholder");
      this.labelEl = this.containerEl.createDiv("canvas-node-label");
      this.labelEl.hide();
      this.labelEl.setAttribute("contenteditable", "false");
      this.labelEl.addEventListener("blur", () => this.commitLabel());
      this.labelEl.addEventListener("keydown", (evt) => {
        evt.stopPropagation();
        if (evt.key === "Enter") { evt.preventDefault(); this.labelEl.blur(); }
        else if (evt.key === "Escape") { this.labelEl.setText(this.labelText()); this.labelEl.blur(); }
      });
      this.labelEl.addEventListener("pointerdown", (evt) => evt.stopPropagation());

      this.nodeEl.addEventListener("pointerdown", (evt) => this.onPointerdown(evt));
      this.nodeEl.addEventListener("click", (evt) => this.onClick(evt));
      this.nodeEl.addEventListener("contextmenu", (evt) => this.onContextMenu(evt));
      this.nodeEl.addEventListener("dblclick", (evt) => this.onDoubleClick(evt));

      this.render();
    }

    get rect() { return { x: this.x, y: this.y, width: this.width, height: this.height }; }
    get isAttached() { return !!this.nodeEl.parentNode; }
    get isFocused() { return this.nodeEl.hasClass("is-focused"); }

    getBBox() { return box(this.x, this.y, this.x + this.width, this.y + this.height); }

    // ---------- geometry ----------

    moveTo(pos) {
      if (!pos) return;
      if (ng20Finite(pos.x)) this.x = Math.round(pos.x);
      if (ng20Finite(pos.y)) this.y = Math.round(pos.y);
      this.canvas.markMoved(this);
      this.render();
    }

    resize(size) {
      if (!size) return;
      if (ng20Finite(size.width)) this.width = Math.round(size.width);
      if (ng20Finite(size.height)) this.height = Math.round(size.height);
      this.canvas.markMoved(this);
      this.render();
    }

    moveAndResize(rect_) {
      if (!rect_) return;
      if (ng20Finite(rect_.x)) this.x = Math.round(rect_.x);
      if (ng20Finite(rect_.y)) this.y = Math.round(rect_.y);
      if (ng20Finite(rect_.width)) this.width = Math.round(rect_.width);
      if (ng20Finite(rect_.height)) this.height = Math.round(rect_.height);
      this.canvas.markMoved(this);
      this.render();
    }

    // ---------- colour ----------

    setColor(color, render = true) {
      this.color = ng20NormalColor(color);
      if (render) this.render();
      else this.canvas.markDirty(this);
    }

    // ---------- codec ----------

    getData() {
      const out = { id: this.id, x: this.x, y: this.y, width: this.width, height: this.height };
      if (this.type) out.type = this.type;
      if (this.color) out.color = this.color;
      return { ...this.unknownData, ...out };
    }

    setData(data) {
      if (!data || typeof data !== "object") return;
      const known = new Set(["id", "type", "x", "y", "width", "height", "color"]);
      const unknown = {};
      for (const key of Object.keys(data)) if (!known.has(key)) unknown[key] = data[key];
      this.unknownData = unknown;
      if (ng20Finite(data.x)) this.x = Math.round(data.x);
      if (ng20Finite(data.y)) this.y = Math.round(data.y);
      if (ng20Finite(data.width) && data.width > 0) this.width = Math.round(data.width);
      if (ng20Finite(data.height) && data.height > 0) this.height = Math.round(data.height);
      if (data.color !== undefined) this.setColor(data.color, false);
      this.initialized = true;
      this.canvas.markMoved(this);
      this.canvas.markDirty(this);
    }

    // ---------- lifecycle ----------

    attach() {
      if (this.isAttached) return;
      this.canvas.canvasEl.appendChild(this.nodeEl);
      this.renderZIndex();
      this.updateBreakpoint();
    }

    detach() {
      this.nodeEl.detach();
    }

    preDetach() {
      this.unloadChildSafe();
    }

    unloadChildSafe() {
      if (this.child && typeof this.child.unload === "function") this.child.unload();
    }

    destroy() {
      if (this.destroyed) return;
      this.destroyed = true;
      this.detach();
      this.unloadChildSafe();
      this.nodeEl.remove();
    }

    render() {
      if (this.destroyed) return;
      const el = this.nodeEl;
      el.style.left = this.x + "px";
      el.style.top = this.y + "px";
      el.style.width = this.width + "px";
      el.style.height = this.height + "px";
      el.style.zIndex = String(this.zIndex);
      s13ApplyCanvasColor(this.containerEl, this.color, host);
      this.renderZIndex();
      this.renderLabel();
    }

    renderZIndex() {
      if (!this.nodeEl.parentNode) return;
      // keep DOM order consistent with zIndex so equal-z siblings paint in order
      const parent = this.nodeEl.parentNode;
      let ref = this.nodeEl.nextSibling;
      while (ref) {
        const zid = ref.__ng20z;
        if (zid !== undefined && zid < this.zIndex) break;
        ref = ref.nextSibling;
      }
      if (ref !== this.nodeEl.nextSibling) parent.insertBefore(this.nodeEl, ref);
    }

    updateZIndex() {
      this.zIndex = this.canvas.getZIndex();
      this.render();
      this.canvas.markMoved(this);
    }

    updateBreakpoint() {}

    // ---------- label ----------

    renderLabel() {
      const show = this.labelText && this.labelText() ? true : !!this.labelElText;
      void show;
    }

    labelText() { return ""; }

    updateNodeLabel(text) {
      this.labelElText = text || "";
      if (this.labelEl.getAttribute("contenteditable") !== "true") this.labelEl.setText(this.labelElText);
      this.labelEl.toggle(this.labelElText.length > 0 || this.labelEl.getAttribute("contenteditable") === "true");
    }

    /** Focuses the node label for inline renaming (group nodes). */
    focusLabel() {
      if (!this.labelElText && this.labelText && !this.labelText()) return;
      this.labelEl.setAttribute("contenteditable", "true");
      this.labelEl.show();
      this.labelEl.focus();
      host.focusAndSelectContents(this.labelEl);
    }

    commitLabel() {
      this.labelEl.setAttribute("contenteditable", "false");
      const text = (this.labelEl.innerText || "").trim();
      if (typeof this.setLabel === "function") this.setLabel(text);
      else this.updateNodeLabel(this.labelText());
    }

    // ---------- selection ----------

    focus() { this.nodeEl.addClass("is-focused"); }
    blur() { this.nodeEl.removeClass("is-focused"); }
    select() { this.nodeEl.addClass("is-selected"); }
    deselect() { this.nodeEl.removeClass("is-selected"); }

    // ---------- editing ----------

    isEditable() { return false; }
    startEditing() {}
    setIsEditing(editing) { this.isEditing = !!editing; }

    // ---------- pointer ----------

    onPointerdown(evt) {
      if (evt.button !== 0 || !evt.isPrimary) return;
      if (this.isEditing) return;
      const canvas_ = this.canvas;
      if (canvas_.readonly) return;
      canvas_.handleSelectionDrag(evt, this.nodeEl, this);
    }

    onClick(evt) {
      void evt;
      if (!this.canvas.readonly) this.canvas.selectOnly(this);
    }

    onContextMenu(evt) {
      if (evt.defaultPrevented) return;
      evt.preventDefault();
      this.showMenu(evt);
    }

    onDoubleClick(evt) {
      if (this.canvas.readonly || !this.isEditable()) return;
      if (evt.defaultPrevented) return;
      this.startEditing({ x: evt.clientX, y: evt.clientY });
    }

    showMenu(evt) {
      const canvas_ = this.canvas;
      const menu = new host.Menu();
      const ti = env().gm.plugins.canvas;
      const self = this;
      menu.addSections(["title", "action", "clipboard", "danger"]);
      menu.addItem((item) => item.setSection("action").setTitle(ti.actionBringToFront ? ti.actionBringToFront() : "Bring to front").setIcon("lucide-chevrons-up").onClick(() => self.updateZIndex()));
      if (!canvas_.readonly) {
        menu.addItem((item) => item.setSection("danger").setTitle(ti.actionRemove ? ti.actionRemove() : "Remove").setIcon("lucide-trash-2").setWarning(true).onClick(() => canvas_.removeNode(self)));
      }
      canvas_.app.workspace.trigger("canvas:node-menu", menu, this);
      if (window.__fpNodeMenu) window.__fpNodeMenu(menu, this);
      menu.showAtMouseEvent(evt);
    }

    onResizePointerdown(evt, side) {
      if (this.canvas.readonly) return;
      evt.preventDefault();
      evt.stopPropagation();
      const canvas_ = this.canvas;
      const start = canvas_.posFromEvt(evt);
      const origin = { x: this.x, y: this.y, width: this.width, height: this.height };
      const minDim = canvas_.config.minContainerDimension || 50;
      host.dragWithThreshold(evt, () => ({
        move: (moveEvt) => {
          const p = canvas_.posFromEvt(moveEvt);
          let dx = p.x - start.x;
          let dy = p.y - start.y;
          let { x, y, width, height } = origin;
          const left = side.includes("left");
          const right = side.includes("right");
          const top = side.includes("top");
          const bottom = side.includes("bottom");
          if (left) { x = origin.x + dx; width = origin.width - dx; }
          if (right) { width = origin.width + dx; }
          if (top) { y = origin.y + dy; height = origin.height - dy; }
          if (bottom) { height = origin.height + dy; }
          if (width < minDim) { if (left) x += width - minDim; width = minDim; }
          if (height < minDim) { if (top) y += height - minDim; height = minDim; }
          if (moveEvt.shiftKey && this.aspectRatio) {
            const ratio = width / Math.max(1, height);
            if (Math.abs(dx) > Math.abs(dy)) height = width / ratio; else width = height * ratio;
          }
          this.moveAndResize({ x, y, width, height });
        },
        end: () => canvas_.requestSave(),
      }), 0);
    }

    onResizeDblclick() {}

    /** Begins a connection drag from one of the four side midpoints. */
    onConnectionPointerdown(evt, side) {
      if (evt.button !== 0 || !evt.isPrimary || this.canvas.readonly) return;
      evt.preventDefault();
      evt.stopPropagation();
      const canvas_ = this.canvas;
      const self = this;
      if (host.Keymap.isModEvent(evt)) {
        // modifier-held connection drag -> create a link node instead
        new host.s32UrlModal(canvas_.app, "", (url) => {
          canvas_.createLinkNode({ pos: canvas_.posFromEvt(evt), url });
        }).open();
        return;
      }
      const dummy = new canvas_.DummyNode(canvas_);
      dummy.width = 0;
      dummy.height = 0;
      const edge = new canvas_.EdgeClass(canvas_, randomHex(16), { node: this, side, end: ng20EdgeEndNoneSafe() }, { node: dummy, side: oppositeSide(side), end: ng20EdgeEndArrowSafe() });
      canvas_.addEdge(edge);
      canvas_.wrapperEl.addClass("is-connecting");
      let overNode = null;
      let overSide = null;
      host.dragWithThreshold(evt, () => ({
        move: (moveEvt) => {
          const p = canvas_.posFromEvt(moveEvt);
          dummy.moveTo({ x: p.x, y: p.y });
          const node = canvas_.hitTestNode(p, canvas_.snapDistance);
          overNode = node && node !== self ? node : null;
          overSide = overNode ? ng20SideToward(overNode, p) : null;
          edge.to = overNode
            ? { node: overNode, side: overSide, end: ng20EdgeEndArrowSafe() }
            : { node: dummy, side: oppositeSide(side), end: ng20EdgeEndArrowSafe() };
          edge.update();
          canvas_.markMoved(edge);
        },
        end: () => {
          canvas_.wrapperEl.removeClass("is-connecting");
          if (overNode) {
            edge.to = { node: overNode, side: overSide, end: ng20EdgeEndArrowSafe() };
            canvas_.markMoved(edge);
            canvas_.requestSave();
          } else {
            canvas_.removeEdge(edge);
          }
        },
        cleanup: () => {
          canvas_.wrapperEl.removeClass("is-connecting");
          dummy.detach();
          dummy.destroy();
        },
      }), 0);
    }

    /** Files this node links to (path+subpath), for connected-files queries. */
    getConnectedFiles() { return new Set(); }
  }

  function ng20EdgeEndNoneSafe() { return "none"; }
  function ng20EdgeEndArrowSafe() { return "arrow"; }
  function oppositeSide(side) {
    return { top: "bottom", bottom: "top", left: "right", right: "left" }[side] || "left";
  }
  function ng20SideToward(node, p) {
    const b = node.getBBox();
    const cx = b.minX + (b.maxX - b.minX) / 2;
    const cy = b.minY + (b.maxY - b.minY) / 2;
    const dx = p.x - cx, dy = p.y - cy;
    if (Math.abs(dx) >= Math.abs(dy)) return dx >= 0 ? "right" : "left";
    return dy >= 0 ? "bottom" : "top";
  }

  canvas.Node = CanvasNode;
  return CanvasNode;
}

// ---- content-mounting node (x5) ---------------------------------------------------------------

function defineNg20ContentMountNode(host) {
  const Base = canvas.Node || defineNg20CanvasNode(host);
  class ContentMountNode extends Base {
    constructor(canvas_, id) {
      super(canvas_, id);
      this.isContentMounted = false;
      this.alwaysKeepLoaded = false;
      this._scroll = null;
    }

    updateBreakpoint() {
      const canvas_ = this.canvas;
      const bp = canvas_.zoomBreakpoint;
      const shouldMount = this.alwaysKeepLoaded || canvas_.zoom >= bp;
      if (shouldMount) this.mountContent();
      else this.unmountContent();
    }

    mountContent() {
      if (this.isContentMounted || this.destroyed) return;
      this.isContentMounted = true;
      this.renderContent();
      if (this._scroll) {
        host.restoreScrollPositions(this.contentEl, this._scroll);
        this._scroll = null;
      }
    }

    unmountContent() {
      if (!this.isContentMounted) return;
      this._scroll = host.saveScrollPositions(this.contentEl);
      this.isContentMounted = false;
      this.unloadChildSafe();
      this.child = null;
      this.contentEl.empty();
      this.placeholderEl.show();
    }

    /** Subclass hook: build the type-specific content inside contentEl. */
    renderContent() {
      this.placeholderEl.hide();
    }

    preDetach() {
      super.preDetach();
      if (this.isContentMounted) this.unmountContent();
    }
  }

  canvas.ContentMountNode = ContentMountNode;
  return ContentMountNode;
}

// ---- dummy node (T5) --------------------------------------------------------------------------

function defineNg20DummyNode(host) {
  const Base = canvas.Node || defineNg20CanvasNode(host);
  class DummyNode extends Base {
    constructor(canvas_, id) {
      super(canvas_, id);
      this.type = "dummy";
      this.width = 0;
      this.height = 0;
      this.nodeEl.addClass("canvas-node-dummy");
    }

    getData() {
      return super.getData();
    }

    render() {
      super.render();
      this.nodeEl.toggleClass("is-empty", this.width === 0 && this.height === 0);
    }
  }
  canvas.DummyNode = DummyNode;
  return DummyNode;
}

// ---- editable node (A5) -----------------------------------------------------------------------

function defineNg20EditableNode(host) {
  const Base = canvas.ContentMountNode || defineNg20ContentMountNode(host);
  class EditableNode extends Base {
    constructor(canvas_, id) {
      super(canvas_, id);
      this.alwaysKeepLoaded = true;
    }

    isEditable() { return true; }

    setIsEditing(editing) {
      this.isEditing = !!editing;
      this.nodeEl.toggleClass("is-editing", this.isEditing);
      this.contentBlockerEl.toggle(!this.isEditing);
      if (!this.isEditing) this.canvas.markDirty(this);
    }

    startEditing(point_) {
      this.setIsEditing(true);
      const child = this.child;
      if (child && typeof child.focus === "function") child.focus();
      else if (this.contentEl) this.contentEl.focus();
      void point_;
    }

    onDoubleClick(evt) {
      if (this.canvas.readonly || !this.isEditable()) return;
      if (evt.defaultPrevented) return;
      if (host.isEditableTarget(evt.targetNode)) return;
      this.startEditing({ x: evt.clientX, y: evt.clientY });
    }
  }
  canvas.EditableNode = EditableNode;
  return EditableNode;
}

// ---- text node (I5) ----------------------------------------------------------------------------

function defineNg20TextNode(host) {
  const Base = canvas.EditableNode || defineNg20EditableNode(host);
  class TextNode extends Base {
    constructor(canvas_, id) {
      super(canvas_, id);
      this.type = "text";
      this.text = "";
      this.editEl = null;
    }

    getData() {
      const out = super.getData();
      if (this.text) out.text = this.text;
      return out;
    }

    setData(data) {
      super.setData(data);
      if (typeof data.text === "string") {
        this.text = data.text;
        if (this.editEl) this.editEl.setText(this.text);
      }
    }

    setText(text) {
      this.text = text || "";
      this.canvas.markDirty(this);
      this.canvas.requestSave();
    }

    renderContent() {
      super.renderContent();
      const el = this.contentEl.createEl("div", { cls: "canvas-node-text", attr: { contenteditable: "true", spellcheck: "false" } });
      el.setText(this.text);
      this.editEl = el;
      el.addEventListener("input", () => this.setText(el.innerText));
      el.addEventListener("blur", () => this.setIsEditing(false));
      el.addEventListener("pointerdown", (evt) => evt.stopPropagation());
      el.addEventListener("keydown", (evt) => {
        evt.stopPropagation();
        if (evt.key === "Escape") { this.setIsEditing(false); el.blur(); }
      });
      if (this.isEditing) el.focus();
    }

    startEditing(point_) {
      super.startEditing(point_);
      if (this.editEl) {
        this.editEl.focus();
        host.focusAndSelectContents(this.editEl);
      }
      void point_;
    }

    setIsEditing(editing) {
      super.setIsEditing(editing);
      if (this.editEl) this.editEl.setAttribute("contenteditable", editing ? "true" : "false");
    }

    unmountContent() {
      this.editEl = null;
      super.unmountContent();
    }

    /** Converts the card's text into a new markdown file node. */
    async convertToFile() {
      const canvas_ = this.canvas;
      const app = this.app;
      const text = this.text || "";
      const base = (text.split("\n")[0] || "").trim().slice(0, 60) || "Untitled";
      const folder = canvas_.view && canvas_.view.file ? canvas_.view.file.parent : app.vault.getRoot();
      let path = base + ".md";
      let i = 1;
      while (app.vault.getAbstractFileByPath((folder && folder.path !== "/" ? folder.path + "/" : "") + path)) {
        path = base + " " + i++ + ".md";
      }
      const full = (folder && folder.path !== "/" ? folder.path + "/" : "") + path;
      try {
        const file = await app.vault.create(full, text);
        const node = canvas_.createFileNode({ pos: { x: this.x, y: this.y }, size: { width: this.width, height: this.height }, file, save: false, focus: false });
        canvas_.removeNode(this);
        canvas_.requestSave();
        return node;
      } catch (err) {
        console.error(err);
        return null;
      }
    }
  }
  canvas.TextNode = TextNode;
  return TextNode;
}

// ---- link node (F5) ----------------------------------------------------------------------------

function defineNg20LinkNode(host) {
  const Base = canvas.ContentMountNode || defineNg20ContentMountNode(host);
  class LinkNode extends Base {
    constructor(canvas_, id) {
      super(canvas_, id);
      this.type = "link";
      this.url = "";
      this.frameEl = null;
      this.pageTitle = "";
    }

    getData() {
      const out = super.getData();
      if (this.url) out.url = this.url;
      return out;
    }

    setData(data) {
      super.setData(data);
      if (typeof data.url === "string") this.setUrl(data.url, false);
    }

    setUrl(url, render = true) {
      let u = String(url || "");
      if (window.__fpUrl) u = window.__fpUrl(u);
      this.url = u;
      this.recreateFrame();
      this.updateNodeLabel(this.pageTitle || this.urlHost());
      if (render) this.canvas.markDirty(this);
    }

    urlHost() {
      try { return new URL(this.url).host; } catch (e) { return this.url; }
    }

    recreateFrame() {
      if (this.frameEl) { this.frameEl.remove(); this.frameEl = null; }
      if (!this.url) return;
      const wrap = this.contentEl;
      if (env().Yl.isMobile) {
        const framed = host.normalizeEmbedUrl ? host.normalizeEmbedUrl(this.url) : null;
        const f = wrap.createEl("iframe", { cls: "canvas-node-frame" });
        f.setAttr("src", framed || this.url);
        f.setAttr("sandbox", "allow-scripts allow-same-origin allow-forms allow-popups");
        this.frameEl = f;
      } else {
        const w = wrap.createEl("webview", { cls: "canvas-node-frame" });
        w.setAttr("src", this.url);
        w.setAttr("partition", "persist:canvas");
        w.addEventListener("page-title-updated", (evt) => {
          this.pageTitle = evt.title || "";
          this.updateNodeLabel(this.pageTitle || this.urlHost());
        });
        this.frameEl = w;
      }
    }

    setFrameUrl() {
      if (this.frameEl) this.frameEl.setAttr("src", this.url);
    }

    renderContent() {
      super.renderContent();
      this.recreateFrame();
      this.updateNodeLabel(this.pageTitle || this.urlHost());
    }

    unmountContent() {
      if (this.frameEl) { this.frameEl.remove(); this.frameEl = null; }
      super.unmountContent();
    }

    showMenu(evt) {
      const canvas_ = this.canvas;
      const menu = new host.Menu();
      const ti = env().gm.plugins.canvas;
      const self = this;
      menu.addSections(["title", "action", "danger"]);
      menu.addItem((item) => item.setSection("action").setTitle(ti.actionOpen ? ti.actionOpen() : "Open").setIcon("lucide-external-link").onClick(() => { window.open(self.url, "_blank"); }));
      menu.addItem((item) => item.setSection("action").setTitle(ti.actionCopyLink ? ti.actionCopyLink() : "Copy URL").setIcon("lucide-copy").onClick(() => copyText(self.url)));
      menu.addItem((item) => item.setSection("action").setTitle(ti.actionReload ? ti.actionReload() : "Reload").setIcon("lucide-rotate-cw").onClick(() => self.setFrameUrl()));
      if (!canvas_.readonly) {
        menu.addItem((item) => item.setSection("danger").setTitle(ti.actionRemove ? ti.actionRemove() : "Remove").setIcon("lucide-trash-2").setWarning(true).onClick(() => canvas_.removeNode(self)));
      }
      canvas_.app.workspace.trigger("canvas:node-menu", menu, this);
      if (window.__fpNodeMenu) window.__fpNodeMenu(menu, this);
      menu.showAtMouseEvent(evt);
    }
  }
  canvas.LinkNode = LinkNode;
  return LinkNode;
}

// ---- n-g20-select.js ----
// g20 clean-room: selection overlay + floating canvas menu.
//
// The controller keeps `selection` as a plain Set; the menu object (U3) owns the
// .canvas-selection overlay (8 [data-resize] handles) and the .canvas-menu-container
// popup, and exposes `selection.bbox` for viewport math. z3 is the standalone
// selection-state helper kept for API parity.
//
// Replaces orig z3 (canvas-selection) and U3 (canvas-menu).

const NG20_HANDLES = ["top", "topright", "right", "bottomright", "bottom", "bottomleft", "left", "topleft"];
const NG20_GROUP_BACKGROUNDS = ["", "solid", "translucent", "pattern"];

function ng20SelectionBBox(items) {
  const boxes = [];
  for (const item of items || []) {
    if (item && typeof item.getBBox === "function") {
      try { boxes.push(item.getBBox()); } catch (e) { /* detached */ }
    }
  }
  return boxes.length ? boxUnion(boxes) : null;
}

// ---- standalone selection helper (z3) ------------------------------------------------------------

function defineNg20CanvasSelection(host) {
  class CanvasSelection {
    constructor(canvas_) {
      this.canvas = canvas_;
      this.items = new Set();
    }

    get size() { return this.items.size; }
    has(item) { return this.items.has(item); }
    add(item) { this.items.add(item); }
    delete(item) { this.items.delete(item); }
    clear() { this.items.clear(); }
    values() { return this.items.values(); }
    [Symbol.iterator]() { return this.items[Symbol.iterator](); }

    get bbox() { return ng20SelectionBBox(this.items); }
  }
  canvas.CanvasSelection = CanvasSelection;
  return CanvasSelection;
}

// ---- floating menu + selection overlay (U3) -------------------------------------------------------

function defineNg20CanvasMenu(host) {
  class CanvasMenu {
    constructor(canvas_) {
      this.canvas = canvas_;
      this.selection = {
        get items() { return canvas_.selection; },
        get bbox() { return ng20SelectionBBox(canvas_.selection); },
        get size() { return canvas_.selection.size; },
      };
      this.selectionEl = null;
      this.handleEls = {};
      this.menuEl = null;
      this.submenuEl = null;
      this.renderedFor = null;
    }

    /** Frame-loop hook: rebuild overlay + popup when the selection changed. */
    render(force) {
      const canvas_ = this.canvas;
      const sel = canvas_.selection;
      const key = sel.size + ":" + [...sel].map((i) => i.id).join(",");
      if (!force && this.renderedFor === key) return;
      this.renderedFor = key;
      this.renderSelectionOverlay(sel);
      this.renderMenuPopup(sel);
    }

    // ---------- selection overlay ----------

    renderSelectionOverlay(sel) {
      const canvas_ = this.canvas;
      const b = ng20SelectionBBox(sel);
      const show = !!b && sel.size > 0 && !canvas_.readonly;
      if (!this.selectionEl) {
        this.selectionEl = createDiv("canvas-selection");
        this.selectionEl.hide();
        canvas_.canvasEl.appendChild(this.selectionEl);
        const handles = this.selectionEl.createDiv("canvas-selection-handles");
        for (const side of NG20_HANDLES) {
          const h = handles.createDiv(`canvas-selection-handle mod-${side}`);
          h.setAttr("data-resize", side);
          h.addEventListener("pointerdown", (evt) => this.onHandlePointerdown(evt, side));
          this.handleEls[side] = h;
        }
      }
      this.selectionEl.toggle(show);
      if (!show) return;
      this.selectionEl.style.left = b.minX + "px";
      this.selectionEl.style.top = b.minY + "px";
      this.selectionEl.style.width = (b.maxX - b.minX) + "px";
      this.selectionEl.style.height = (b.maxY - b.minY) + "px";
    }

    onHandlePointerdown(evt, side) {
      if (evt.button !== 0 || !evt.isPrimary || this.canvas.readonly) return;
      evt.preventDefault();
      evt.stopPropagation();
      const canvas_ = this.canvas;
      const start = canvas_.posFromEvt(evt);
      const origin = new Map();
      for (const item of canvas_.selection) {
        if (item && item.rect) origin.set(item, { x: item.x, y: item.y, width: item.width, height: item.height });
      }
      const minDim = (canvas_.config && canvas_.config.minContainerDimension) || 50;
      host.dragWithThreshold(evt, () => ({
        move: (moveEvt) => {
          const p = canvas_.posFromEvt(moveEvt);
          const dx = p.x - start.x;
          const dy = p.y - start.y;
          const horiz = side.includes("left") || side.includes("right");
          const vert = side.startsWith("top") || side.startsWith("bottom");
          for (const [item, o] of origin) {
            if (!item.moveAndResize) continue;
            let { x, y, width, height } = o;
            if (horiz && side.includes("left")) { x = o.x + dx; width = o.width - dx; }
            else if (horiz) { width = o.width + dx; }
            if (vert && side.startsWith("top")) { y = o.y + dy; height = o.height - dy; }
            else if (vert) { height = o.height + dy; }
            if (width < minDim) width = minDim;
            if (height < minDim) height = minDim;
            item.moveAndResize({ x, y, width, height });
          }
        },
        end: () => canvas_.requestSave(),
      }), 0);
    }

    // ---------- floating menu ----------

    renderMenuPopup(sel) {
      const canvas_ = this.canvas;
      const show = sel.size > 0;
      if (!this.menuEl) {
        this.menuEl = createDiv("canvas-menu-container");
        this.menuEl.hide();
        canvas_.canvasEl.appendChild(this.menuEl);
      }
      this.menuEl.toggle(show);
      if (!show) { this.menuEl.empty(); return; }
      // rebuild only when the selection signature changed (renderedFor already gates)
      this.menuEl.empty();
      const ti = ng20CanvasStrings();
      const nodes = [...sel].filter((i) => i && i.moveAndResize);
      const groups = nodes.filter((n) => n.type === "group");
      const btn = (cls, icon, title, fn) => {
        const b = this.menuEl.createDiv(`canvas-menu-button ${cls}`);
        b.setAttr("aria-label", title);
        b.setAttr("title", title);
        if (icon) { const ic = b.createDiv("canvas-menu-icon"); try { window.__bsApi.setIcon(ic, "lucide-" + icon); } catch (e) { ic.setText(icon); } }
        b.addEventListener("click", (evt) => { evt.stopPropagation(); fn(); });
        return b;
      };
      btn("canvas-menu-color", "palette", ti.menuColor ? ti.menuColor() : "Color", () => this.openSubmenu("color"));
      btn("canvas-menu-align", "align-left", ti.menuAlign ? ti.menuAlign() : "Align", () => this.openSubmenu("align"));
      btn("canvas-menu-arrange", "layout-grid", ti.menuArrange ? ti.menuArrange() : "Arrange", () => this.openSubmenu("arrange"));
      btn("canvas-menu-distribute", "distribute-horizontal", ti.menuDistribute ? ti.menuDistribute() : "Distribute", () => this.openSubmenu("distribute"));
      btn("canvas-menu-justify", "align-horizontal-distribute-center", ti.menuJustify ? ti.menuJustify() : "Justify", () => this.openSubmenu("justify"));
      btn("canvas-menu-direction", "arrow-right", ti.menuEdgeDirection ? ti.menuEdgeDirection() : "Edge direction", () => this.openSubmenu("direction"));
      btn("canvas-menu-background", "image", ti.menuBackground ? ti.menuBackground() : "Background", () => this.openSubmenu("background"));
      // position near the selection box, inside canvas coordinates
      const b = this.selection.bbox;
      if (b) {
        this.menuEl.style.left = ((b.minX + b.maxX) / 2) + "px";
        this.menuEl.style.top = (b.maxY + 8) + "px";
        this.menuEl.style.transform = "translateX(-50%)";
      }
    }

    openSubmenu(kind) {
      this.closeSubmenu();
      const sub = createDiv("canvas-menu-submenu");
      const canvas_ = this.canvas;
      const ti = ng20CanvasStrings();
      const add = (label, fn) => {
        const row = sub.createDiv("canvas-menu-submenu-item");
        row.setText(label);
        row.addEventListener("click", (evt) => { evt.stopPropagation(); this.closeSubmenu(); fn(); });
      };
      if (kind === "color") {
        for (const c of ["", "1", "2", "3", "4", "5", "6", "#e03131", "#2f9e44", "#1971c2", "#f08c00", "#ae3ec9"]) {
          add(c === "" ? (ti.colorNone || "None") : c, () => {
            for (const item of canvas_.selection) if (item && item.setColor) item.setColor(c);
            canvas_.requestSave();
          });
        }
      } else if (kind === "align") {
        const ops = [
          ["left", ti.alignLeft], ["center-h", ti.alignCenter], ["right", ti.alignRight],
          ["top", ti.alignTop], ["center-v", ti.alignMiddle], ["bottom", ti.alignBottom],
        ];
        for (const [k, labelFn] of ops) add(labelFn ? labelFn() : k, () => this.align(k));
      } else if (kind === "arrange") {
        const ops = [["grid", ti.arrangeGrid], ["row", ti.arrangeRow], ["column", ti.arrangeColumn]];
        for (const [k, labelFn] of ops) add(labelFn ? labelFn() : k, () => this.distribute(k));
      } else if (kind === "distribute") {
        const ops = [["row", ti.distributeRow || "Row"], ["column", ti.distributeColumn || "Column"]];
        for (const [k, labelFn] of ops) add(labelFn, () => this.distribute(k));
      } else if (kind === "justify") {
        const ops = [["left", ti.justifyLeft], ["center", ti.justifyCenter], ["right", ti.justifyRight], ["space-between", ti.justifySpace]];
        for (const [k, labelFn] of ops) add(labelFn ? labelFn() : k, () => this.justify(k));
      } else if (kind === "direction") {
        const ops = [["right", ti.directionRight], ["left", ti.directionLeft], ["down", ti.directionDown], ["up", ti.directionUp]];
        for (const [k, labelFn] of ops) add(labelFn ? labelFn() : k, () => this.setEdgeDirection(k));
      } else if (kind === "background") {
        for (const bg of NG20_GROUP_BACKGROUNDS) {
          add(bg === "" ? (ti.bgNone || "None") : bg, () => this.setGroupBackground(bg));
        }
      }
      this.menuEl.appendChild(sub);
      this.submenuEl = sub;
    }

    closeSubmenu() {
      if (this.submenuEl) { this.submenuEl.remove(); this.submenuEl = null; }
    }

    selectedNodes() {
      return [...this.canvas.selection].filter((i) => i && i.rect);
    }

    align(mode) {
      const nodes = this.selectedNodes();
      if (nodes.length < 2) return;
      const boxes = nodes.map((n) => n.getBBox());
      const all = boxes.reduce((a, b) => ({
        minX: Math.min(a.minX, b.minX), minY: Math.min(a.minY, b.minY),
        maxX: Math.max(a.maxX, b.maxX), maxY: Math.max(a.maxY, b.maxY),
      }));
      const cCX = (all.minX + all.maxX) / 2, cCY = (all.minY + all.maxY) / 2;
      for (let i = 0; i < nodes.length; i++) {
        const n = nodes[i], b = boxes[i];
        const cx = (b.minX + b.maxX) / 2, cy = (b.minY + b.maxY) / 2;
        let dx = 0, dy = 0;
        if (mode === "left") dx = all.minX - b.minX;
        else if (mode === "right") dx = all.maxX - b.maxX;
        else if (mode === "center-h") dx = cCX - cx;
        else if (mode === "top") dy = all.minY - b.minY;
        else if (mode === "bottom") dy = all.maxY - b.maxY;
        else if (mode === "center-v") dy = cCY - cy;
        if (dx || dy) n.moveTo({ x: n.x + dx, y: n.y + dy });
      }
      this.canvas.requestSave();
    }

    distribute(kind) {
      const nodes = this.selectedNodes();
      if (nodes.length < 2) return;
      const boxes = nodes.map((n) => n.getBBox());
      if (kind === "grid") {
        const cols = Math.ceil(Math.sqrt(nodes.length));
        const minX = Math.min(...boxes.map((b) => b.minX));
        const minY = Math.min(...boxes.map((b) => b.minY));
        const maxX = Math.max(...boxes.map((b) => b.maxX));
        const maxY = Math.max(...boxes.map((b) => b.maxY));
        const rows = Math.ceil(nodes.length / cols);
        nodes.forEach((n, i) => {
          const col = i % cols, row = Math.floor(i / cols);
          n.moveTo({ x: minX + col * ((maxX - minX) / cols), y: minY + row * ((maxY - minY) / Math.max(1, rows)) });
        });
      } else {
        const horizontal = kind !== "column";
        const items = nodes.map((n, i) => ({ n, b: boxes[i] })).sort((a, b2) => horizontal ? a.b.minX - b2.b.minX : a.b.minY - b2.b.minY);
        const min = horizontal ? Math.min(...boxes.map((b) => b.minX)) : Math.min(...boxes.map((b) => b.minY));
        const max = horizontal ? Math.max(...boxes.map((b) => b.maxX)) : Math.max(...boxes.map((b) => b.maxY));
        const total = items.reduce((s, it) => s + (horizontal ? it.b.maxX - it.b.minX : it.b.maxY - it.b.minY), 0);
        const gap = items.length > 1 ? (max - min - total) / (items.length - 1) : 0;
        let cursor = min;
        for (const it of items) {
          if (horizontal) it.n.moveTo({ x: cursor, y: it.n.y });
          else it.n.moveTo({ x: it.n.x, y: cursor });
          cursor += (horizontal ? it.b.maxX - it.b.minX : it.b.maxY - it.b.minY) + gap;
        }
      }
      this.canvas.requestSave();
    }

    justify(mode) {
      const nodes = this.selectedNodes().sort((a, b) => a.x - b.x);
      if (nodes.length < 2) return;
      const boxes = nodes.map((n) => n.getBBox());
      const minX = Math.min(...boxes.map((b) => b.minX));
      const maxX = Math.max(...boxes.map((b) => b.maxX));
      const totalW = boxes.reduce((s, b) => s + (b.maxX - b.minX), 0);
      if (mode === "space-between" && nodes.length > 2) {
        const gap = (maxX - minX - totalW) / (nodes.length - 1);
        let cx = minX;
        nodes.forEach((n, i) => {
          n.moveTo({ x: cx, y: n.y });
          cx += (boxes[i].maxX - boxes[i].minX) + gap;
        });
      } else if (mode === "center") {
        const mid = (minX + maxX) / 2;
        for (let i = 0; i < nodes.length; i++) {
          const cx = (boxes[i].minX + boxes[i].maxX) / 2;
          nodes[i].moveTo({ x: nodes[i].x + (mid - cx), y: nodes[i].y });
        }
      } else if (mode === "left") {
        for (let i = 0; i < nodes.length; i++) nodes[i].moveTo({ x: nodes[i].x + (minX - boxes[i].minX), y: nodes[i].y });
      } else if (mode === "right") {
        for (let i = 0; i < nodes.length; i++) nodes[i].moveTo({ x: nodes[i].x + (maxX - boxes[i].maxX), y: nodes[i].y });
      }
      this.canvas.requestSave();
    }

    setEdgeDirection(dir) {
      const nodes = this.selectedNodes();
      if (nodes.length < 2) return;
      const nodeSet = new Set(nodes);
      const map = { right: ["left", "right"], left: ["right", "left"], down: ["top", "bottom"], up: ["bottom", "top"] };
      const [fromSide, toSide] = map[dir];
      let changed = false;
      for (const e of this.canvas.edges.values()) {
        if (!e || !e.from || !e.to) continue;
        const fa = nodeSet.has(e.from.node), ta = nodeSet.has(e.to.node);
        if (fa === ta) continue; // both-in or both-out: leave internal/untouched edges alone
        if (fa) { e.from.side = fromSide; changed = true; }
        if (ta) { e.to.side = toSide; changed = true; }
        if (fa || ta) { e.update && e.update(); this.canvas.markMoved(e); }
      }
      if (changed) this.canvas.requestSave();
    }

    setGroupBackground(bg) {
      const canvas_ = this.canvas;
      let touched = false;
      for (const item of canvas_.selection) {
        if (item && item.type === "group") {
          item.background = bg;
          item.render && item.render();
          touched = true;
        }
      }
      if (!touched) {
        const nodes = this.selectedNodes();
        if (nodes.length === 0 || !canvas_.createGroupNode) return;
        const b = ng20SelectionBBox(nodes);
        if (!b) return;
        const g = canvas_.createGroupNode({
          pos: { x: b.minX - 20, y: b.minY - 20 },
          size: { width: b.maxX - b.minX + 40, height: b.maxY - b.minY + 60 },
          save: false, focus: false,
        });
        g.background = bg;
        g.render();
      }
      canvas_.requestSave();
    }
  }
  canvas.CanvasMenu = CanvasMenu;
  return CanvasMenu;
}

// ---- n-g20-shared.js ----
// g20 clean-room shared pieces: the `canvas` class registry the controller copies onto
// itself, the canvas/plugin i18n table accessors, frozen canvas constants and tiny helpers
// shared by the node/edge/selection/menu modules of this slice.

/** Registry populated by every canvas class factory; the controller copies its keys onto itself. */
const canvas = {};

// ---- frozen constants (contract: plugins/themes read these exact values) --------------------

const ng20EdgeEndRotation = { top: "180", bottom: "0", left: "90", right: "270" };
const ng20EdgeEndNone = "none";
const ng20EdgeEndArrow = "arrow";
const ng20CanvasViewType = "canvas";
const ng20CanvasExtension = "canvas";
const ng20FileExplorerViewType = "file-explorer";
const ng20DefaultDateFormat = "YYYY-MM-DD";
const ng20RecoveryDefaults = { intervalMinutes: 5, keepDays: 7 };

// ---- lazy i18n table accessors --------------------------------------------------------------

function ng20InterfaceStrings() { return env().gm.interface; }
function ng20CanvasStrings() { return env().gm.plugins.canvas; }
function ng20DailyNotesStrings() { return env().gm.plugins.dailyNotes; }
function ng20FileExplorerStrings() { return env().gm.plugins.fileExplorer; }
function ng20FileRecoveryStrings() { return env().gm.plugins.fileRecovery; }
function ng20EditorStatusStrings() { return env().gm.plugins.editorStatus; }
function ng20SyncStrings() { return env().gm.plugins.sync; }

// ---- small shared helpers ---------------------------------------------------------------------

/** True for a finite number (geometry inputs ignore anything else). */
function ng20Finite(v) { return typeof v === "number" && isFinite(v); }

/** Rounds a possibly-missing numeric field, keeping the fallback when invalid. */
function ng20RoundOr(v, fallback) {
  return ng20Finite(v) ? Math.round(v) : fallback;
}

const NG20_SIDES = ["top", "right", "bottom", "left"];
function ng20Sides() { return NG20_SIDES; }

/** Deterministic tie order for direction picking: horizontal wins exact ties. */
function ng20DominantAxis(dx, dy) {
  return Math.abs(dx) >= Math.abs(dy) ? "x" : "y";
}

/** Serialises canvas data the way the view expects: pretty JSON, tab indent. */
function ng20Serialize(data, host) {
  return host.canvasSerialize(data);
}

// ---- n-g20-utils.js ----
// g20 clean-room: undo stack, spatial index family, per-file canvas view-data
// cache (localStorage) and the node interaction layer (resize handles / dots).
//
// Replaces orig l5/Y3/m5/v5/g5/n8/M5 (canvas-utils.js).

// ---- undo stack (l5) --------------------------------------------------------------------------

function defineNg20UndoStack() {
  class UndoStack {
    constructor(max = 100) {
      this.data = [];
      this.current = -1;
      this.max = max;
    }

    get length() { return this.data.length; }

    canUndo() { return this.current > 0; }
    canRedo() { return this.current < this.data.length - 1; }

    /** Appends a state, dropping the redo tail first; bounds the stack to max-1 entries. */
    push(state) {
      this.data = this.data.slice(0, this.current + 1);
      this.data.push(state);
      this.current = this.data.length - 1;
      if (this.data.length >= this.max) {
        this.data.shift();
        this.current--;
      }
    }

    /** Overwrites the entry under the pointer, or appends when the stack is empty. */
    replace(state) {
      if (this.data.length === 0) {
        this.data.push(state);
        this.current = 0;
        return;
      }
      this.data[this.current] = state;
    }

    undo() {
      if (!this.canUndo()) return null;
      this.current--;
      return this.data[this.current];
    }

    redo() {
      if (!this.canRedo()) return null;
      this.current++;
      return this.data[this.current];
    }

    clear() {
      this.data = [];
      this.current = -1;
    }
  }
  canvas.UndoStack = UndoStack;
  return UndoStack;
}

// ---- spatial index family ----------------------------------------------------------------------
// One generic 2D index parameterised by how an item's bbox is obtained and how ties order.

function ng20ItemBBox(item, accessor) {
  if (accessor === "bbox") return item.bbox;
  if (accessor === "getBBox") return item.getBBox();
  return item.bbox !== undefined ? item.bbox : item.getBBox();
}

function ng20Intersects(a, b) {
  return a.minX <= b.maxX && a.maxX >= b.minX && a.minY <= b.maxY && a.maxY >= b.minY;
}

class Ng20SpatialIndex {
  constructor(opts = {}) {
    this.accessor = opts.accessor || "getBBox";
    this.order = opts.order || null; // optional comparator for search results
    this.items = [];
  }

  toBBox(item) { return ng20ItemBBox(item, this.accessor); }

  all() { return this.items.slice(); }

  insert(item) {
    if (this.items.includes(item)) return;
    this.items.push(item);
  }

  remove(item, equals) {
    const eq = equals || ((a, b) => a === b);
    for (let i = this.items.length - 1; i >= 0; i--) {
      if (eq(this.items[i], item)) this.items.splice(i, 1);
    }
  }

  clear() { this.items = []; }

  load(items) {
    this.items = [];
    for (const item of items || []) this.insert(item);
  }

  search(bbox) {
    const out = [];
    for (const item of this.items) {
      const b = this.toBBox(item);
      if (b && ng20Intersects(b, bbox)) out.push(item);
    }
    if (this.order) out.sort(this.order);
    return out;
  }

  collides(bbox) {
    for (const item of this.items) {
      const b = this.toBBox(item);
      if (b && ng20Intersects(b, bbox)) return true;
    }
    return false;
  }

  toJSON() { return this.items.map((i) => this.toBBox(i)); }
  fromJSON(data) {
    this.items = [];
    for (const b of data || []) this.items.push({ bbox: b, getBBox() { return this.bbox; } });
  }
}

/** Uniform-grid flavour kept for API parity: same contract, insertion-order ties. */
function defineNg20SpatialIndex() {
  class SpatialIndex extends Ng20SpatialIndex {
    constructor() { super({ accessor: "getBBox" }); }
  }
  canvas.SpatialIndex = SpatialIndex;
  return SpatialIndex;
}

/** Caches `item.bbox` on insert; `update(item)` refreshes a moved item. */
function defineNg20BboxCachedIndex() {
  class BboxIndex extends Ng20SpatialIndex {
    constructor() { super({ accessor: "bbox" }); }
    insert(item) {
      item.bbox = item.getBBox();
      super.insert(item);
    }
    update(item) {
      this.remove(item);
      this.insert(item);
    }
    remove(item, equals) {
      const eq = equals || ((a, b) => a === b);
      for (let i = this.items.length - 1; i >= 0; i--) {
        if (eq(this.items[i], item)) {
          this.items[i].bbox = undefined;
          this.items.splice(i, 1);
        }
      }
    }
  }
  canvas.BboxIndex = BboxIndex;
  return BboxIndex;
}

/** Orders items by (x, y): degenerate-box queries return hits sorted y-then-x. */
function defineNg20PointIndex() {
  class PointIndex extends Ng20SpatialIndex {
    constructor() {
      super({
        accessor: "bbox",
        order: (a, b) => (a.y !== b.y ? a.y - b.y : a.x - b.x),
      });
    }
    insert(item) {
      item.bbox = box(item.x, item.y, item.x, item.y);
      super.insert(item);
    }
    search(bbox) {
      const out = super.search(bbox);
      out.sort((a, b) => (a.y !== b.y ? a.y - b.y : a.x - b.x));
      return out;
    }
  }
  canvas.PointIndex = PointIndex;
  return PointIndex;
}

/** Orders by getBBox() min corner — the default node/edge index. */
function defineNg20BBoxItemIndex() {
  class BBoxItemIndex extends Ng20SpatialIndex {
    constructor() { super({ accessor: "getBBox" }); }
  }
  canvas.BBoxItemIndex = BBoxItemIndex;
  return BBoxItemIndex;
}

// ---- canvas view-local data cache (n8) ---------------------------------------------------------
// Stores at most view-local flags (today: {readonly:true}) under "<appId>-canvas-<path>".

function defineNg20CanvasDataCache(host) {
  class CanvasDataCache {
    constructor(app) {
      this.app = app;
    }

    keyFor(path) { return this.app.appId + "-canvas-" + path; }

    load(file) {
      if (!file) return null;
      let raw = null;
      try { raw = window.localStorage.getItem(this.keyFor(file.path)); } catch (e) { return null; }
      if (raw == null) return null;
      try {
        const data = JSON.parse(raw);
        return data && typeof data === "object" ? data : null;
      } catch (err) {
        return null;
      }
    }

    save(file, data) {
      if (!file) return;
      const key = this.keyFor(file.path);
      try {
        if (data == null) window.localStorage.removeItem(key);
        else window.localStorage.setItem(key, JSON.stringify(data));
      } catch (e) { /* storage full/blocked -> ignore */ }
    }

    remove(path) {
      try { window.localStorage.removeItem(this.keyFor(path)); } catch (e) { /* ignore */ }
    }

    handleRename(oldPath, newFile) {
      let raw = null;
      try { raw = window.localStorage.getItem(this.keyFor(oldPath)); } catch (e) { return; }
      if (raw != null) {
        try {
          window.localStorage.setItem(this.keyFor(newFile.path), raw);
          window.localStorage.removeItem(this.keyFor(oldPath));
        } catch (e) { /* ignore */ }
      }
    }

    handleDelete(file) {
      if (file) this.remove(file.path);
    }
  }
  canvas.DataCache = CanvasDataCache;
  return CanvasDataCache;
}

// ---- node interaction layer (M5) ---------------------------------------------------------------
// Overlay over the hovered node: four side connection dots + resize handles.

function defineNg20InteractionLayer(host) {
  class NodeInteractionLayer {
    constructor(canvas_) {
      this.canvas = canvas_;
      this.target = null;
      this.interactionEl = createDiv("canvas-node-interaction-layer");
      this.dotsEl = this.interactionEl.createDiv("canvas-node-interaction-layer-dots");
      this.handlesEl = this.interactionEl.createDiv("canvas-node-interaction-layer-handles");
      this.interactionEl.hide();
      canvas_.canvasEl.appendChild(this.interactionEl);
      this.buildDots();
    }

    buildDots() {
      for (const side of ["top", "right", "bottom", "left"]) {
        const dot = this.dotsEl.createDiv(`canvas-node-interaction-dot mod-${side}`);
        dot.setAttr("data-side", side);
        dot.addEventListener("pointerdown", (evt) => {
          if (this.target) this.target.onConnectionPointerdown(evt, side);
        });
      }
      for (const side of ["top", "right", "bottom", "left", "topleft", "topright", "bottomleft", "bottomright"]) {
        const handle = this.handlesEl.createDiv(`canvas-node-interaction-handle mod-resize-${side}`);
        handle.setAttr("data-resize", side);
        handle.addEventListener("pointerdown", (evt) => {
          if (this.target && !this.canvas.readonly) this.target.onResizePointerdown(evt, side);
        });
        handle.addEventListener("dblclick", (evt) => {
          if (this.target) this.target.onResizeDblclick(evt);
        });
      }
    }

    setTarget(node) {
      if (this.target === node) return;
      this.target = node;
      this.render();
    }

    render() {
      const node = this.target;
      const show = !!node && !this.canvas.readonly && !node.destroyed;
      this.interactionEl.toggle(show);
      if (!show) return;
      const b = node.getBBox();
      this.interactionEl.style.left = b.minX + "px";
      this.interactionEl.style.top = b.minY + "px";
      this.interactionEl.style.width = (b.maxX - b.minX) + "px";
      this.interactionEl.style.height = (b.maxY - b.minY) + "px";
      this.handlesEl.toggle(!node.isEditable || node.width > 30);
    }
  }
  canvas.InteractionLayer = NodeInteractionLayer;
  return NodeInteractionLayer;
}

// ---- n-g24-composer.js ----
// The "Note composer" core plugin: merge one note into another, or extract a selection /
// a whole heading into a new note.
//
// Replaces the inherited pieces:
//   Z8  NoteComposerPlugin        -> defineNoteComposerPlugin
//   J8  MergeFileSuggest          -> defineMergeFileSuggest   (base: quick-switcher modal)
//   e7  ExtractFileSuggest        -> defineExtractFileSuggest (base: quick-switcher modal)
//   t7  NoteComposerSettingTab    -> defineNoteComposerSettingTab (base: plugin setting tab)
//   $8  gm.plugins.noteComposer   -> declarator __basaltHost.t.plugins.noteComposer
//
// Options persisted through the plugin instance: askBeforeMerging, replacementText ("link" |
// "embed" | "none") and an optional template file whose {{content}}/{{fromTitle}}/{{newTitle}}/
// {{date:...}} variables are expanded on merge/extract.


const composerT = (host) => host.t.plugins.noteComposer;

// The plugin and the suggest/settings factories run at different bundle positions; they reach
// each other through this registry.
const composerParts = {};

const REPLACEMENT_LINK = "link";
const REPLACEMENT_EMBED = "embed";
const REPLACEMENT_NONE = "none";

/** Modal asking which file the current note should be merged into (or a new file created). */
function defineMergeFileSuggest(host) {
  function MergeFileSuggest(app, composer) {
    const self = host.s13QuickSwitcherModalBase.call(this, app) || this;
    self.currentFile = null;
    self.emptyStateText = composerT(host).labelNoFiles();
    self.composer = composer;
    self.shouldShowNonImageAttachments = false;
    self.shouldShowImages = false;
    self.shouldShowNonAttachments = false;
    self.setPlaceholder(composerT(host).promptSelectFileToMerge());
    self.setInstructions([
      { command: "↑↓", purpose: composerT(host).instructionNavigate() },
      { command: "↵", purpose: composerT(host).instructionMerge() },
      { command: host.isMacLike ? "cmd ↵" : "ctrl ↵", purpose: composerT(host).instructionCreateNew() },
      { command: "shift ↵", purpose: composerT(host).instructionMergeAtTop() },
      { command: "esc", purpose: composerT(host).instructionDismiss() },
    ]);
    self.scope.register(["Shift"], "Enter", (event) => { self.selectActiveSuggestion(event); return false; });
    self.scope.register(["Mod"], "Enter", (event) => { self.selectActiveSuggestion(event); return false; });
    return self;
  }
  inherit(MergeFileSuggest, host.s13QuickSwitcherModalBase);
  const proto = MergeFileSuggest.prototype;

  proto.setCurrentFile = function (file) {
    this.currentFile = file;
  };

  proto.onChooseSuggestion = async function (suggestion, evt) {
    const app = this.app;
    const input = this.inputEl.value;
    let target;
    // Mod+Enter or no suggestion: create a new file from the typed name.
    if (host.Keymap.isModifier(evt, "Mod") || !suggestion || suggestion.type === "unresolved") {
      const linktext = suggestion && suggestion.type === "unresolved" ? suggestion.linktext : input;
      const parent = app.fileManager.getNewFileParent(this.currentFile.path, linktext);
      try {
        target = await app.fileManager.createNewMarkdownFile(parent, linktext);
      } catch (error) {
        new host.Notice(error.toString());
        return;
      }
    } else if (suggestion.type === "bookmark") {
      if (suggestion.item.type === "file") {
        const file = app.vault.getAbstractFileByPath(suggestion.item.path);
        if (file instanceof host.TFile) target = file;
      }
    } else {
      target = suggestion.file;
    }
    if (!target || target === this.currentFile) return;
    const source = this.currentFile;
    const composer = this.composer;
    let skipConfirm = false;
    const doMerge = async () => {
      if (skipConfirm) {
        composer.options.askBeforeMerging = false;
        composer.pluginInstance.saveData(composer.options);
      }
      await this.mergeFile(target, source, evt.shiftKey ? "prepend" : "append");
    };
    if (composer.options.askBeforeMerging) {
      const content = document.createDocumentFragment();
      content.createEl("p", {
        text: composerT(host).labelConfirmFileMerge({ file: source.basename, destination: target.basename }),
      });
      const modal = new host.ButtonModal(app).setTitle(composerT(host).labelMergeFile()).setContent(content);
      if (!host.Platform.isMobile) {
        modal.addCheckbox(host.t.dialogue.labelDoNotAskAgain(), (cb) => {
          skipConfirm = cb.target.checked;
        });
      }
      modal
        .addButton("mod-warning", composerT(host).buttonMerge(), () => doMerge())
        .addCancelButton()
        .open();
    } else {
      await doMerge();
    }
  };

  /** Reads the source, expands the template, writes into the target, trashes the source, opens the target. */
  proto.mergeFile = async function (target, source, position = "append") {
    const app = this.app;
    const fileManager = app.fileManager;
    const content = await app.vault.read(source);
    const merged = await this.composer.applyTemplate(content, source.basename, target.basename);
    await fileManager.runAsyncLinkUpdate(async (links) => {
      await fileManager.insertIntoFile(target, merged, position);
      await fileManager.trashFile(source);
      if (links) {
        for (const link of links) {
          if (link.resolvedFile === source) {
            link.resolvedFile = target;
            link.resolvedPaths = [];
          }
        }
      }
    });
    await app.workspace.getLeaf().openFile(target);
  };

  composerParts.MergeFileSuggest = MergeFileSuggest;
  return MergeFileSuggest;
}

/** Modal asking which file the current selection (or heading) should be extracted into. */
function defineExtractFileSuggest(host) {
  function ExtractFileSuggest(app, editor, composer, heading) {
    const self = host.s13QuickSwitcherModalBase.call(this, app) || this;
    self.defaultValue = "";
    self.allowCreateNewFile = true;
    self.editor = editor;
    self.composer = composer;
    self.shouldShowUnresolved = true;
    self.shouldShowNonImageAttachments = false;
    self.shouldShowImages = false;
    self.shouldShowNonAttachments = false;
    if (!heading) {
      const firstLine = editor.getSelection().split("\n");
      if (firstLine.length > 0) heading = firstHeadingText(firstLine[0]);
    }
    self.defaultValue = heading || "";
    self.setPlaceholder(composerT(host).promptSelectFileToMerge());
    self.setInstructions([
      { command: "↑↓", purpose: composerT(host).instructionNavigate() },
      { command: "↵", purpose: composerT(host).instructionAppend() },
      { command: host.isMacLike ? "cmd ↵" : "ctrl ↵", purpose: composerT(host).instructionCreateNew() },
      { command: "shift ↵", purpose: composerT(host).instructionPrepend() },
      { command: "esc", purpose: composerT(host).instructionDismiss() },
    ]);
    self.scope.register(["Shift"], "Enter", (event) => { self.selectActiveSuggestion(event); return false; });
    self.scope.register(["Mod"], "Enter", (event) => { self.selectActiveSuggestion(event); return false; });
    return self;
  }
  inherit(ExtractFileSuggest, host.s13QuickSwitcherModalBase);
  const proto = ExtractFileSuggest.prototype;

  proto.onOpen = function () {
    host.s13QuickSwitcherModalBase.prototype.onOpen.call(this);
    this.inputEl.value = this.defaultValue;
    this.updateSuggestions();
  };

  proto.setCurrentFile = function (file) {
    this.currentFile = file;
  };

  proto.onChooseSuggestion = async function (suggestion, evt) {
    const app = this.app;
    const selection = this.editor.getSelection();
    const createNew = host.Keymap.isModifier(evt, "Mod");
    const source = this.currentFile;
    let target;
    try {
      if (createNew || !suggestion) {
        target = await app.fileManager.createNewMarkdownFileFromLinktext(this.inputEl.value, source.path);
      } else if (suggestion.type === "unresolved") {
        target = await app.fileManager.createNewMarkdownFileFromLinktext(suggestion.linktext, source.path);
      } else if (suggestion.type === "file" || suggestion.type === "alias") {
        target = suggestion.file;
      }
    } catch (error) {
      new host.Notice(error.toString());
      return;
    }
    const content = await this.composer.applyTemplate(selection, source.basename, target.basename);
    await app.fileManager.insertIntoFile(target, content, evt.shiftKey ? "prepend" : "append");
    const link = app.fileManager.generateMarkdownLink(target, source.path);
    const mode = this.composer.options.replacementText;
    if (mode === REPLACEMENT_EMBED) this.editor.replaceSelection("!" + link);
    else if (mode === REPLACEMENT_NONE) this.editor.replaceSelection("");
    else this.editor.replaceSelection(link);
  };

  composerParts.ExtractFileSuggest = ExtractFileSuggest;
  return ExtractFileSuggest;
}

/** Settings tab: replacement text after extraction, template file, merge confirmation. */
function defineNoteComposerSettingTab(host) {
  function NoteComposerSettingTab(app, plugin, instance) {
    const self = host.PluginInstanceSettingTab.call(this, app, plugin) || this;
    self.icon = "merge";
    self.instance = instance;
    return self;
  }
  inherit(NoteComposerSettingTab, host.PluginInstanceSettingTab);
  const proto = NoteComposerSettingTab.prototype;

  proto.display = function () {
    const self = this;
    const containerEl = this.containerEl;
    containerEl.empty();
    const options = this.instance.options;
    new host.SettingGroup(containerEl)
      .addSetting((setting) =>
        setting
          .setName(composerT(host).optionSplitReplacementText())
          .setDesc(composerT(host).optionSplitReplacementTextDescription())
          .addDropdown((dropdown) => {
            dropdown
              .addOption(REPLACEMENT_LINK, composerT(host).optionChoiceSplitReplacementTextLink())
              .addOption(REPLACEMENT_EMBED, composerT(host).optionChoiceSplitReplacementTextEmbed())
              .addOption(REPLACEMENT_NONE, composerT(host).optionChoiceSplitReplacementTextNone())
              .setValue(options.replacementText || REPLACEMENT_LINK)
              .onChange((value) => {
                options.replacementText = value;
                self.plugin.saveData(options);
              });
          })
      )
      .addSetting((setting) =>
        setting
          .setName(composerT(host).optionTemplateFile())
          .setDesc(composerT(host).optionTemplateFileDescription({ interpolation: { prefix: "{{{{", suffix: "}}}}" } }))
          .addText((text) => {
            text
              .setPlaceholder(host.t.setting.filePathExamplePlaceholder())
              .setValue(options.template)
              .onChange((value) => {
                options.template = value.trim();
                self.plugin.saveData(options);
              });
            new host.MarkdownFileSuggest(self.app, text.inputEl);
          })
      )
      .addSetting((setting) =>
        setting
          .setName(composerT(host).optionConfirmFileMerge())
          .setDesc(composerT(host).optionConfirmFileMergeDescription())
          .addToggle((toggle) => {
            toggle
              .setValue(options.askBeforeMerging)
              .onChange((value) => {
                options.askBeforeMerging = value;
                self.plugin.saveData(options);
              });
          })
      );
  };

  composerParts.NoteComposerSettingTab = NoteComposerSettingTab;
  return NoteComposerSettingTab;
}

/** The plugin shell: registers the three commands, the file/editor menu entries and the settings tab. */
function defineNoteComposerPlugin(host) {
  const t = composerT(host);

  class NoteComposerPlugin {
    constructor() {
      this.id = "note-composer";
      this.name = t.name();
      this.description = t.desc();
      this.defaultOn = true;
      this.options = {};
      this.app = null;
      this.pluginInstance = null;
    }

    init(app, plugin) {
      const self = this;
      this.app = app;
      this.pluginInstance = plugin;
      plugin.registerGlobalCommand({
        id: "note-composer:merge-file",
        name: t.commandMergeFile(),
        icon: "lucide-git-merge",
        checkCallback: (checking) => {
          const file = self.app.workspace.getActiveFile();
          if (file && file.extension === "md") {
            if (!checking) {
              const modal = new composerParts.MergeFileSuggest(self.app, self);
              modal.setCurrentFile(file);
              modal.open();
            }
            return true;
          }
        },
      });
      plugin.registerGlobalCommand({
        id: "note-composer:split-file",
        name: t.commandSplitFile(),
        icon: "lucide-scissors",
        editorCheckCallback: (checking, editor, ctx) => {
          if (ctx.file && editor.somethingSelected()) {
            if (!checking) {
              const modal = new composerParts.ExtractFileSuggest(self.app, editor, self);
              modal.setCurrentFile(ctx.file);
              modal.open();
            }
            return true;
          }
        },
      });
      plugin.registerGlobalCommand({
        id: "note-composer:extract-heading",
        name: t.commandExtractHeading(),
        icon: "lucide-scissors",
        editorCheckCallback: (checking, editor, ctx) => {
          if (!ctx.file) return;
          const line = editor.getCursor().line;
          if (firstHeadingText(editor.getLine(line)) !== null) {
            if (!checking) self.extractHeading(ctx.file, editor);
            return true;
          }
        },
      });
    }

    async onEnable(app, wrapper) {
      this.options = (await wrapper.loadData()) || { askBeforeMerging: true };
      wrapper.registerEvent(app.workspace.on("file-menu", this.onFileMenu, this));
      wrapper.registerEvent(app.workspace.on("editor-menu", this.onEditorMenu, this));
      wrapper.addSettingTab(new composerParts.NoteComposerSettingTab(app, wrapper, this));
    }

    async onExternalSettingsChange() {
      this.options = (await this.pluginInstance.loadData()) || {};
    }

    onFileMenu(menu, file, source) {
      if (source === "link-context-menu") return;
      if (!(file instanceof host.TFile) || file.extension !== "md") return;
      const self = this;
      menu.addItem((item) =>
        item
          .setSection("action")
          .setTitle(t.actionMergeFile())
          .setIcon("lucide-git-merge")
          .onClick(() => {
            const modal = new composerParts.MergeFileSuggest(self.app, self);
            modal.setCurrentFile(file);
            modal.open();
          })
      );
    }

    onEditorMenu(menu, editor, ctx) {
      const file = ctx.file;
      if (!file) return;
      const self = this;
      if (editor.getSelection().trim()) {
        menu.addItem((item) =>
          item
            .setTitle(t.commandSplitFile())
            .setIcon("lucide-git-branch-plus")
            .setSection("selection")
            .onClick(() => {
              const modal = new composerParts.ExtractFileSuggest(self.app, editor, self);
              modal.setCurrentFile(file);
              modal.open();
            })
        );
      }
      const line = editor.getCursor().line;
      if (firstHeadingText(editor.getLine(line)) !== null) {
        menu.addItem((item) =>
          item
            .setTitle(t.commandExtractHeading())
            .setSection("action")
            .setIcon("lucide-git-branch-plus")
            .onClick(() => self.extractHeading(file, editor))
        );
      }
    }

    /** Selects the whole section under the cursor's heading, then opens the extract modal for it. */
    extractHeading(file, editor) {
      const line = editor.getCursor().line;
      const section = this.getSelectionUnderHeading(file, editor, line);
      if (section) {
        editor.setSelection(section.start, section.end);
        const modal = new composerParts.ExtractFileSuggest(this.app, editor, this, section.heading);
        modal.setCurrentFile(file);
        modal.open();
      } else {
        new host.Notice(t.msgFailToFindHeading());
      }
    }

    /** Finds the heading at `line` and the line range of its section (up to the next same-or-higher heading). */
    getSelectionUnderHeading(file, editor, line) {
      const cache = this.app.metadataCache.getFileCache(file);
      if (!cache) return null;
      const headings = cache.headings;
      if (!headings || headings.length === 0) return null;
      let heading = null;
      let level = 0;
      let next = null;
      for (const candidate of headings) {
        if (heading && candidate.level <= level) {
          next = candidate;
          break;
        }
        if (!heading && candidate.position.start.line === line) {
          level = candidate.level;
          heading = candidate;
        }
      }
      if (!heading) return null;
      let end;
      if (next) {
        end = next.position.start.line - 1;
        while (editor.getLine(end).trim() === "" && end > line) end--;
      } else {
        end = editor.lineCount() - 1;
      }
      return {
        heading: heading.heading.trim(),
        start: { line, ch: 0 },
        end: { line: end, ch: editor.getLine(end).length },
      };
    }

    /** Expands the configured template file's variables against the merge/extract context. */
    async applyTemplate(content, fromTitle, newTitle) {
      const template = this.options.template;
      if (!template) return content;
      const app = this.app;
      const dest = app.metadataCache.getFirstLinkpathDest(template, "");
      if (!dest) {
        new host.Notice(t.msgFailToFetchTemplate({ template }));
        return content;
      }
      let templateText = await app.vault.cachedRead(dest);
      if (!templateText) return content;
      if (!templateText.contains("{{content}}")) templateText += "\n\n{{content}}";
      return applyTemplateVars(templateText, { fromTitle, newTitle, content });
    }
  }
  return NoteComposerPlugin;
}

// ---- n-g24-editor-api.js ----
// Public `Editor` API (cP): the document/method surface plugins call on a
// markdown editor — line access, selections, block toggles (heading,
// blockquote, bullet/number/check lists), callout/codeblock/math insertion,
// list-aware newline continuation and text expansion.
// The low-level editor primitives (getLine, replaceRange, transaction, exec,
// posAtCoords, ...) live on the concrete CodeMirror-backed editor and are
// reached through `this`.

function pos(line, ch) {
  if (ch === undefined) ch = 0;
  return { line, ch };
}

function posPlus(point, offset) {
  return { line: point.line, ch: point.ch + offset };
}

function samePos(a, b) {
  return a.line === b.line && a.ch === b.ch;
}

function unique(list) {
  return Array.from(new Set(list));
}

const compareLineNumbers = (a, b) => a - b;

// /^([>\s]*)(([*+-] |(\d+)([.)] ))(?:\[(.)\] )?)?/ — blockquote + list marker.
const LIST_LINE = /^([>\s]*)(([*+-] |(\d+)([.)] ))(?:\[(.)\] )?)?/;
// /^([>\s]*)(#{1,6} )?(.*)/ — heading.
const HEADING_LINE = /^([>\s]*)(#{1,6} )?(.*)/;
// /^\s{0,3}>(\s*)/ — leading blockquote marker.
const BLOCKQUOTE_PREFIX = /^\s{0,3}>(\s*)/;

// CJK/full-width bracket expansion for wikilinks.
const EXPANDERS = [
  { regex: /(！)?【【$/, replace: (match) => (match[1] ? "![[" : "[[") },
  { regex: /】】$/, replace: () => "]]" },
  { regex: /【【$/, replace: () => "[[" },
];

// Width of the blockquote prefix on a line, in characters (tabs expanded).
function blockquoteIndent(line) {
  const match = line.match(BLOCKQUOTE_PREFIX);
  if (!match) return 0;
  let width = match[0].length - match[1].length;
  let rest = match[1];
  while (rest.startsWith("    ")) rest = rest.substring(4);
  if (rest.startsWith(" ")) width += 1;
  return width;
}

function defineEditor() {
  function Editor() {}

  Editor.prototype.getDoc = function () {
    return this;
  };

  Editor.prototype.setLine = function (line, text) {
    this.replaceRange(text, pos(line, 0), pos(line, this.getLine(line).length));
  };

  Editor.prototype.somethingSelected = function () {
    return !!this.getSelection();
  };

  Editor.prototype.setCursor = function (line, ch) {
    if (Number.isNumber(line)) return this.setSelection({ line, ch });
    return this.setSelection(line);
  };

  Editor.prototype.posAtMouse = function (event) {
    return this.posAtCoords(event.clientX, event.clientY);
  };

  Editor.prototype.insertText = function (text) {
    const lastLine = this.lineCount() - 1;
    let end = pos(lastLine, this.getLine(lastLine).length);
    this.replaceRange(text, end);
    const newLast = this.lineCount() - 1;
    end = pos(newLast, this.getLine(newLast).length);
    this.setSelection(end);
  };

  // Applies `lineFn`/`changeFn` to every selected line (or its deduped,
  // sorted line set). `skipBlank` skips empty lines in multi-selection.
  Editor.prototype.processLines = function (lineFn, changeFn, skipBlank) {
    if (skipBlank === undefined) skipBlank = true;
    const selections = this.listSelections();
    const lines = unique(selections.reduce((acc, sel) => {
      const from = Math.min(sel.anchor.line, sel.head.line);
      const to = Math.max(sel.anchor.line, sel.head.line);
      for (let i = from; i <= to; i++) acc.push(i);
      return acc;
    }, [])).sort(compareLineNumbers);
    const mapped = [];
    for (let i = 0; i < lines.length; i++) {
      const lineNo = lines[i];
      const lineText = this.getLine(lineNo);
      if (skipBlank && lines.length > 1 && !lineText.trim()) mapped.push(null);
      else mapped.push(lineFn(lineNo, lineText));
    }
    const changes = [];
    for (let i = 0; i < lines.length; i++) {
      const lineNo = lines[i];
      const mappedValue = mapped[i];
      const lineText = this.getLine(lineNo);
      if (!skipBlank || mappedValue !== null) {
        const change = changeFn(lineNo, lineText, mappedValue);
        if (change) changes.push(change);
      }
    }
    if (changes.length === 0) return;
    if (selections.length === 1) {
      const change = changes[0];
      const sel = selections[0];
      const anchor = sel.anchor;
      if (anchor.ch === 0 && samePos(anchor, sel.head) && anchor.line === change.from.line) {
        const delta = change.text.length - (change.to ? change.to.ch - change.from.ch : 0);
        anchor.ch += delta;
        if (anchor.ch < 0) anchor.ch = 0;
        this.transaction({ changes, selection: { from: anchor } });
        return;
      }
    }
    this.transaction({ changes });
  };

  Editor.prototype.setHeading = function (level) {
    this.processLines(
      (lineNo, text) => text.match(HEADING_LINE),
      (lineNo, text, match) => {
        const prefix = level === 0 ? "" : Array(level).fill("#").join("") + " ";
        return { from: pos(lineNo, match[1].length), to: pos(lineNo, text.length - match[3].length), text: prefix };
      },
    );
  };

  Editor.prototype.toggleBlockquote = function () {
    let allQuoted = false; // `e` in the original: becomes true once any line has a quote prefix
    this.processLines(
      (lineNo, text) => {
        const indent = blockquoteIndent(text);
        if (indent === 0) allQuoted = true;
        return indent;
      },
      (lineNo, text, indent) => {
        const width = indent;
        if (allQuoted && width === 0) return { from: pos(lineNo, 0), text: "> " };
        if (allQuoted) return undefined;
        return { from: pos(lineNo, 0), to: pos(lineNo, width), text: "" };
      },
      false,
    );
  };

  Editor.prototype.toggleBulletList = function () {
    let hasNonBullet = false;
    this.processLines(
      (lineNo, text) => {
        const match = text.match(LIST_LINE);
        if (!match[3] || match[4] || match[6]) hasNonBullet = true;
        return match;
      },
      (lineNo, text, match) => {
        if (!match) return null;
        return { from: pos(lineNo, 0), to: pos(lineNo, match[0].length), text: match[1] + (hasNonBullet ? "- " : "") };
      },
    );
  };

  Editor.prototype.toggleNumberList = function () {
    let hasNonNumber = false;
    this.processLines(
      (lineNo, text) => {
        const match = text.match(LIST_LINE);
        if (!match[4]) hasNonNumber = true;
        return match;
      },
      (lineNo, text, match) => {
        if (!match) return null;
        return { from: pos(lineNo, 0), to: pos(lineNo, match[0].length), text: match[1] + (hasNonNumber ? "1. " : "") };
      },
    );
  };

  Editor.prototype.toggleCheckList = function (check) {
    let state = 3;
    this.processLines(
      (lineNo, text) => {
        const match = text.match(LIST_LINE);
        if (state > 2 && match[6] === " ") state = 2;
        if (state > 1 && !match[6]) state = 1;
        if (check && state > 0 && !match[3]) state = 0;
        return match;
      },
      (lineNo, text, match) => {
        if (!match) return null;
        const marker = match[0];
        const prefix = match[1];
        const checkChar = match[3];
        const change = { from: pos(lineNo, 0), to: pos(lineNo, marker.length), text: text.substr(0, marker.length) };
        const base = prefix + (checkChar || "- ");
        change.text = base;
        if (state === 1) {
          if (!match[6]) change.text = base + "[ ] ";
        } else if (state === 2) {
          change.text = base + "[x] ";
        } else if (state === 3) {
          change.text = check ? base : base + "[ ] ";
        }
        return change;
      },
    );
  };

  Editor.prototype.insertCallout = function () {
    const from = this.getCursor("from");
    const to = this.getCursor("to");
    if (!samePos(from, to) || this.getLine(from.line).substring(0, from.ch).trim()) {
      const changes = [];
      let marker = "> [!NOTE]\n> ";
      const selection = { from: pos(from.line, 4), to: pos(from.line, 8) };
      if (from.line > 0 && this.getLine(from.line - 1)) {
        marker = "\n" + marker;
        selection.from.line += 1;
        selection.to.line += 1;
      }
      changes.push({ from: pos(from.line, 0), text: marker });
      for (let line = from.line + 1; line <= to.line; line++) {
        changes.push({ from: pos(line, 0), text: "> " });
      }
      if (to.line < this.lineCount() - 1 && this.getLine(to.line + 1)) {
        changes.push({ from: pos(to.line + 1, 0), text: "\n" });
      }
      this.transaction({ changes, selection });
    } else {
      this.transaction({
        changes: [{ from, to, text: "\n> [!NOTE] Title\n> Contents\n" }],
        selection: { from: pos(from.line + 1, 4), to: pos(from.line + 1, 8) },
      });
    }
  };

  Editor.prototype.insertCodeblock = function () {
    this.insertBlock("```", "```");
  };

  Editor.prototype.insertMathBlock = function () {
    this.insertBlock("$$", "$$");
  };

  Editor.prototype.indentList = function () {
    this.exec("indentMore");
  };

  Editor.prototype.unindentList = function () {
    this.exec("indentLess");
  };

  // Enter inside/at the edge of a markdown list continues the list marker,
  // handling blockquote prefixes, ordered renumbering and checkboxes.
  Editor.prototype.newlineAndIndentContinueMarkdownList = function () {
    const self = this;
    const selections = this.listSelections();
    const changes = [];
    const trySelection = (sel) => {
      const head = sel.head;
      if (sel.head.line !== sel.anchor.line || sel.head.ch !== sel.anchor.ch) return false;
      const lineText = self.getLine(head.line);
      const match = LIST_LINE.exec(lineText);
      if (!match || !match[0]) return false;
      let marker = match[0];
      let prefix = match[1];
      let markerGroup = match[2];
      let listMarker = match[3];
      let number = match[4];
      let delimiter = match[5];
      let checkState = match[6];
      const markerLength = marker.length;
      if (head.ch < markerLength || (!markerGroup && !prefix)) return false;
      if (!markerGroup) {
        // Bullet: look upwards for an enclosing ordered item of same width.
        for (let line = head.line - 1; line >= 0; line--) {
          const above = self.getLine(line);
          const aboveMatch = LIST_LINE.exec(above);
          if (aboveMatch[2] && aboveMatch[0].length === markerLength) {
            marker = aboveMatch[0];
            prefix = aboveMatch[1];
            markerGroup = aboveMatch[2];
            listMarker = aboveMatch[3];
            number = aboveMatch[4];
            delimiter = aboveMatch[5];
            checkState = aboveMatch[6];
            break;
          }
          if (aboveMatch[0].length < markerLength) break;
        }
      }
      const rest = lineText.substr(markerLength);
      if (rest.trim() === "") {
        if (!prefix) {
          changes.push({ text: "", from: pos(head.line), to: head });
          return true;
        }
        if (prefix.endsWith(">") || prefix.endsWith("> ")) {
          if (markerGroup) {
            changes.push({ text: "", from: pos(head.line, prefix.length), to: head });
            return true;
          }
          const trim = prefix.endsWith(">") ? 1 : 2;
          if (head.line > 0) {
            if (self.getLine(head.line - 1) === prefix) {
              changes.push(
                { text: "", from: pos(head.line - 1, prefix.length - trim), to: pos(head.line - 1, prefix.length) },
                { text: "", from: pos(head.line, prefix.length - trim), to: pos(head.line, prefix.length) },
              );
              return true;
            }
          }
          const parent = prefix.substr(0, prefix.length - trim);
          changes.push({ text: "\n" + parent, from: pos(head.line, prefix.length - trim), to: pos(head.line, prefix.length) });
          return true;
        }
        if (prefix.endsWith("\t")) {
          changes.push({ text: "", from: pos(head.line, prefix.length - 1), to: pos(head.line, prefix.length) });
          return true;
        }
        let spaces = 0;
        while (spaces < 4 && prefix.charAt(prefix.length - spaces - 1) === " ") spaces++;
        if (spaces > 0) {
          changes.push({ text: "", from: pos(head.line, prefix.length - spaces), to: pos(head.line, prefix.length) });
          return true;
        }
        changes.push({ text: "", from: pos(head.line), to: pos(head.line, prefix.length) });
        return true;
      }
      if (!markerGroup) {
        changes.push({ text: lineText.charAt(head.ch - 1) + "\n" + prefix, from: pos(head.line, head.ch - 1), to: head });
        return true;
      }
      let next = listMarker;
      if (number) next = parseInt(number, 10) + 1 + delimiter;
      if (checkState) next += "[ ] ";
      const trailing = LIST_LINE.exec(lineText.substring(head.ch));
      if (trailing && trailing[3]) next = "";
      changes.push({ text: lineText.charAt(head.ch - 1) + "\n" + prefix + next, from: pos(head.line, head.ch - 1), to: head });
      if (trailing && trailing[1]) {
        changes.push({ text: "", from: head, to: pos(head.line, head.ch + trailing[1].length) });
      }
      return true;
    };
    for (let i = 0; i < selections.length; i++) {
      if (!trySelection(selections[i])) return this.exec("newlineAndIndent");
    }
    this.transaction({ changes }, "input.type");
  };

  // Enter that only preserves leading whitespace (indent continuation).
  Editor.prototype.newlineAndIndentOnly = function () {
    const self = this;
    const selections = this.listSelections();
    const changes = [];
    const trySelection = (sel) => {
      const head = sel.head;
      if (sel.head.line !== sel.anchor.line || sel.head.ch !== sel.anchor.ch) return false;
      const lineText = self.getLine(head.line);
      const match = LIST_LINE.exec(lineText);
      if (!match || !match[0]) return false;
      const marker = match[0];
      const prefix = match[1];
      const markerGroup = match[2];
      if (head.ch < marker.length) return false;
      changes.push({
        text: lineText.charAt(head.ch - 1) + "\n" + prefix + (markerGroup ? markerGroup.replace(/\t/g, "    ").replace(/./g, " ") : ""),
        from: pos(head.line, head.ch - 1),
        to: head,
      });
      return true;
    };
    for (let i = 0; i < selections.length; i++) {
      if (!trySelection(selections[i])) return this.newlineOnly();
    }
    this.transaction({ changes });
  };

  Editor.prototype.newlineOnly = function () {
    this.transaction({ replaceSelection: "\n" });
  };

  // Expands trailing CJK brackets into wikilink syntax.
  Editor.prototype.expandText = function () {
    const anchor = this.getCursor("anchor");
    const head = this.getCursor("head");
    if (anchor.line === head.line && anchor.ch === head.ch) {
      const before = this.getLine(anchor.line).substr(0, anchor.ch);
      for (let i = 0; i < EXPANDERS.length; i++) {
        const expander = EXPANDERS[i];
        const match = before.match(expander.regex);
        if (match) {
          const length = match[0].length;
          const replacement = expander.replace(match);
          this.replaceRange(replacement, posPlus(anchor, -length), anchor);
          break;
        }
      }
    }
  };

  return Editor;
}

// ---- n-g24-importer.js ----
// The "Format converter" (markdown importer) core plugin: a modal that rewrites Markdown produced
// by other apps (Roam Research, Bear, Zettelkasten-style UIDs) into Basalt's format, plus a
// frontmatter migration for tags/aliases/cssclasses.
//
// Replaces the inherited pieces:
//   U8  MarkdownImporterPlugin -> defineMarkdownImporterPlugin
//   X8  ImporterModal          -> defineImporterModal      (base: Modal)
//   j8  gm.plugins.markdownFormatImporter -> declarator __basaltHost.t.plugins.markdownFormatImporter
//   W8/_8/G8/K8/Y8/Q8          -> the converter regexes now live inside defineImporterModal;
//                                the top-level literals become null (nothing else referenced them).


/** i18next is configured to treat "{{" as a placeholder; descriptions that must show "{{[[TODO]]}}"
 *  literally are fetched with alternate interpolation markers. */
const TODO_INTERPOLATION = { interpolation: { prefix: "{{{{", suffix: "}}}}" } };

// The modal and plugin factories run at different positions in the bundle; the plugin reaches
// the modal class through this registry (populated by defineImporterModal).
const importerModalParts = {};

/** Renames an object key while keeping the position of the entry in iteration order. */
function renameKeyInPlace(obj, from, to) {
  for (const key of Object.keys(obj)) {
    const value = obj[key];
    delete obj[key];
    obj[key === from ? to : key] = value;
  }
}

/** Rewrites the frontmatter of `text` through `mutate(data)` and serializes it back. */
function updateFrontmatterText(host, text, mutate) {
  const bounds = frontmatterBounds(text);
  let data = bounds.exists ? host.parseYaml(bounds.frontmatter) : {};
  if (!data || typeof data !== "object") data = {};
  mutate(data);
  if (Object.keys(data).length === 0) return bounds.exists ? text.slice(bounds.contentStart) : text;
  const yaml = host.yamlStringify(data);
  return bounds.exists ? text.slice(0, bounds.from) + yaml + text.slice(bounds.to) : "---\n" + yaml + "---\n" + text;
}

/** Runs `fn` for every element of `items`, yielding a microtask between elements (keeps the UI alive). */
async function* eachItem(items) {
  for (const item of items) yield await Promise.resolve(item);
}

// =====================================================================================================================
// The conversion modal
// =====================================================================================================================

/** Modal listing the available conversions; runs them file by file over the whole vault. */
function defineImporterModal(host) {
  const t = () => host.t.plugins.markdownFormatImporter;

  /** Roam "#tag"/"#[[tag]]" -> "[[tag]]"; numeric "#123" anchors are left alone, "#[[x]]" loses its '#'. */
  const ROAM_TAG = /(^|\s)#([^\u2000-\u206F\u2E00-\u2E7F'!"#$%&()*+,.:;<=>?@^`{|}~[\]\\\s]+)/g;
  const ROAM_TAG_WIKILINK = /\B#(\[\[[\w \t]*?\]\])/g;
  /** Roam "^^highlight^^" -> "==highlight==". */
  const ROAM_HIGHLIGHT = /\^\^(\S(.*?\S)?)\^\^/g;
  /** Bear "::highlight::" -> "==highlight==". */
  const BEAR_HIGHLIGHT = /::(\S(.*?\S)?)::/g;
  /** "{{[[TODO]]}}"/{{[[DONE]]}}" task markers -> "[ ]"/"[x]". */
  const ROAM_TODO = /\{\{\[\[(TODO|DONE)\]\]\}\}/g;
  /** "[[12345]]" Zettelkasten uid links. */
  const ZETTEL_ID = /\[\[(\d+?)\]\]/g;

  function ImporterModal(app) {
    const self = host.Modal.call(this, app) || this;
    self.converters = [];
    const contentEl = self.contentEl;
    const converters = self.converters;
    self.titleEl.setText(t().name());
    const optionsEl = (self.conversionsEl = contentEl.createDiv());

    const allDigits = (s) => {
      for (let i = 0; i < s.length; i++) {
        const code = s.charCodeAt(i);
        if (code < 48 || code > 57) return false;
      }
      return true;
    };

    const conversions = [
      {
        name: t().optionRoamTagFixer(),
        description: t().optionRoamTagFixerDescription(),
        convert(app, file, text, stats) {
          text = text.replace(ROAM_TAG, (match, prefix, tag) => {
            if (allDigits(tag)) return match;
            stats.replaced++;
            return prefix + "[[" + tag + "]]";
          });
          return text.replace(ROAM_TAG_WIKILINK, (match, inner) => {
            stats.replaced++;
            return inner;
          });
        },
      },
      {
        name: t().optionRoamHighlightFixer(),
        description: t().optionRoamHighlightFixerDescription(),
        convert(app, file, text, stats) {
          return text.replace(ROAM_HIGHLIGHT, (match, inner) => {
            stats.replaced++;
            return "==" + inner + "==";
          });
        },
      },
      {
        name: t().optionRoamTodoConverter(),
        description: t().optionRoamTodoConverterDescription(TODO_INTERPOLATION),
        convert(app, file, text, stats) {
          return text.replace(ROAM_TODO, (match, word) => {
            stats.replaced++;
            return word === "TODO" ? "[ ]" : "[x]";
          });
        },
      },
      {
        name: t().optionBearHighlightFixer(),
        description: t().optionBearHighlightFixerDescription(),
        convert(app, file, text, stats) {
          return text.replace(BEAR_HIGHLIGHT, (match, inner) => {
            stats.replaced++;
            return "==" + inner + "==";
          });
        },
      },
      {
        name: t().zettelkastenLinkFixer(),
        description: t().zettelkastenLinkFixerDescription(),
        convert(app, file, text, stats) {
          return text.replace(ZETTEL_ID, (match, id) => {
            for (const candidate of app.vault.getAllLoadedFiles()) {
              if (candidate instanceof host.TFile && candidate.basename.contains(id)) {
                stats.replaced++;
                return "[[" + app.metadataCache.fileToLinktext(candidate, file.path) + "]]";
              }
            }
            return match;
          });
        },
      },
      {
        name: t().zettelkastenLinkBeautifier(),
        description: t().zettelkastenLinkBeautifierDescription(),
        convert(app, file, text, stats) {
          return text.replace(ZETTEL_ID, (match, id) => {
            for (const candidate of app.vault.getAllLoadedFiles()) {
              if (candidate instanceof host.TFile && candidate.basename.contains(id)) {
                stats.replaced++;
                const name = candidate.basename.replace(id, "").trim();
                return "[[" + app.metadataCache.fileToLinktext(candidate, file.path) + "|" + name + "]]";
              }
            }
            return match;
          });
        },
      },
      {
        name: t().frontmatterMigration(),
        description: t().frontmatterMigrationDescription(),
        convert(app, file, text, stats) {
          let changed = false;
          const migrated = updateFrontmatterText(host, text, (data) => {
            // aliases / alias
            const aliasesKey = keyIgnoringCase(data, "aliases");
            if (!Object.hasOwn(data, aliasesKey)) {
              for (const key in data) {
                if (Object.hasOwn(data, key) && key.toLowerCase() === "alias") {
                  renameKeyInPlace(data, key, aliasesKey);
                  changed = true;
                  break;
                }
              }
            }
            if (Object.hasOwn(data, aliasesKey)) {
              const value = data[aliasesKey];
              if (String.isString(value)) {
                data[aliasesKey] = value.split(/[,\n]/).map((s) => s.trim()).filter((s) => !!s);
                changed = true;
              }
            }
            // tags / tag
            const tagsKey = keyIgnoringCase(data, "tags");
            if (!Object.hasOwn(data, tagsKey)) {
              for (const key in data) {
                if (Object.hasOwn(data, key) && key.toLowerCase() === "tag") {
                  renameKeyInPlace(data, key, tagsKey);
                  changed = true;
                  break;
                }
              }
            }
            if (Object.hasOwn(data, tagsKey)) {
              const value = data[tagsKey];
              if (String.isString(value)) {
                data[tagsKey] = value.split(/[ ,\n]/).filter((s) => !!s);
                changed = true;
              }
            }
            // cssclasses / cssclass
            const cssKey = keyIgnoringCase(data, "cssclasses");
            if (!Object.hasOwn(data, cssKey)) {
              for (const key in data) {
                if (Object.hasOwn(data, key) && key.toLowerCase() === "cssclass") {
                  renameKeyInPlace(data, key, cssKey);
                  changed = true;
                  break;
                }
              }
            }
            if (Object.hasOwn(data, cssKey)) {
              const value = data[cssKey];
              if (String.isString(value)) {
                data[cssKey] = value.split(/[ ,\n]/).filter((s) => !!s);
                changed = true;
              }
            }
          });
          return changed ? migrated : text;
        },
      },
    ];

    const addToggle = (conversion) => {
      new host.Setting(optionsEl)
        .setName(conversion.name)
        .setDesc(conversion.description)
        .addToggle((toggle) => {
          toggle.setValue(false);
          converters.push({ toggle, conversion });
        });
    };
    for (const conversion of conversions) addToggle(conversion);

    optionsEl.createEl("p", { cls: "setting-message mod-warning", text: t().msgAllFilesWarning() });
    optionsEl.createEl("p", { cls: "setting-message mod-warning", text: t().msgOverrideFilesWarning() });
    optionsEl.createDiv("modal-button-container").createEl("button", { cls: "mod-cta", text: t().labelStartConversion() })
      .addEventListener("click", self.onProcess.bind(self));

    const resultEl = (self.resultEl = createDiv());
    self.statusEl = resultEl.createEl("p", "u-center-text");
    self.processedEl = resultEl.createDiv("changelog-item mod-success");
    self.modifiedEl = resultEl.createDiv("changelog-item mod-highlighted");
    self.replacedEl = resultEl.createDiv("changelog-item mod-highlighted");
    self.failedEl = resultEl.createDiv("changelog-item mod-failed");
    self.renderStats({ processed: 0, modified: 0, replaced: 0, failed: 0 });
    const buttonEl = resultEl.createDiv("modal-button-container");
    self.cancelEl = buttonEl.createEl("button", { cls: "mod-warning", text: t().labelStop() });
    self.cancelEl.addEventListener("click", self.onCancel.bind(self));
    self.goBackEl = buttonEl.createEl("button", { cls: "", text: t().labelGoBack() });
    self.goBackEl.addEventListener("click", self.onGoBack.bind(self));
    self.doneEl = buttonEl.createEl("button", { cls: "mod-cta", text: t().labelDone() });
    self.doneEl.addEventListener("click", self.close.bind(self));
    return self;
  }
  inherit(ImporterModal, host.Modal);
  const proto = ImporterModal.prototype;

  proto.onProcess = function () {
    const chosen = [];
    for (const entry of this.converters) {
      if (entry.toggle.getValue()) chosen.push(entry.conversion);
    }
    if (chosen.length === 0) return;
    this.runnable = new host.Runnable({
      onCancel: () => {
        this.cancelEl.hide();
        this.statusEl.setText(t().labelCancelling());
      },
    });
    this.conversionsEl.detach();
    this.contentEl.append(this.resultEl);
    this.cancelEl.show();
    this.goBackEl.hide();
    this.doneEl.hide();
    this.statusEl.setText(t().labelProcessing());
    this.process(chosen);
  };

  proto.onCancel = function () {
    this.runnable?.cancel();
  };

  proto.onGoBack = function () {
    this.resultEl.detach();
    this.contentEl.append(this.conversionsEl);
    for (const entry of this.converters) entry.toggle.setValue(false);
  };

  proto.onFinish = function (stats) {
    this.renderStats(stats);
    this.cancelEl.hide();
    this.goBackEl.show();
    this.statusEl.setText(t().labelFinished());
    this.doneEl.show();
  };

  proto.renderStats = function (stats) {
    this.processedEl.setText(t().labelProcessedFiles());
    this.processedEl.setAttribute("data-label", String(stats.processed));
    this.modifiedEl.setText(t().labelModifiedFiles());
    this.modifiedEl.setAttribute("data-label", String(stats.modified));
    this.replacedEl.setText(t().labelTotalReplacements());
    this.replacedEl.setAttribute("data-label", String(stats.replaced));
    this.failedEl.toggle(stats.failed > 0);
    this.failedEl.setText(t().labelFailed());
    this.failedEl.setAttribute("data-label", String(stats.failed));
  };

  proto.onClose = function () {
    this.onCancel();
    this.onGoBack();
  };

  /** Applies every chosen conversion to every markdown file, one file at a time. */
  proto.process = async function (conversions) {
    const app = this.app;
    const runnable = this.runnable;
    const stats = { processed: 0, modified: 0, replaced: 0, failed: 0 };
    const files = app.vault.getMarkdownFiles();
    const changed = [];
    try {
      for await (const file of eachItem(files)) {
        if (runnable.isCancelled()) {
          this.onFinish(stats);
          app.fileManager.notifyForBulkUndo(changed);
          break;
        }
        try {
          await app.vault.process(
            file,
            (content) => {
              let next = content;
              for (const conversion of conversions) next = conversion.convert(app, file, next, stats);
              if (next !== content) {
                stats.modified++;
                changed.push({ file, mtime: file.stat.mtime, content });
              }
              return next;
            },
            { mtime: file.stat.mtime + 1 }
          );
        } catch (error) {
          stats.failed++;
          console.error(error);
        }
        stats.processed++;
        if (runnable.isCancelled()) {
          this.onFinish(stats);
          app.fileManager.notifyForBulkUndo(changed);
          break;
        }
        this.renderStats(stats);
        if (stats.processed % 10 === 0) await host.sleep(0);
      }
    } finally {
      this.onFinish(stats);
      app.fileManager.notifyForBulkUndo(changed);
    }
  };

  importerModalParts.Modal = ImporterModal;
  return ImporterModal;
}

/** Ribbon item + global command opening the converter modal. */
function defineMarkdownImporterPlugin(host) {
  const t = () => host.t.plugins.markdownFormatImporter;

  class MarkdownImporterPlugin {
    constructor() {
      this.id = "markdown-importer";
      this.name = t().name();
      this.description = t().desc();
    }

    init(app, plugin) {
      this.app = app;
      plugin.registerRibbonItem(t().actionOpen(), "lucide-binary", this.onOpen.bind(this));
      plugin.registerGlobalCommand({
        id: "markdown-importer:open",
        name: t().actionOpen(),
        icon: "lucide-download",
        callback: this.onOpen.bind(this),
      });
    }

    onOpen() {
      new importerModalParts.Modal(this.app).open();
      return false;
    }
  }
  return MarkdownImporterPlugin;
}

// ---- n-g24-markdown-render.js ----
// The reading-mode render foundation: MarkdownRenderChild (the Component that owns a rendered container),
// MarkdownPreviewSection (one rendered slice of a document), the link/hover handlers every rendered view shares,
// and MarkdownRenderer (the object plugins call to render markdown into a DOM node).
//
// Everything the application scope still owns (the sectioned preview renderer, the embed loader, the markdown
// parsers, the preview view that post-processes embeds) is reached through `host`; names there are the only
// minified identifiers in this file.

/** Plugins that called renderMarkdown without a Component: warn once per plugin id (was the bundle's `sq`). */
const renderWarnings = {};

function defineMarkdownRenderChild(host) {
  /** A Component that simply owns the element its rendered content goes into. */
  function MarkdownRenderChild(containerEl) {
    const self = host.Component.call(this) || this;
    self.containerEl = containerEl;
    return self;
  }
  inherit(MarkdownRenderChild, host.Component);
  return MarkdownRenderChild;
}

function defineMarkdownPreviewSection(host) {
  /** One rendered section of a preview: holds the sanitized html, the source range it came from and the
   *  geometry the renderer measured. `html === null` means "not rendered yet". */
  function MarkdownPreviewSection(html) {
    this.rendered = false;
    this.height = 0;
    this.computed = false;
    this.lines = 0;
    this.used = true;
    this.highlightRanges = null;
    this.level = 0;
    this.headingCollapsed = false;
    this.shown = true;
    this.usesFrontMatter = false;
    this.html = html || "";
    this.el = createDiv();
    if (html === null) {
      this.rendered = true;
      this.start = this.end = { line: 0, col: 0, offset: 0 };
    }
  }

  MarkdownPreviewSection.prototype.render = function () {
    if (this.rendered) return;
    const fragment = host.sanitizeHtml(this.html);
    this.el.appendChild(fragment);
    const first = this.el.firstChild;
    if (first && first.nodeType === Node.ELEMENT_NODE) this.el.addClass("el-" + first.tagName.toLowerCase());
    this.rendered = true;
    this.computed = false;
  };

  /** Marks the measured geometry stale; highlight rects of child ranges are dropped with it. */
  MarkdownPreviewSection.prototype.resetCompute = function () {
    this.computed = false;
    const ranges = this.highlightRanges;
    if (ranges) for (let i = 0; i < ranges.length; i++) ranges[i].rects = null;
  };

  MarkdownPreviewSection.prototype.setCollapsed = function (collapsed) {
    this.headingCollapsed = collapsed;
    host.setCollapsed(this.el, collapsed);
  };

  return MarkdownPreviewSection;
}

function definePreviewLinkHandlers(host) {
  /** The click/drag/hover behaviour of links and tags inside rendered markdown. `info` is the owner
   *  (a MarkdownRenderer, or an editor wrapper): it provides `app` and `path`. */
  function PreviewLinkHandlers(info) {
    this.info = info;
  }
  const proto = PreviewLinkHandlers.prototype;

  proto.onInternalLinkDrag = function (event, targetEl, linktext, sourcePath) {
    const app = this.info.app;
    app.dragManager.onDragStart(event, app.dragManager.dragLink(event, linktext, this.info.path, sourcePath));
  };

  proto.onInternalLinkClick = function (event, targetEl, linktext) {
    event.preventDefault();
    this.info.app.workspace.openLinkText(linktext, this.info.path, host.Keymap.isModEvent(event));
  };

  proto.onInternalLinkRightClick = function (event, targetEl, linktext) {
    const menu = host.Menu.forEvent(event);
    menu.setParentElement(targetEl);
    menu.addSections(["title", "open", "action", "clipboard", "view", "info", "", "danger"]);
    menu.addItem((item) => item.setSection("clipboard").setTitle(host.t.interface.menu.copy()).setIcon("lucide-copy")
      .onClick(() => copyText(targetEl.getText())));
    this.info.app.workspace.handleLinkContextMenu(menu, linktext, this.info.path);
  };

  proto.onExternalLinkClick = function (event, targetEl, href) {
    event.preventDefault();
    if (isUrl(href)) {
      const mod = host.Keymap.isModEvent(event);
      // a boolean means "no modifier string to pass on"
      window.open(href, typeof mod === "boolean" ? "" : mod);
    } else {
      new host.Notice(host.t.interface.msgFailedToOpenHref({ href }));
    }
  };

  proto.onExternalLinkRightClick = function (event, targetEl, href) {
    const menu = host.Menu.forEvent(event);
    menu.addSections(["title", "open", "selection", "clipboard", "info", "action", "view", "", "danger"]);
    menu.addItem((item) => item.setSection("clipboard").setTitle(host.t.interface.menu.copy()).setIcon("lucide-copy")
      .onClick(() => copyText(targetEl.getText())));
    this.info.app.workspace.handleExternalLinkContextMenu(menu, href);
  };

  proto.onInternalLinkMouseover = function (event, targetEl, linktext) {
    this.info.app.workspace.trigger("hover-link", {
      event, source: "preview", hoverParent: this.info, targetEl, linktext, sourcePath: this.info.path,
    });
  };

  proto.onTagClick = function (event, targetEl, tag) {
    const search = this.info.app.internalPlugins.getEnabledPluginById("global-search");
    if (search) search.openGlobalSearch("tag:" + tag);
  };

  return PreviewLinkHandlers;
}

function defineMarkdownRenderer(host) {
  /** Renders markdown into DOM. Plugins use the statics (render / renderMarkdown); a view uses an instance
   *  (constructed with the view's app, a container element and the file path) and drives `renderer`. */
  function MarkdownRenderer(app, containerEl, sourcePath, registerEvents) {
    if (registerEvents === undefined) registerEvents = true;
    const self = host.MarkdownRenderChild.call(this, containerEl) || this;
    self.docId = randomHex(16);
    self.hoverPopover = null;
    self.requestUpdateLinks = host.debounce(() => {
      const sections = self.renderer.sections;
      for (let i = 0; i < sections.length; i++) {
        const section = sections[i];
        if (section.rendered) self.resolveLinks(section.el);
      }
    }, 500);
    self.app = app;
    const linkHandlers = new host.PreviewLinkHandlers(self);
    self.renderer = new host.MarkdownPreviewRenderer(self, linkHandlers, containerEl, "worker.js", registerEvents);
    return self;
  }
  inherit(MarkdownRenderer, host.MarkdownRenderChild);
  const proto = MarkdownRenderer.prototype;

  proto.onload = function () {
    const app = this.app;
    this.registerEvent(app.vault.on("modify", this.onFileChange, this));
    this.registerEvent(app.vault.on("delete", this.onFileChange, this));
    this.registerEvent(app.metadataCache.on("changed", this.onFileChange, this));
  };

  /** Checkbox toggle inside rendered task lists: flips the source and patches the rendered list item. */
  proto.onCheckboxClick = function (event, checkboxEl, line) {
    event.preventDefault();
    navigator.vibrate(100);
    const text = this.renderer.text;
    const toggled = MarkdownRenderer.toggleCheckbox(text, line);
    if (toggled !== null) {
      const section = this.renderer.getSectionContainer(checkboxEl);
      if (section) {
        const checked = toggled.char !== " ";
        const sectionLine = line - section.start.line;
        if (sectionLine >= 0) {
          const key = String(sectionLine);
          // rewrite the matching <li> in the section's html so a re-render keeps the new state
          section.html = section.html.replace(
            /<li class="task-list-item( is-checked)?" data-task="(.)" data-line="(\d+)"><input class="task-list-item-checkbox" type="checkbox"( checked)? data-line="(\d+)">/g,
            (match, isChecked, task, dataLine, wasChecked, endLine) =>
              dataLine === key && endLine === key
                ? '<li class="task-list-item' + (checked ? " is-checked" : "") + '" data-task="' + toggled.char + '" data-line="' + dataLine + '"><input class="task-list-item-checkbox" type="checkbox"' + (checked ? " checked" : "") + ' data-line="' + endLine + '">'
                : match
          );
        }
        setTimeout(() => {
          checkboxEl.checked = checked;
          const item = checkboxEl.parentNode;
          if (item && item.instanceOf(HTMLLIElement)) {
            item.setAttr("data-task", toggled.char);
            item.toggleClass("is-checked", checked);
          }
        }, 0);
      }
      this.edit(toggled.text);
    }
  };

  /** Flips the [ ]/[x] on `line`; returns the new source text and marker char, or null when there is none. */
  MarkdownRenderer.toggleCheckbox = function (text, line) {
    const bounds = lineBounds(text, line);
    if (!bounds) return null;
    const mark = text.slice(bounds.start, bounds.end).search(/\[.\]/);
    if (mark === -1) return null;
    const at = bounds.start + mark + 1;
    const char = text.charAt(at) === " " ? "x" : " ";
    return { text: text.slice(0, at) + char + text.slice(at + 1), char };
  };

  /** Runs every registered post-processor over a rendered section, then resolves its links. */
  proto.postProcess = function (section, promises, frontmatter) {
    const self = this;
    const ctx = host.MarkdownPreviewView.postProcess(self.app, {
      docId: self.docId,
      sourcePath: self.path,
      frontmatter,
      promises,
      addChild: (child) => self.addChild(child),
      getSectionInfo: (el) => self.renderer.getSectionInfo(el),
      replace: (html, rerender) => {
        const text = self.renderer.text;
        const from = section.start;
        const to = section.end;
        const next = text.slice(0, from.offset) + html + text.slice(to.offset);
        if (rerender) {
          const rendered = host.renderSectionHtml(html);
          if (rendered.sections.length === 1) section.html = rendered.sections[0].html;
        }
        self.edit(next);
      },
      containerEl: self.renderer.sizerEl,
      el: section.el,
    });
    section.usesFrontMatter = !!ctx.usesFrontMatter;
    self.resolveLinks(section.el);
  };

  proto.onScroll = function () {};
  proto.onFoldChange = function () {};
  proto.onRenderComplete = function () {};

  Object.defineProperty(proto, "path", {
    get: function () { return (this.file && this.file.path) || ""; },
    enumerable: false,
    configurable: true,
  });

  proto.onFileChange = function () { this.requestUpdateLinks(); };

  proto.resolveLinks = function (el) {
    const self = this;
    host.refreshLinkStates(self.app, el, self.path, (linktext) => self.renderer.getInternalLinkHref(linktext));
  };

  /** The post-processing every rendered markdown root gets: query embeds, registered post-processors,
   *  file embeds. `ctx` is { app, markdown, el, sourcePath, component }. */
  MarkdownRenderer.postProcess = function (app, ctx) {
    const sourcePath = ctx.sourcePath;
    const promises = ctx.promises;
    const el = ctx.el;
    const displayMode = ctx.displayMode;
    const queries = el.findAll("code.language-query");
    for (let i = 0; i < queries.length; i++) {
      const code = queries[i];
      const query = host.queryBlockText(code).trim();
      const parent = code.parentElement;
      ctx.addChild(host.queryEmbed(app, query, parent, sourcePath));
    }
    const postProcessors = host.MarkdownPreviewRenderer.postProcessors;
    for (let i = 0; i < postProcessors.length; i++) {
      const result = postProcessors[i](el, ctx);
      if (result && result.then) promises.push(result);
    }
    const depth = host.embedDepth(ctx.containerEl);
    const embeds = el.findAll(".internal-embed:not(.is-loaded)");
    if (embeds.length > 0) {
      for (let i = 0; i < embeds.length; i++) {
        const embed = embeds[i];
        const linktext = embed.getAttribute("src");
        const child = host.EmbedLoader.load({
          app, linktext, sourcePath, containerEl: embed, displayMode, showInline: true, depth,
        });
        if (child) {
          ctx.addChild(child);
          promises.push(child.loadFile());
        }
      }
    }
    return ctx;
  };

  MarkdownRenderer.renderMarkdown = function (markdown, el, sourcePath, component) {
    return MarkdownRenderer.render(null, markdown, el, sourcePath, component);
  };

  /** Parses `markdown`, appends the sanitized DOM to `el` and runs post-processing; resolves when embeds settle. */
  MarkdownRenderer.render = function (app, markdown, el, sourcePath, component) {
    if (!(component && component instanceof host.Component)) {
      const stack = new Error().stack;
      if (typeof stack === "string") {
        const match = stack.match(/plugin:([^:]+)/);
        if (match) {
          const id = match[1];
          if (!renderWarnings.hasOwnProperty(id)) {
            renderWarnings[id] = true;
            console.error(new Error('Plugin "' + id + '" is not passing Component in renderMarkdown. This is needed to avoid memory leaks when embedded contents register global event handlers.'));
          }
        }
      }
    }
    const tree = host.markdownTree(markdown);
    const frontmatter = host.treeFrontmatter(tree);
    const html = host.sanitizeHtml(host.treeToHtml(tree));
    el.appendChild(html);
    const promises = [];
    const ctx = {
      docId: randomHex(16),
      sourcePath,
      frontmatter,
      promises,
      addChild: (child) => component && component.addChild(child),
      getSectionInfo: () => null,
      replace: () => null,
      containerEl: el,
      el,
      displayMode: true,
    };
    const postProcessors = host.MarkdownPreviewRenderer.postProcessors;
    for (let i = 0; i < postProcessors.length; i++) {
      const result = postProcessors[i](el, ctx);
      if (result && result.then) promises.push(result);
    }
    if (app && component) {
      const depth = host.embedDepth(el);
      const embeds = el.findAll(".internal-embed:not(.is-loaded)");
      if (embeds.length > 0) {
        for (let i = 0; i < embeds.length; i++) {
          const embed = embeds[i];
          const linktext = embed.getAttribute("src");
          const child = host.EmbedLoader.load({
            app, linktext, sourcePath, containerEl: embed, displayMode: true, showInline: true, depth,
          });
          if (child) {
            ctx.addChild(child);
            promises.push(child.loadFile());
          }
        }
      }
    }
    return promises.length > 0 ? Promise.all(promises).then() : Promise.resolve();
  };

  return MarkdownRenderer;
}

// ---- n-g24-markdown-view.js ----
// MarkdownView: a markdown leaf that owns two "modes" — the source/live-preview editor mode
// (j6, still inherited) and the reading preview mode (fq, own). It keeps the inline title,
// the properties metadata editor, the embedded backlinks pane, view state (mode/source/
// backlinks), scroll sync between modes, fold persistence and the pane menu.

const VIEW_TYPE = "markdown";

function isBoolean(value) { return typeof value === "boolean"; }

function defineMarkdownView(host) {
  function MarkdownView(leaf) {
    const self = host.TextFileView.call(this, leaf) || this;
    self.icon = "lucide-file";
    self.modeButtonEl = null;
    self.modes = {};
    self.currentMode = null;
    self.scroll = null;
    self.showBacklinks = false;
    self.rawFrontmatter = null;
    self.scope = self.initialScope = new host.Scope(self.app.scope);
    self.editMode = self.registerMode(new host.MarkdownEditMode(self));
    self.sourceMode = { cmEditor: self.editor };
    self.previewMode = self.registerMode(new host.MarkdownPreviewView(self));

    const titleEl = self.inlineTitleEl = createDiv("inline-title");
    titleEl.contentEditable = "true";
    titleEl.spellcheck = self.app.vault.getConfig("spellcheck");
    titleEl.autocapitalize = "on";
    titleEl.tabIndex = -1;
    titleEl.enterKeyHint = host.Platform.isAndroidApp ? "enter" : "done";
    titleEl.addEventListener("focus", () => { self.fileBeingRenamed = self.file; });
    titleEl.addEventListener("blur", () => self.onInlineTitleBlur());
    titleEl.addEventListener("input", () => self.onTitleChange(titleEl));
    titleEl.addEventListener("paste", (event) => self.onTitlePaste(titleEl, event));
    titleEl.addEventListener("keydown", self.onTitleKeydown.bind(self));

    self.metadataEditor = new host.MetadataEditor(self.app, self);
    self.addChild(self.metadataEditor);
    self.backlinksEl = createDiv("embedded-backlinks");
    self.backlinksEl.hide();
    self.modeButtonEl = self.addAction("lucide-book-open", "", self.onSwitchView.bind(self));

    const modes = self.modes;
    for (const key in modes) if (modes.hasOwnProperty(key)) modes[key].hide();

    let defaultMode = self.app.vault.getConfig("defaultViewMode");
    if (!defaultMode || !modes.hasOwnProperty(defaultMode)) defaultMode = "source";
    self.currentMode = modes[defaultMode];
    self.containerEl.setAttribute("data-mode", self.getMode());
    self.currentMode.show();
    self.updateButtons();
    self.showBacklinks = self.app.workspace.backlinkInDocument;
    self.updateShowBacklinks();
    self.addChild(self.previewMode);

    // ctrl/cmd + wheel adjusts the base font size (with a 500 ms rate limit per direction change)
    let lastWheelTime = 0;
    self.containerEl.addEventListener("wheel", (event) => {
      if (self.app.vault.getConfig("baseFontSizeAction")) {
        const isZoom = event.ctrlKey;
        const now = Date.now();
        if (isZoom && !(lastWheelTime > now - 500)) {
          if (isZoom && event.deltaY !== 0) {
            if (host.isMacOS && Number.isInteger(event.deltaY)) return;
            let size = self.app.vault.getConfig("baseFontSize");
            if (event.deltaY < 0) size++; else size--;
            size = Math.clamp(size, 10, 30);
            self.app.vault.setConfig("baseFontSize", size);
          }
        } else lastWheelTime = now;
      }
    }, { passive: true });
    return self;
  }
  inherit(MarkdownView, host.TextFileView);

  Object.defineProperty(MarkdownView.prototype, "editor", {
    get() { return this.editMode.editor; },
    enumerable: false, configurable: true,
  });

  const proto = MarkdownView.prototype;

  proto.replaceScope = function (scope) { this.scope = scope || this.initialScope; };

  proto.saveFrontmatter = function (frontmatter) {
    const data = host.spliceFrontmatter(this.getViewData(), frontmatter);
    this.setViewData(data, false);
    this.onInternalDataChange();
    this.save();
  };

  proto.getFile = function () { return this.file; };

  proto.shiftFocusAfter = function () {
    this.setEphemeralState({ focus: true, focusOnMobile: true, cursor: { from: { line: 0, ch: 0 } } });
  };

  proto.shiftFocusBefore = function () {
    if (this.canShowProperties() && !this.metadataEditor.hasFocus()) {
      this.metadataEditor.focus({ bottom: true });
    } else if (this.inlineTitleEl.isShown()) {
      host.focusAndSelectContents(this.inlineTitleEl);
    }
  };

  proto.onInlineTitleBlur = function () {
    return Promise.resolve().then(async () => {
      const changed = await this.saveTitle(this.inlineTitleEl);
      if (!changed) this.inlineTitleEl.setText(this.file.basename);
      host.hideTooltip();
    });
  };

  proto.onload = function () {
    host.TextFileView.prototype.onload.call(this);
    const leaf = this.leaf;
    this.registerEvent(leaf.workspace.on("quick-preview", this.onExternalDataChange, this));
    this.registerEvent(leaf.workspace.on("resize", this.onResize, this));
    this.registerEvent(leaf.workspace.on("css-change", this.onCssChange, this));
    this.registerEvent(this.app.vault.on("config-changed", this.onConfigChanged, this));
    this.onResize();
  };

  proto.onClose = function () {
    return Promise.resolve().then(() => host.TextFileView.prototype.onClose.call(this))
      .then(() => { this.editMode.destroy(); });
  };

  proto.getViewType = function () { return VIEW_TYPE; };

  proto.canAcceptExtension = function (extension) {
    return host.markdownExtensions.contains(extension);
  };

  proto.getState = function () {
    const state = host.TextFileView.prototype.getState.call(this);
    state.mode = this.getMode();
    state.source = this.editMode.sourceMode;
    state.backlinks = this.showBacklinks;
    if (state.backlinks) state.backlinkOpts = this.backlinks.getState();
    return state;
  };

  proto.setState = function (state, result) {
    return (async () => {
      let needsLayout = false;
      const mode = state.mode;
      const backlinks = state.backlinks;
      const backlinkOpts = state.backlinkOpts;
      const source = state.source;
      if (mode) {
        const modes = this.modes;
        if (modes.hasOwnProperty(mode)) needsLayout = await this.setMode(modes[mode]);
      }
      const editMode = this.editMode;
      if (typeof source === "boolean" && editMode.sourceMode !== source) {
        editMode.toggleSource();
        needsLayout = true;
      }
      if (isBoolean(backlinks)) {
        this.showBacklinks = backlinks;
        this.updateShowBacklinks();
        if (backlinks && backlinkOpts && typeof backlinkOpts === "object") this.backlinks.setState(backlinkOpts);
      }
      if (needsLayout) result.layout = true;
      await host.TextFileView.prototype.setState.call(this, state, result);
    })();
  };

  proto.getEphemeralState = function () {
    const state = host.TextFileView.prototype.getEphemeralState.call(this);
    this.currentMode.getEphemeralState(state);
    if (this.scroll !== null) state.scroll = this.scroll;
    return state;
  };

  proto.setEphemeralState = function (state) {
    const rename = state.rename;
    if (rename) {
      let collapse;
      if (rename === "start") collapse = true;
      else if (rename === "end") collapse = false;
      if (this.inlineTitleEl.isShown()) {
        const scroll = this.currentMode === this.editMode
          ? this.editMode.cm.scrollDOM.scrollTop
          : this.previewMode.getScroll();
        if (scroll < 0.5) {
          host.focusAndSelectContents(this.inlineTitleEl, collapse);
          delete state.rename;
        }
      }
    }
    host.TextFileView.prototype.setEphemeralState.call(this, state);
    const subpath = state.subpath;
    if (subpath) {
      const pos = host.subpathToPos(this.app.metadataCache.getFileCache(this.file), subpath);
      if (pos) {
        state.line = pos.start.line;
        state.startLoc = pos.start;
        state.endLoc = pos.end || null;
      }
    }
    this.currentMode.setEphemeralState(state);
    if (state.hasOwnProperty("scroll")) this.scroll = state.scroll;
  };

  proto.onUnloadFile = function (file) {
    return Promise.resolve().then(() => {
      this.onMarkdownFold();
      this.currentMode.beforeUnload();
      this.rawFrontmatter = null;
      this.metadataEditor.clear();
      this.editMode.setCssClass(null);
      return host.TextFileView.prototype.onUnloadFile.call(this, file);
    });
  };

  proto.registerMode = function (mode) {
    this.modes[mode.type] = mode;
    return mode;
  };

  proto.getMode = function () { return this.currentMode.type; };

  proto.getHoverSource = function () { return this.editMode ? "editor" : "preview"; };

  proto.toggleMode = function () {
    const leaf = this.leaf;
    const viewState = leaf.getViewState();
    viewState.state.mode = viewState.state.mode === "preview" ? "source" : "preview";
    leaf.setViewState(viewState, { focus: true });
  };

  proto.updateButtons = function () {
    const mode = this.currentMode;
    const button = this.modeButtonEl;
    const modClick = host.t.interface.menu.modClickOpenNewTab({ key: host.keyNames.Mod });
    if (mode.type === "source") {
      host.setIcon(button, "lucide-book-open");
      host.setTooltip(button, host.t.interface.menu.editView() + "\n" + host.t.interface.menu.switchToReadView() + "\n" + modClick);
    } else {
      host.setIcon(button, "lucide-edit-3");
      host.setTooltip(button, host.t.interface.menu.readView() + "\n" + host.t.interface.menu.switchToEditView() + "\n" + modClick);
    }
  };

  proto.setMode = function (mode) {
    return (async () => {
      if (!mode || this.currentMode === mode) return false;
      const previous = this.currentMode;
      const scroll = this.scroll;
      if (previous.type === "source") await this.save();
      const foldInfo = previous.getFoldInfo();
      this.app.foldManager.save(this.file, foldInfo);
      previous.hide();
      this.currentMode = mode;
      mode.show();
      if (this.data !== null) mode.set(this.data, false);
      mode.onResize();
      if (scroll !== null) mode.setEphemeralState({ scroll });
      mode.applyFoldInfo(foldInfo);
      this.metadataEditor.setCollapse(!!foldInfo && foldInfo.folds.some((fold) => fold.from === 0), false);
      this.updateButtons();
      this.containerEl.setAttribute("data-mode", this.getMode());
      return true;
    })();
  };

  proto.getViewData = function () { return this.currentMode.get(); };

  proto.clear = function () {
    const currentMode = this.currentMode;
    const editMode = this.editMode;
    const modes = this.modes;
    if (currentMode === editMode) this.onMarkdownFold();
    this.scroll = null;
    for (const key in modes) if (modes.hasOwnProperty(key)) modes[key].clear();
  };

  Object.defineProperty(MarkdownView.prototype, "path", {
    get() { return this.file.path; },
    enumerable: false, configurable: true,
  });

  proto.onSwitchView = function (event) {
    return (async () => {
      event.preventDefault();
      const leaf = this.leaf;
      const state = this.getState();
      state.mode = this.getMode() === "preview" ? "source" : "preview";
      const viewState = { type: VIEW_TYPE, state };
      if (host.Keymap.isModEvent(event)) {
        const workspace = this.app.workspace;
        const newLeaf = workspace.createLeafBySplit(this.leaf);
        viewState.active = true;
        viewState.group = this.leaf;
        await newLeaf.setViewState(viewState, { focus: true });
      } else {
        await leaf.setViewState(viewState, { focus: true });
      }
    })();
  };

  proto.canToggleBacklinks = function () {
    return this.getMode() === "preview" || this.editMode instanceof host.MarkdownEditMode;
  };

  proto.toggleBacklinks = function () {
    return (async () => {
      const state = this.getState();
      state.backlinks = !state.backlinks;
      await this.leaf.setViewState({ type: VIEW_TYPE, state });
      this.app.workspace.requestSaveLayout();
    })();
  };

  proto.updateShowBacklinks = function () {
    const show = this.showBacklinks;
    const app = this.app;
    const backlinks = this.backlinks;
    if (show && !backlinks) {
      this.backlinksEl.show();
      this.backlinks = this.addChild(new host.BacklinksPane(app, this.backlinksEl));
      this.updateBacklinks();
    } else if (!show && backlinks) {
      this.removeChild(backlinks);
      this.backlinksEl.empty();
      this.backlinksEl.hide();
      this.backlinks = null;
    }
    if (this.currentMode === this.editMode) this.editMode.onResize();
  };

  proto.updateBacklinks = function () {
    const backlinks = this.backlinks;
    if (backlinks) {
      backlinks.file = this.file;
      backlinks.update();
    }
  };

  proto.onLoadFile = function (file) {
    return Promise.resolve().then(() => {
      this.inlineTitleEl.setText(this.getDisplayText());
      return host.TextFileView.prototype.onLoadFile.call(this, file);
    }).then(() => { this.updateBacklinks(); });
  };

  proto.onRename = function (file) {
    return (async () => {
      if (file === this.file) this.inlineTitleEl.setText(file.basename);
      await host.TextFileView.prototype.onRename.call(this, file);
    })();
  };

  proto.syncScroll = function () {
    const scroll = this.currentMode.getScroll();
    if (scroll !== null) this.scroll = scroll;
    this.app.workspace.trigger("markdown-scroll", this);
    this.syncState();
  };

  proto.receiveSyncState = function (other) {
    if (this.file !== other.file) {
      this.leaf.openFile(other.file, { eState: other.getEphemeralState() });
    } else {
      this.setEphemeralState(other.getEphemeralState());
    }
  };

  proto.onMarkdownFold = function () {
    this.app.foldManager.save(this.file, this.currentMode.getFoldInfo());
  };

  proto.onPaneMenu = function (menu, leaf) {
    host.TextFileView.prototype.onPaneMenu.call(this, menu, leaf);
    const mode = this.getMode();
    const self = this;
    menu.addItem((item) => item
      .setSection("pane")
      .setTitle(host.t.interface.menu.toggleReadingView())
      .setChecked(mode === "preview")
      .setIcon("lucide-book-open")
      .onClick(self.onSwitchView.bind(self)));
    menu.addItem((item) => item
      .setSection("action")
      .setTitle(host.t.interface.menu.addProperty())
      .setDisabled(!this.canShowProperties())
      .setIcon("lucide-plus-circle")
      .onClick(() => host.propertiesPlugin(this.app).then((properties) => properties.addProperty())));
    if (mode === "source") {
      menu.addItem((item) => item
        .setSection("pane")
        .setTitle(host.t.interface.menu.toggleSourceMode())
        .setIcon("lucide-code-2")
        .setChecked(!!this.getState().source)
        .onClick(() => {
          const state = this.getState();
          state.source = !state.source;
          this.leaf.setViewState({ type: VIEW_TYPE, state });
        }));
    }
    menu.addItem((item) => item
      .setSection("find")
      .setTitle(host.t.interface.menu.find())
      .setIcon("lucide-file-search")
      .onClick(() => this.showSearch()));
    menu.addItem((item) => item
      .setSection("find")
      .setDisabled(mode !== "source")
      .setTitle(host.t.interface.menu.replace())
      .setIcon("lucide-file-search")
      .onClick(() => this.showSearch(true)));
    if (host.Platform.canExportPdf) {
      menu.addItem((item) => item
        .setSection("action")
        .setTitle(host.tc.exportPdf())
        .setIcon("lucide-file-down")
        .onClick(() => this.printToPdf()));
    }
  };

  proto.onResize = function () { this.currentMode.onResize(); };

  proto.onCssChange = function () { this.editMode.onCssChange(); };

  proto.loadFrontmatter = function (data) {
    const frontmatter = host.extractFrontmatter(data).frontmatter;
    if (this.rawFrontmatter === null || this.rawFrontmatter !== frontmatter) {
      this.rawFrontmatter = frontmatter;
      let parsed;
      try {
        parsed = host.parseYaml(frontmatter) ?? {};
        if (typeof parsed !== "object" || Array.isArray(parsed)) {
          throw new Error("Frontmatter must be a valid object!");
        }
      } catch (e) {
        parsed = null;
      }
      this.editMode.setCssClass(host.frontmatterClasses(parsed));
      this.metadataEditor.synchronize(parsed);
    }
  };

  proto.onInternalDataChange = function () {
    const data = this.currentMode.get();
    if (this.data !== data) {
      this.data = data;
      this.leaf.workspace.onQuickPreview(this.file, this.data);
      this.loadFrontmatter(data);
    }
  };

  proto.onExternalDataChange = function (file, data) {
    if (file === this.file) this.setData(data, false);
  };

  proto.setViewData = function (data, isNewFile) {
    const currentMode = this.currentMode;
    const modes = this.modes;
    if (isNewFile) {
      this.scroll = null;
      for (const key in modes) if (modes.hasOwnProperty(key)) modes[key].set(data, true);
      const foldInfo = this.app.foldManager.load(this.file);
      if (foldInfo) currentMode.applyFoldInfo(foldInfo);
      this.metadataEditor.setCollapse(!!foldInfo && foldInfo.folds.some((fold) => fold.from === 0), false);
    } else {
      currentMode.set(data, false);
    }
    this.loadFrontmatter(data);
  };

  proto.onConfigChanged = function (key) {
    if (key === "spellcheck") this.inlineTitleEl.spellcheck = this.app.vault.getConfig("spellcheck");
  };

  proto.updateOptions = function () {
    const modes = this.modes;
    for (const key in modes) if (modes.hasOwnProperty(key)) modes[key].updateOptions();
  };

  proto.showSearch = function (replace) {
    if (replace === undefined) replace = false;
    this.currentMode.showSearch(replace);
  };

  proto.canShowProperties = function () {
    return (this.getMode() !== "source" || !this.editMode.sourceMode)
      && this.app.vault.getConfig("propertiesInDocument") === "visible";
  };

  proto.undo = function () { this.editMode.editor.undo(); };

  proto.redo = function () { this.editMode.editor.redo(); };

  proto.metadataHasFocus = function () { return this.metadataEditor.hasFocus(); };

  proto.getSelection = function () { return this.currentMode.getSelection(); };

  proto.printToPdf = function () {
    new host.PrintToPdfModal(this.app, this.file).open();
  };

  proto.triggerClickableToken = function (token, event) {
    const self = this;
    if (token.type === "internal-link") {
      setTimeout(() => {
        self.app.workspace.openLinkText(token.text, self.file.path, event);
      }, 100);
    } else if (token.type === "external-link") {
      window.open(token.text);
    } else if (token.type === "tag") {
      let tag = token.text;
      if (!tag.startsWith("#")) tag = "#" + tag;
      const search = this.app.internalPlugins.getEnabledPluginById("global-search");
      if (search) search.openGlobalSearch("tag:" + tag);
    }
  };

  proto.handleCut = function (event) {
    if (this.metadataEditor.hasFocus()) this.metadataEditor.handleCut(event);
  };

  proto.handleCopy = function (event) {
    if (this.metadataEditor.hasFocus()) this.metadataEditor.handleCopy(event);
  };

  proto.handlePaste = function (event) {
    if (event.clipboardData.getData("basalt/properties")) this.metadataEditor.handlePaste(event);
  };

  MarkdownView.VIEW_TYPE = VIEW_TYPE;
  return MarkdownView;
}

// ---- n-g24-outline.js ----
// The "Outline" core plugin: a side-pane tree of the current note's headings.
//
// Replaces the inherited pieces:
//   p7  OutlinePlugin        -> defineOutlinePlugin
//   d7  OutlineView          -> defineOutlineView    (base: the shared link-pane view)
//   h7  OutlineTreeItem      -> defineOutlineTreeItem (base: collapsible tree item)
//   c7  "outline" view type  -> declarator "outline"
//
// The view keeps a reconciled list of heading rows inside the shared Tree/InfinityScroll widget,
// follows the cursor or the preview scroll position, offers a search filter and supports
// drag-reordering of heading sections inside the note.

const s34OutlineViewType = "outline";
const outlineT = (host) => host.t.plugins.outline;

function s34IsBoolean(value) {
  return typeof value === "boolean";
}

/** Reconciles `existing` against `desired` in place (same contract as the inherited yy helper). */
function reconcileItems(existing, desired, matches, create) {
  for (let o = 0; o < desired.length; o++) {
    const wanted = desired[o];
    let found = -1;
    for (let l = o; l < existing.length; l++) {
      if (matches(existing[l], wanted)) {
        found = l;
        break;
      }
    }
    if (found !== -1) {
      if (o !== found) {
        const tmp = existing[o];
        existing[o] = existing[found];
        existing[found] = tmp;
      }
    } else {
      existing.splice(o, 0, create(wanted));
    }
  }
  existing.length = desired.length;
}

// The plugin and the view/item factories run at different bundle positions; they reach each
// other through this registry.
const outlineParts = {};

/** One heading row of the outline tree. */
function defineOutlineTreeItem(host) {
  const ItemBase = ng15CollapsibleTreeItem(host.TreeItem);

  function OutlineTreeItem(view, tree, heading) {
    const self = ItemBase.call(this) || this;
    self.pusherEl = ng15MakeTreePusher();
    self.info = { height: 0, width: 0, childLeft: 0, childLeftPadding: 0, childTop: 0, computed: false, queued: false, hidden: false, next: false };
    self.vChildren = new host.TreeChildren(self);
    self.view = view;
    self.tree = tree;
    self.heading = heading;
    self.setClickable(true);
    self.setCollapsible(false);
    self.headingText = s05HeadingText(self.heading);
    self.innerEl.setText(self.headingText);
    return self;
  }
  inherit(OutlineTreeItem, ItemBase);
  const proto = OutlineTreeItem.prototype;

  proto.onSelfClick = function () {
    const view = this.view;
    const leaf = view.findCorrespondingLeaf();
    const state = { line: this.heading.position.start.line };
    if (leaf) {
      view.leaf.workspace.setActiveLeaf(leaf, { focus: true });
      leaf.view.setEphemeralState(state);
    } else {
      const app = view.app;
      const file = view.file;
      const newLeaf = app.workspace.getLeaf();
      newLeaf.openFile(file, { eState: state });
    }
  };

  proto.updateCollapsed = async function (collapsed) {
    if (!this.collapsed) this.tree.handleCollapseAll?.(false);
    await ItemBase.prototype.updateCollapsed.call(this, collapsed);
    this.tree.infinityScroll.invalidate(this);
  };

  outlineParts.OutlineTreeItem = OutlineTreeItem;
  return OutlineTreeItem;
}

/** The outline view: heading tree + search + follow-cursor for the active markdown file. */
function defineOutlineView(host) {
  const backlinksT = () => host.t.plugins.backlinks;
  const searchT = () => host.t.plugins.search;
  const fileExplorerT = () => host.t.plugins.fileExplorer;
  const tagPaneT = () => host.t.plugins.tagPane;

  function OutlineView(leaf, plugin) {
    const self = host.LinkPaneView.call(this, leaf) || this;
    self.icon = "lucide-list";
    self.activeEl = null;
    self.searchQuery = null;
    self.cachedHeadingDom = [];
    self.isShowingSearch = false;
    self.followCursor = false;
    self.onSelectionChange = debounceCall(self.handleSelectionChange.bind(self), 20);
    self.prevQuery = "";
    self.plugin = plugin;
    const contentEl = self.contentEl;
    self.scope = new host.Scope(self.app.scope);
    self.tree = new host.Tree(self, {
      app: self.app,
      containerEl: contentEl,
      id: s34OutlineViewType,
      scope: self.scope,
      handleCollapseAll: self.handleCollapseAll.bind(self),
    });
    self.tree.isAllCollapsed = false;
    const header = new host.ViewHeader(self.app, self.containerEl);
    self.showSearchButtonEl = header.addNavButton("lucide-search", backlinksT().labelShowSearch(), self.onToggleShowSearch.bind(self));
    self.searchComponent = new host.SearchComponent(header.navHeaderEl)
      .setPlaceholder(searchT().promptStartSearch())
      .onChange(debounceCall(self.updateSearch.bind(self), 300, true))
      .then((component) => {
        setElementTooltip(component.clearButtonEl, searchT().tooltipClearSearch());
        component.inputEl.addEventListener("keypress", (event) => {
          if (event.isComposing) return;
          if (event.key !== "Enter") return;
          if (!host.Platform.hasPhysicalKeyboard) host.blurAndClearSelection();
          self.updateSearch();
        });
        component.containerEl.hide();
      });
    self.followCursorButtonEl = header.addNavButton("lucide-gallery-vertical", outlineT(host).labelFollowCursor(), self.onToggleFollowCursor.bind(self));
    self.collapseOrExpandAllEl = header.addNavButton("lucide-chevrons-down-up", fileExplorerT().actionCollapseAll(), () => self.tree.toggleCollapseAll());
    self.emptyEl = self.contentEl.createDiv({ cls: "pane-empty", text: outlineT(host).labelNoHeadings() });
    self.app.dragManager.handleDrop(contentEl, (event, dragInfo, isOver) => {
      if (dragInfo.source !== "outline" || dragInfo.type !== "heading" || dragInfo.file !== self.file) return;
      if (!self.tree.root.vChildren.hasChildren()) return;
      const drop = ng15TreeDropPosition(event, self.tree);
      const indicator = ng15UpdateTreeDropIndicator(self.tree, drop, [], isOver);
      if (!isOver) {
        (async () => {
          const cache = self.app.metadataCache.getFileCache(self.file);
          if (!cache?.headings || !drop?.node) return;
          const headings = cache.headings;
          const dragged = dragInfo.heading;
          const fromIndex = headings.indexOf(dragged);
          let toIndex = headings.indexOf(drop.node.heading);
          let anchor = drop.node.heading;
          if (toIndex === -1 || fromIndex === -1) return;
          if (drop.placement === "after") {
            toIndex++;
            anchor = headings[toIndex];
          }
          if (fromIndex === toIndex) return;
          let sectionEnd = fromIndex + 1;
          while (sectionEnd < headings.length && !(headings[sectionEnd].level <= dragged.level)) sectionEnd++;
          const startOffset = dragged.position.start.offset;
          let endOffset = sectionEnd < headings.length ? headings[sectionEnd].position.start.offset : -1;
          let anchorOffset = anchor ? anchor.position.start.offset : -1;
          const insertAt = Math.max(startOffset, endOffset, anchorOffset) + 1;
          const writeEnd = endOffset === -1 ? insertAt : endOffset;
          const anchorPos = anchorOffset === -1 ? insertAt : anchorOffset;
          if (anchorPos >= startOffset && anchorPos <= writeEnd) return;
          const content = await self.app.vault.read(self.file);
          if (endOffset === -1) endOffset = content.length;
          if (anchorOffset === -1) anchorOffset = content.length;
          const section = endWithBlankLine(content.substring(startOffset, endOffset));
          const next =
            anchorOffset < startOffset
              ? endWithBlankLine(content.substring(0, anchorOffset)) +
                section +
                content.substring(anchorOffset, startOffset) +
                content.substring(endOffset)
              : content.substring(0, startOffset) +
                endWithBlankLine(content.substring(endOffset, anchorOffset)) +
                section +
                content.substring(anchorOffset);
          await self.app.vault.modify(self.file, next);
        })();
      }
      return { dropEffect: "move", hoverEl: indicator, hoverClass: "is-active" };
    }, { dropEffect: "move", hoverEl: header, hoverClass: "is-active" });
    return self;
  }
  inherit(OutlineView, host.LinkPaneView);
  const proto = OutlineView.prototype;

  /** The markdown leaf showing this file (any group), used for cursor/scroll following. */
  proto.findCorrespondingLeaf = function () {
    const leaf = this.leaf;
    const group = leaf.group;
    const workspace = leaf.workspace;
    let leaves;
    if (group) leaves = workspace.getGroupLeaves(group);
    else {
      leaves = [];
      const active = workspace.getActiveFileView();
      if (active) leaves.push(active.leaf);
    }
    for (const candidate of leaves) {
      if (candidate && candidate.view instanceof host.MarkdownView && candidate.view.file === this.file) return candidate;
    }
    return null;
  };

  proto.handleCollapseAll = function (collapsed) {
    this.tree.isAllCollapsed = collapsed;
    if (collapsed) {
      host.setIcon(this.collapseOrExpandAllEl, "lucide-chevrons-up-down");
      setElementTooltip(this.collapseOrExpandAllEl, tagPaneT().actionExpandAll());
    } else {
      host.setIcon(this.collapseOrExpandAllEl, "lucide-chevrons-down-up");
      setElementTooltip(this.collapseOrExpandAllEl, tagPaneT().actionCollapseAll());
    }
  };

  proto.getDisplayText = function () {
    if (!this.file || host.Platform.isMobile) return outlineT(host).name();
    return outlineT(host).tabTitle({ displayText: host.LinkPaneView.prototype.getDisplayText.call(this) });
  };

  proto.getViewType = function () {
    return s34OutlineViewType;
  };

  proto.getState = function () {
    const state = host.LinkPaneView.prototype.getState.call(this);
    state.followCursor = this.followCursor;
    state.showSearch = this.isShowingSearch;
    state.searchQuery = this.searchComponent.getValue();
    return state;
  };

  proto.setState = async function (state, result) {
    await host.LinkPaneView.prototype.setState.call(this, state, result);
    const followCursor = state.followCursor;
    const searchQuery = state.searchQuery;
    const showSearch = state.showSearch;
    if (s34IsBoolean(followCursor)) this.setFollowCursor(followCursor);
    if (s34IsBoolean(showSearch)) this.setShowSearch(showSearch);
    if (String.isString(searchQuery)) {
      this.searchComponent.setValue(searchQuery);
      this.updateSearch();
    }
  };

  proto.canAcceptExtension = function () {
    return true;
  };

  proto.onload = function () {
    this.registerEvent(this.app.workspace.on("editor-selection-change", this.onSelectionChange));
    this.registerEvent(this.app.workspace.on("markdown-scroll", debounceCall(this.onMarkdownScroll.bind(this), 20)));
    this.registerEvent(this.app.metadataCache.on("changed", this.onFileChanged, this));
  };

  /** Heading under the cursor (edit mode) or under the preview scroll position. */
  proto.findActiveHeading = function (view) {
    if (!view) return null;
    let result = null;
    if (view.getMode() === "preview") {
      const scroll = view.scroll;
      ng15WalkTree(this.tree.root, (item) => {
        if (scroll >= item.heading.position.end.line) result = item;
      });
    } else if (view.file) {
      const selection = view.editor.listSelections().first();
      const heading = ng08HeadingAtPosition(this.app, view.file, selection.head);
      ng15WalkTree(this.tree.root, (item) => {
        if (item.heading === heading) {
          result = item;
          return true;
        }
      });
    }
    return result;
  };

  proto.setHighlightedItem = function (item) {
    if (item?.selfEl === this.activeEl) return;
    this.activeEl?.removeClass("is-active");
    this.activeEl = null;
    if (item) {
      this.activeEl = item.selfEl;
      this.activeEl.addClass("is-active");
      if (this.followCursor) this.tree.infinityScroll.scrollIntoView(item, 20);
    }
  };

  proto.getOwner = function () {
    const editor = this.app.workspace.activeEditor;
    if (editor && editor.file === this.file && !(editor instanceof host.EmbedFileView && editor.subpath)) return editor;
    const leaf = this.findCorrespondingLeaf();
    if (leaf && leaf.view instanceof host.MarkdownView) return leaf.view;
    return null;
  };

  proto.onMarkdownScroll = function (view) {
    if (view.getMode() === "preview" && view === this.getOwner()) {
      const item = this.findActiveHeading(view);
      this.setHighlightedItem(item);
    }
  };

  proto.onFileChanged = function (file) {
    if (this.app.workspace.layoutReady && file === this.file) this.requestUpdate();
  };

  proto.handleSelectionChange = function (view, owner) {
    if (
      owner === this.getOwner() &&
      !(owner instanceof host.MarkdownView && owner.dirty) &&
      !(owner instanceof host.MarkdownEmbedBase && owner.dirty)
    ) {
      const item = this.findActiveHeading(owner);
      this.setHighlightedItem(item);
    }
  };

  proto.createItemDom = function (heading) {
    const self = this;
    const item = new outlineParts.OutlineTreeItem(this, this.tree, heading);
    this.app.dragManager.handleDrag(item.selfEl, (event) => {
      self.app.dragManager.updateSource([item.selfEl], "is-being-dragged");
      ng08SetDragPlainData(event.dataTransfer, item.heading.heading);
      return {
        source: "outline",
        type: "heading",
        icon: "heading-glyph",
        title: item.heading.heading,
        heading: item.heading,
        file: self.file,
      };
    });
    const selfEl = item.selfEl;
    selfEl.addEventListener("mouseover", (event) => {
      if (!host.pointerEntered(event, selfEl) || host.isTouchSyntheticMouse(event)) return;
      const linktext = self.file.path + "#" + linkSafeHeading(heading.heading);
      self.app.workspace.trigger("hover-link", { event, source: "outline", hoverParent: self, targetEl: selfEl, linktext });
    });
    return item;
  };

  proto.update = function () {
    if (this.file !== this.cachedFile) {
      this.activeEl = null;
      this.cachedHeadingDom = [];
      this.cachedFile = this.file;
    }
    this.tree.root.vChildren.clear();
    const headings = this.getHeadings();
    if (headings.length > 0) {
      const items = this.cachedHeadingDom;
      this.emptyEl.detach();
      reconcileItems(
        items,
        headings,
        (item, heading) => {
          const current = item.heading;
          const same = current.level === heading.level && current.heading === heading.heading;
          if (same) {
            item.heading = heading;
            if (item.vChildren.hasChildren()) item.vChildren.clear();
          }
          return same;
        },
        (heading) => this.createItemDom(heading)
      );
      const stack = [];
      for (const item of items) {
        const heading = item.heading;
        let parent = stack[stack.length - 1];
        while (parent && parent.heading.level >= heading.level) {
          stack.pop();
          parent = stack[stack.length - 1];
        }
        stack.push(item);
        if (parent) {
          parent.vChildren.addChild(item);
          parent.setCollapsible(true);
        } else {
          this.tree.root.vChildren.addChild(item);
        }
      }
    } else {
      this.contentEl.appendChild(this.emptyEl);
    }
    const active = this.findActiveHeading(this.getOwner());
    this.setHighlightedItem(active);
    this.filterSearchResults();
    this.tree.infinityScroll.queueCompute();
  };

  /** Applies the search filter: matching rows get their heading text highlighted, others hidden. */
  proto.filterSearchResults = function () {
    const tree = this.tree;
    const filtering = !!this.searchQuery;
    const query = this.searchQuery?.query ?? "";
    const queryChanged = query !== this.prevQuery;
    this.prevQuery = query;
    ng15WalkTree(tree.root, (item) => {
      if (filtering) {
        const match = this.searchQuery.matchContent(item.heading.heading);
        if (match) {
          if (!queryChanged && item.innerEl.hasClass("is-match")) return;
          item.innerEl.empty();
          item.innerEl.addClass("is-match");
          renderMatches(item.innerEl, item.headingText, match.content);
          let node = item;
          while (node) {
            node.el.show();
            node = node.parent;
          }
        } else {
          if (!queryChanged && !item.innerEl.hasClass("is-match")) return;
          item.innerEl.removeClass("is-match");
          item.innerEl.setText(item.headingText);
          item.el.hide();
        }
      } else {
        if (!queryChanged && !item.innerEl.hasClass("is-match")) return;
        item.innerEl.removeClass("is-match");
        item.innerEl.setText(item.headingText);
        item.el.show();
      }
      tree.infinityScroll.invalidate(item);
    });
  };

  proto.getHeadings = function () {
    const file = this.file;
    if (!file || file.extension !== "md") return [];
    const cache = this.app.metadataCache.getFileCache(file);
    if (!cache) return [];
    const headings = cache.headings;
    return headings && headings.length !== 0 ? headings : [];
  };

  proto.setFollowCursor = function (follow) {
    if (follow === this.followCursor) return;
    this.followCursor = follow;
    this.followCursorButtonEl.toggleClass("is-active", follow);
  };

  proto.onToggleFollowCursor = function () {
    this.setFollowCursor(!this.followCursor);
    if (this.followCursor) {
      const item = this.findActiveHeading(this.getOwner());
      if (item) this.tree.infinityScroll.scrollIntoView(item, 20);
    }
    this.app.workspace.requestSaveLayout();
  };

  proto.onToggleShowSearch = function () {
    this.setShowSearch(!this.isShowingSearch);
    if (this.isShowingSearch) this.searchComponent.inputEl.focus();
  };

  proto.showSearch = function () {
    this.setShowSearch(true);
    this.searchComponent.inputEl.focus();
  };

  proto.setShowSearch = function (show) {
    if (show === this.isShowingSearch) return;
    this.isShowingSearch = show;
    this.searchComponent.containerEl.toggle(show);
    this.showSearchButtonEl.toggleClass("is-active", show);
    if (!show) {
      this.searchComponent.setValue("");
      this.updateSearch();
    }
    this.app.workspace.requestSaveLayout();
  };

  proto.updateSearch = function () {
    const value = this.searchComponent.getValue();
    const current = this.searchQuery;
    if ((!current && !value) || (current && current.query === value)) return;
    try {
      if (value) {
        const query = new searchClasses.SearchQuery(this.app, value, false);
        this.searchQuery = query.matcher ? query : null;
      } else {
        this.searchQuery = null;
      }
      this.filterSearchResults();
    } catch (error) {
      console.log(error);
    }
  };

  outlineParts.OutlineView = OutlineView;
  return OutlineView;
}

/** The plugin shell: view type, open commands, file-menu entry, hover source and the "outline" CLI. */
function defineOutlinePlugin(host) {
  class OutlinePlugin {
    constructor() {
      this.id = "outline";
      this.name = outlineT(host).name();
      this.description = outlineT(host).desc();
      this.defaultOn = true;
    }

    init(app, plugin) {
      const self = this;
      this.app = app;
      this.plugin = plugin;
      plugin.registerViewType(s34OutlineViewType, (leaf) => new outlineParts.OutlineView(leaf, self));
      plugin.registerGlobalCommand({
        id: "outline:open",
        name: outlineT(host).actionShow(),
        icon: "lucide-list",
        callback: () => {
          self.app.workspace.ensureSideLeaf(s34OutlineViewType, "right", { active: true });
        },
      });
      plugin.registerGlobalCommand({
        id: "outline:open-for-current",
        name: outlineT(host).actionOpenForCurrent(),
        icon: "lucide-list",
        checkCallback: this.openTocForActiveFile.bind(this),
      });
    }

    onEnable(app, wrapper) {
      wrapper.registerEvent(app.workspace.on("layout-ready", this.initLeaf, this));
      wrapper.registerEvent(app.workspace.on("file-menu", this.onFileMenu, this));
      app.workspace.registerHoverLinkSource("outline", { display: this.name, defaultMod: true });
      wrapper.registerCliHandler(
        "outline",
        "Show headings for the current file",
        {
          file: { value: "<name>", description: "File name" },
          path: { value: "<path>", description: "File path" },
          format: { value: "tree|md|json", description: "Output format (default: tree)" },
          total: { description: "Return heading count" },
        },
        (args) => {
          const file = app.cli.tryResolveFile(args);
          if (file.extension !== "md") throw "File is not a markdown file.";
          const cache = app.metadataCache.getFileCache(file);
          const headings = cache?.headings;
          if (!headings || headings.length === 0) return "No headings found.";
          let list = headings;
          if (args.total) return String(list.length);
          if (args.format === "json") {
            return JSON.stringify(
              list.map((h) => ({ level: h.level, heading: h.heading, line: h.position.start.line + 1 })),
              null,
              2
            );
          }
          if (args.format === "md") {
            return list.map((h) => "#".repeat(h.level) + " " + h.heading).join("\n");
          }
          const roots = [];
          const stack = [];
          for (const heading of list) {
            const node = { label: heading.heading, children: [] };
            while (stack.length > 0 && stack[stack.length - 1].level >= heading.level) stack.pop();
            if (stack.length === 0) roots.push(node);
            else stack[stack.length - 1].node.children.push(node);
            stack.push({ node, level: heading.level });
          }
          return app.cli.formatAsciiTree(roots);
        }
      );
    }

    onUserEnable() {
      this.initLeaf();
    }

    initLeaf() {
      this.app.workspace.ensureSideLeaf(s34OutlineViewType, "right", { reveal: false });
    }

    onFileMenu(menu, file, source, leaf) {
      if (host.Platform.isMobile) return;
      if (!(file instanceof host.TFile) || !leaf || file.extension !== "md") return;
      if (source === "sidebar-context-menu") return;
      const self = this;
      menu.addItem((item) =>
        item
          .setSection("view.linked")
          .setTitle(outlineT(host).actionOpen())
          .setIcon("lucide-list")
          .onClick(async () => {
            await self.app.workspace.splitLeafOrActive(leaf, "vertical").setViewState({
              type: s34OutlineViewType,
              active: true,
              group: leaf,
              state: { file: file.path },
            });
          })
      );
    }

    openTocForActiveFile(checking) {
      const workspace = this.app.workspace;
      const file = workspace.getActiveFile();
      if (file) {
        if (!checking) {
          workspace.splitActiveLeaf("vertical").setViewState({
            type: s34OutlineViewType,
            active: true,
            group: workspace.activeLeaf,
            state: { file: file.path },
          });
        }
        return true;
      }
    }
  }
  return OutlinePlugin;
}

// ---- n-g24-tag-pane.js ----
// The tag pane (view type "tag"): a Tree of TagPaneItem rows built from metadataCache.getTags(), with
// nested "parent/child" tags, frequency / alphabetical sorting, an optional search filter that hides
// non-matching rows, and fold persistence under "tag-pane-fold".
//
// The view (bee) is a plain View that owns a TagPaneTree (yee, a Tree with a fixed fold key) and recycles
// TagPaneItem rows (gee, a collapsible tree item) across updates so their DOM survives.


// Classes defined by the factories below, visible to each other regardless of factory order.
const tagPane = {};

const VIEW_TYPE_TAG = "tag";
const FOLD_KEY = "tag-pane-fold";
const SORT_GROUPS = [["alphabetical", "alphabeticalReverse"], ["frequency", "frequencyReverse"]];

// =====================================================================================================================
// One tag row
// =====================================================================================================================

/** A collapsible tree item showing "parent/tag" split into parent prefix + leaf name, plus an occurrence count. */
function defineTagPaneItem(host) {
  const ItemBase = ng15CollapsibleTreeItem(host.TreeItem);

  function TagPaneItem(tree, tagView) {
    const self = ItemBase.call(this) || this;
    self.info = { height: 0, width: 0, childLeft: 0, childLeftPadding: 0, childTop: 0, computed: false, queued: false, hidden: false, next: false };
    self.tag = "";
    self.count = -1;
    self.vChildren = new host.TreeChildren(self);
    self.pusherEl = ng15MakeTreePusher();
    self.tree = tree;
    self.tagView = tagView;
    const selfEl = self.selfEl;
    const innerEl = self.innerEl;
    selfEl.addClass("tag-pane-tag");
    self.tagTextEl = innerEl.createDiv("tree-item-inner-text");
    self.tagCountEl = selfEl.createDiv("tree-item-flair-outer").createSpan("tag-pane-tag-count tree-item-flair");
    self.setCollapsible(true);
    self.setClickable(true);
    return self;
  }
  inherit(TagPaneItem, ItemBase);
  const proto = TagPaneItem.prototype;

  /** Click toggles the "tag:<tag>" clause of the global search (plain click replaces, mod-click toggles). */
  proto.onSelfClick = function (event) {
    const app = this.tagView.app;
    const query = "tag:" + this.tag;
    const plugin = app.internalPlugins.getEnabledPluginById("global-search");
    if (!plugin) return;
    const current = plugin.getGlobalSearchQuery();
    if (!host.Keymap.isModEvent(event) || current === "") {
      plugin.openGlobalSearch(query);
      return;
    }
    if (current.contains(query)) plugin.openGlobalSearch(current.replace(query, "").trim());
    else plugin.openGlobalSearch(current.trim() + " " + query);
    this.tagView.tree.setFocusedItem(null, false);
  };

  /** Stores the tag and renders it as "parent/" prefix + leaf name. */
  proto.setTag = function (tag) {
    if (this.tag !== tag) {
      this.tag = tag;
      let text = tag;
      if (text.startsWith("#")) text = text.substr(1);
      const parts = text.split("/");
      const leaf = parts[parts.length - 1];
      const parent = text.substr(0, text.length - leaf.length);
      const el = this.tagTextEl;
      el.empty();
      el.createSpan({ cls: "tag-pane-tag-parent", text: parent });
      el.createSpan({ cls: "tree-item-inner-text", text: leaf });
    }
    return this;
  };

  proto.setCount = function (count) {
    if (this.count !== count) {
      this.count = count;
      this.tagCountEl.setText(String(count));
    }
    return this;
  };

  proto.onCollapseClick = function (event) {
    ItemBase.prototype.onCollapseClick.call(this, event);
    this.tree.requestSaveFolds();
  };

  proto.updateCollapsed = async function (animate) {
    await ItemBase.prototype.updateCollapsed.call(this, animate);
    if (!this.collapsed) {
      const tree = this.tree;
      if (tree.handleCollapseAll) tree.handleCollapseAll(false);
    }
    this.tree.infinityScroll.invalidate(this);
  };

  tagPane.TagPaneItem = TagPaneItem;
  return TagPaneItem;
}

// =====================================================================================================================
// The tree: a Tree whose fold state is stored under a fixed key
// =====================================================================================================================

/** Tree subclass with the tag pane's fold key. */
function defineTagPaneTree(host) {
  function TagPaneTree() {
    return host.Tree.apply(this, arguments) || this;
  }
  inherit(TagPaneTree, host.Tree);
  TagPaneTree.prototype.getFoldKey = function () {
    return FOLD_KEY;
  };
  tagPane.TagPaneTree = TagPaneTree;
  return TagPaneTree;
}

// =====================================================================================================================
// The view
// =====================================================================================================================

/** The "tag" sidebar view: header buttons (sort, hierarchy, collapse-all, search) over a virtualised tag tree. */
function defineTagPaneView(host) {
  const paneT = () => host.t.plugins.tagPane;
  const sortLabels = () => {
    const pane = host.t.plugins.tagPane;
    return {
      alphabetical: pane.labelSortByNameAToZ,
      alphabeticalReverse: pane.labelSortByNameZToA,
      frequency: pane.labelSortByFrequencyHighToLow,
      frequencyReverse: pane.labelSortByFrequencyLowToHigh,
    };
  };

  function TagPaneView(leaf) {
    const self = host.View.call(this, leaf) || this;
    self.icon = "lucide-tags";
    self.tagDoms = {};
    self.tagPaneEl = null;
    self.searchQuery = null;
    self.sortOrder = "frequency";
    self.useHierarchy = false;
    self.isShowingSearch = false;

    const containerEl = self.containerEl;
    self.tagPaneEl = containerEl.createDiv("tag-container");
    self.scope = new host.Scope(self.app.scope);
    self.tree = new tagPane.TagPaneTree(self, {
      app: self.app,
      containerEl: self.tagPaneEl,
      id: VIEW_TYPE_TAG,
      scope: self.scope,
      getNodeId: self.getNodeId.bind(self),
    });
    self.emptyEl = createDiv({ cls: "pane-empty tag-pane-empty", text: paneT().labelNoTags() });

    const header = new host.ViewHeader(self.app, containerEl);
    header.addNavButton("lucide-sort-asc", host.t.plugins.fileExplorer.actionChangeSort(), (event) => {
      event.preventDefault();
      const menu = new host.Menu();
      const current = self.sortOrder;
      for (const group of SORT_GROUPS) {
        for (const key of group) {
          const title = sortLabels()[key]();
          menu.addItem((item) => item
            .setTitle(title)
            .setChecked(key === current)
            .onClick(() => {
              self.sortOrder = key;
              self.requestUpdateTags();
              self.app.workspace.requestSaveLayout();
            }));
        }
        menu.addSeparator();
      }
      menu.showAtMouseEvent(event);
    });
    self.useHierarchyEl = header.addNavButton("lucide-folder-tree", paneT().actionShowNestedTags(), () => {
      self.setUseHierarchy(!self.useHierarchy);
      self.app.workspace.requestSaveLayout();
    });
    self.collapseOrExpandAllEl = header.addNavButton("lucide-chevrons-up-down", paneT().actionExpandAll(), () => {
      self.tree.toggleCollapseAll();
      self.app.workspace.requestSaveLayout();
    });
    self.showSearchButtonEl = header.addNavButton("lucide-search", host.t.plugins.backlinks.labelShowSearch(), () => {
      self.onToggleShowSearch();
      self.app.workspace.requestSaveLayout();
    });

    const onSearchChange = debounceCall(() => {
      self.updateSearch();
      self.app.workspace.requestSaveLayout();
    }, 300, true);
    self.searchComponent = new host.SearchComponent(header.navHeaderEl)
      .setPlaceholder(host.t.plugins.search.promptStartSearch())
      .onChange(onSearchChange)
      .then((component) => {
        setElementTooltip(component.clearButtonEl, host.t.plugins.search.tooltipClearSearch());
        component.inputEl.addEventListener("keypress", (event) => {
          if (event.isComposing) return;
          if (event.key !== "Enter") return;
          if (!host.Platform.hasPhysicalKeyboard) host.blurAndClearSelection();
          self.updateSearch();
        });
        component.containerEl.hide();
      });

    self.scope.register([], "Enter", self.onKeyEnterInFocus.bind(self));
    self.scope.register(["Mod"], "Enter", self.onKeyEnterInFocus.bind(self));
    containerEl.addEventListener("click", () => self.tree.setFocusedItem(null));
    self.requestUpdateTags = debounceCall(self.updateTags.bind(self), 10);
    self.setUseHierarchy(true);
    return self;
  }
  inherit(TagPaneView, host.View);
  const proto = TagPaneView.prototype;

  proto.getNodeId = function (item) {
    return item.tag.toLowerCase();
  };

  proto.isItem = function (item) {
    return item instanceof tagPane.TagPaneItem;
  };

  proto.onKeyEnterInFocus = function (event) {
    event.preventDefault();
    if (this.isItem(this.tree.focusedItem)) this.tree.focusedItem.onSelfClick(event);
  };

  proto.getDisplayText = function () {
    return paneT().shortName();
  };

  proto.getViewType = function () {
    return VIEW_TYPE_TAG;
  };

  proto.getState = function () {
    const state = host.View.prototype.getState.call(this);
    state.sortOrder = this.sortOrder;
    state.useHierarchy = this.useHierarchy;
    state.showSearch = this.isShowingSearch;
    state.searchQuery = this.searchComponent.getValue();
    return state;
  };

  proto.setState = async function (state, result) {
    await host.View.prototype.setState.call(this, state, result);
    const sortOrder = state.sortOrder;
    const useHierarchy = state.useHierarchy;
    const showSearch = state.showSearch;
    const searchQuery = state.searchQuery;
    if (String.isString(sortOrder) && sortLabels().hasOwnProperty(sortOrder)) this.sortOrder = sortOrder;
    if (isBoolean(useHierarchy)) this.setUseHierarchy(useHierarchy);
    if (isBoolean(showSearch)) this.setShowSearch(showSearch);
    if (String.isString(searchQuery)) {
      this.searchComponent.setValue(searchQuery);
      this.updateSearch();
    }
    this.requestUpdateTags();
  };

  proto.onload = function () {
    this.registerEvent(this.app.metadataCache.on("finished", this.requestUpdateTags, this));
    this.requestUpdateTags();
  };

  proto.onResize = function () {
    this.tree.onResize();
  };

  /** Keeps the collapse-all button icon / tooltip in sync with the tree's collapse-all state. */
  proto.setIsAllCollapsed = function (collapsed) {
    this.tree.isAllCollapsed = collapsed;
    if (collapsed) {
      host.setIcon(this.collapseOrExpandAllEl, "lucide-chevrons-up-down");
      setElementTooltip(this.collapseOrExpandAllEl, paneT().actionExpandAll());
    } else {
      host.setIcon(this.collapseOrExpandAllEl, "lucide-chevrons-down-up");
      setElementTooltip(this.collapseOrExpandAllEl, paneT().actionCollapseAll());
    }
  };

  proto.onToggleShowSearch = function () {
    this.setShowSearch(!this.isShowingSearch);
    if (this.isShowingSearch) this.searchComponent.inputEl.focus();
  };

  proto.showSearch = function () {
    this.setShowSearch(true);
    this.searchComponent.inputEl.focus();
  };

  proto.setShowSearch = function (show) {
    if (show === this.isShowingSearch) return;
    this.isShowingSearch = show;
    this.searchComponent.containerEl.toggle(show);
    this.showSearchButtonEl.toggleClass("is-active", show);
    if (!show) {
      this.searchComponent.setValue("");
      this.updateSearch();
    }
  };

  /** Rebuilds the query object from the search box; empty or invalid input clears the filter. */
  proto.updateSearch = function () {
    const query = this.searchComponent.getValue();
    const previous = this.searchQuery;
    if ((!previous && !query) || (previous && previous.query === query)) return;
    try {
      if (query) {
        const searchQuery = new searchClasses.SearchQuery(this.app, query, false);
        this.searchQuery = searchQuery.matcher ? searchQuery : null;
      } else {
        this.searchQuery = null;
      }
      this.updateTags();
    } catch (error) {
      console.log(error);
    }
  };

  proto.setUseHierarchy = function (useHierarchy) {
    if (this.useHierarchy === useHierarchy) return;
    this.collapseOrExpandAllEl.ariaDisabled = String(!useHierarchy);
    this.useHierarchy = useHierarchy;
    this.useHierarchyEl.toggleClass("is-active", useHierarchy);
    this.requestUpdateTags();
    this.app.workspace.requestSaveLayout();
  };

  /** Rebuilds the whole tag tree from the metadata cache, reusing the previous rows where possible. */
  proto.updateTags = function () {
    const self = this;
    const app = this.app;
    const oldDoms = this.tagDoms;
    const tree = this.tree;
    const tags = app.metadataCache.getTags();
    const names = Object.keys(tags);
    const doms = (this.tagDoms = {});
    const folded = app.loadLocalStorage(FOLD_KEY);
    const foldedSet = new Set(folded || null);
    tree.root.vChildren.clear();
    tree.setFocusedItem(null, false);
    if (names.length === 0) {
      this.tagPaneEl.appendChild(this.emptyEl);
      return;
    }
    this.emptyEl.detach();

    const order = this.sortOrder;
    let compare;
    if (order === "alphabetical") {
      compare = (a, b) => compareSearchText(a.tag, b.tag);
    } else if (order === "alphabeticalReverse") {
      compare = (a, b) => -compareSearchText(a.tag, b.tag);
    } else {
      const direction = order === "frequencyReverse" ? -1 : 1;
      compare = (a, b) => {
        const countA = tags[a.tag];
        const countB = tags[b.tag];
        return countA === countB ? compareSearchText(a.tag, b.tag) : direction * (countB - countA);
      };
    }

    const hierarchy = this.useHierarchy;
    // Places `item` for `tag` under its parent chain (when hierarchy is on), creating parent rows as needed.
    const place = (tag, item) => {
      const leaf = tag.split("/").pop();
      if (hierarchy && leaf !== tag) {
        const parent = tag.substr(0, tag.length - leaf.length - 1);
        const key = parent.toLowerCase();
        let parentItem = doms[key];
        if (!parentItem) {
          parentItem = new tagPane.TagPaneItem(tree, self);
          parentItem.setTag(parent);
          doms[key] = parentItem;
        }
        if (parentItem.vChildren.children.indexOf(item) === -1) parentItem.vChildren.addChild(item);
        place(parent, parentItem);
      } else if (tree.root.vChildren.children.indexOf(item) === -1) {
        tree.root.vChildren.addChild(item);
      }
    };

    // Old rows keep their DOM but lose their children; missing rows are created fresh.
    for (const key in oldDoms) {
      if (oldDoms.hasOwnProperty(key)) oldDoms[key].vChildren.clear();
    }
    for (const name of names) {
      const key = name.toLowerCase();
      const item = oldDoms[key] || new tagPane.TagPaneItem(tree, self);
      item.setTag(name);
      doms[key] = item;
    }
    for (const name of names) {
      place(name, doms[name.toLowerCase()]);
    }
    for (const key in doms) {
      if (doms.hasOwnProperty(key)) {
        const item = doms[key];
        const hasKids = item.vChildren.hasChildren();
        item.setCollapsible(hasKids);
        item.setCount(tags[item.tag] || 0);
        if (hasKids) item.setCollapsed(foldedSet.has(key), false);
      }
    }
    tree.root.vChildren.sort(compare);

    const filtering = !!(self.searchComponent && self.searchComponent.getValue());
    ng15WalkTree(tree.root, (item) => {
      if (ng15HasChildList(item)) item.vChildren.sort(compare);
      if (filtering) {
        if (self.searchQuery.matchContent(item.tag)) {
          // keep the row and every ancestor visible
          for (let node = item; node; node = node.parent) node.el.show();
        } else {
          item.el.hide();
        }
      } else {
        item.el.show();
      }
    }, false);
    tree.infinityScroll.invalidateAll();
  };

  tagPane.TagPaneView = TagPaneView;
  return TagPaneView;
}

// ---- n-g24-themes.js ----
// s04: own implementations of the CSS theme/snippet manager and its small
// helpers (deferred, cached calls, promise sets, community theme list).
//
// Replaces the inherited `customCss` manager: it watches the vault for
// theme/snippet changes, keeps theme.css + snippet <style> elements in
// document.head in sync, and installs/updates themes from GitHub.
//
// Inherited pieces are reached through the factory's host table (Component,
// debounce, SerialTaskQueue, Notice, i18n) or env() (Platform helpers,
// translucency IPC, electronWindow). HTTP goes through the own s04-http
// helpers; path/string helpers are the own flat-scope functions.

const S04_THEME_FILE = "theme.css";
const S04_MANIFEST_FILE = "manifest.json";
const S04_THEMES_URL = "obsidianmd/obsidian-releases/community-css-themes.json";

// ---------------------------------------------------------------- small async helpers (was `gb`, `yb`, `Eb`, `Mb`)

/** A promise with exposed resolve/reject (was `gb`). */
function s04CreateDeferred() {
  const deferred = { promise: null, resolve: null, reject: null };
  deferred.promise = new Promise((resolve, reject) => {
    deferred.resolve = resolve;
    deferred.reject = reject;
  });
  return deferred;
}

/**
 * Wraps `fetcher` in a TTL cache with in-flight dedupe (was `yb`).
 * `cacheMs` is how long a successful result stays fresh; `dedupeMs` (default
 * `cacheMs`) is the window after a failure during which the previous result
 * is still served instead of refetching.
 */
function s04CachedCall(fetcher, cacheMs, dedupeMs) {
  if (dedupeMs === undefined) dedupeMs = cacheMs;
  let pending = null;
  let freshUntil = 0;
  let result = null;
  return function () {
    if (pending) return pending;
    if (result && freshUntil > Date.now()) return Promise.resolve(result);
    pending = (async () => {
      freshUntil = Date.now() + dedupeMs;
      try {
        result = await fetcher();
      } catch (err) {
        pending = null;
        return null;
      }
      freshUntil = Date.now() + cacheMs;
      pending = null;
      setTimeout(() => {
        if (freshUntil > Date.now()) result = null;
      }, cacheMs);
      return result;
    })();
    return pending;
  };
}

/** Collects promises; `promise()` awaits all added so far (was `Eb`). */
function s04PromiseSetClass() {
  class PromiseSet {
    constructor() {
      this.promises = [];
    }
    add(task) {
      this.promises.push(task());
    }
    addPromise(promise) {
      this.promises.push(promise);
    }
    isEmpty() {
      return this.promises.length === 0;
    }
    promise() {
      return Promise.all(this.promises);
    }
  }
  return PromiseSet;
}

/** Resolves (never rejects) once `promise` settles, with its value or undefined (was `Mb`). */
function s04SettlePromise(promise) {
  return new Promise((resolve) => promise.then(resolve, resolve));
}

// ---------------------------------------------------------------- community theme list (was `Ab`, `Pb`, `Lb`)

const S04_COMMUNITY_THEMES_REPO = "obsidianmd/obsidian-releases";

/** Raw URL of the community theme catalog (was `Ab`). */
// Literal: s04RawFileUrl's base const lives in s04-http.js, concatenated after this file.
const s04CommunityThemesUrl = "https://raw.githubusercontent.com/obsidianmd/obsidian-releases/HEAD/community-css-themes.json";

/** Cached loader for the community theme catalog (was `Pb`). */
const s04CommunityThemes = s04CachedCall(async () => {
  const list = await s04Request(s04RawFileUrl(S04_COMMUNITY_THEMES_REPO, "community-css-themes.json")).json;
  if (!Array.isArray(list)) throw new Error("Failed to parse community themes.");
  return list;
}, 3e5, 6e4);

/** Cached empty catalog used where fetching is unavailable (was `Lb`). */
const s04CommunityThemesEmpty = s04CachedCall(() => Promise.resolve({}), 3e5, 6e4);

// ---------------------------------------------------------------- string helpers (was `cb`, `hb`, `pb`)

const S04_COLLATOR = new Intl.Collator(undefined, { usage: "sort", sensitivity: "base", numeric: true });

/** Locale-aware string compare used for file lists (was `cb`). */
const s04StringCompare = S04_COLLATOR.compare;

/** Descending variant (was `hb`). */
function s04StringCompareDesc(a, b) {
  return -S04_COLLATOR.compare(a, b);
}

/** Numeric compare (was `pb`). */
function s04NumberCompare(a, b) {
  return a - b;
}

// ---------------------------------------------------------------- the manager (was `Ib`)

/**
 * The `app.customCss` manager: keeps the active theme and enabled snippets
 * rendered into <style> elements and handles theme install/update flows.
 */
function s04CssManager(host) {
  function CssManager(app) {
    const self = host.Component.call(this) || this;
    self.app = null;
    self.styleEl = null;
    self.extraStyleEls = [];
    self.boundRaw = self.onRaw.bind(self);
    self.oldThemes = [];
    self.themes = {};
    self.updates = {};
    self.snippets = [];
    self.enabledSnippets = new Set();
    self.csscache = new Map();
    self.theme = "";
    self.requestLoadTheme = host.debounce(self.loadTheme.bind(self), 100);
    self.requestLoadSnippets = host.debounce(self.loadSnippets.bind(self), 100);
    self.requestReadThemes = host.debounce(self.readThemes.bind(self), 2000);
    self.queue = new host.SerialTaskQueue();
    self.app = app;
    return self;
  }
  Object.setPrototypeOf(CssManager, host.Component);
  CssManager.prototype = Object.create(host.Component.prototype, {
    constructor: { value: CssManager, writable: true, configurable: true },
  });

  CssManager.prototype.onload = async function () {
    host.Component.prototype.onload.call(this);
    const app = this.app;
    this.loadData();
    await this.readThemes();
    await this.readSnippets();
    this.styleEl = document.head.createEl("style", { type: "text/css" });
    this.registerEvent(app.vault.on("raw", this.boundRaw));
    await this.loadTheme();
    await this.loadSnippets();
  };

  CssManager.prototype.loadData = function () {
    const vault = this.app.vault;
    const snippets = vault.getConfig("enabledCssSnippets");
    if (snippets) this.enabledSnippets = new Set(snippets);
    const theme = vault.getConfig("cssTheme");
    if (theme) this.theme = theme;
    if (vault.getConfig("translucency")) this.enableTranslucency();
  };

  CssManager.prototype.reloadTheme = function () {
    this.theme = this.app.vault.getConfig("cssTheme") || "";
    this.requestLoadTheme();
  };

  CssManager.prototype.readThemes = function (reload) {
    const self = this;
    return this.queue.queue(async function () {
      const app = self.app;
      const adapter = self.app.vault.adapter;
      const legacy = [];
      const themes = {};
      const folder = self.getThemeFolder();
      if (await app.vault.exists(folder)) {
        const listing = await adapter.list(folder);
        for (const dir of listing.folders) {
          const name = lastSegment(dir);
          const manifestPath = normalizePath(dir + "/" + S04_MANIFEST_FILE);
          const cssPath = normalizePath(dir + "/" + S04_THEME_FILE);
          try {
            if (!(await adapter.exists(cssPath))) continue;
            const raw = await adapter.read(manifestPath);
            const manifest = JSON.parse(raw);
            if (manifest.name && manifest.name === name) themes[name] = manifest;
          } catch (err) {
            console.error(err);
          }
        }
        for (const file of listing.files) {
          const name = lastSegment(file);
          if (name.startsWith(".") || extensionOf(name) !== "css") continue;
          legacy.push(baseName(name));
        }
      }
      self.oldThemes = legacy;
      self.themes = themes;
      if (reload) self.requestLoadTheme();
    });
  };

  CssManager.prototype.readSnippets = function (reload) {
    const self = this;
    return this.queue.queue(async function () {
      const vault = self.app.vault;
      const adapter = vault.adapter;
      const names = [];
      const folder = self.getSnippetsFolder();
      if (await adapter.exists(folder)) {
        const listing = await adapter.list(folder);
        for (const file of listing.files) {
          const name = lastSegment(file);
          if (name.startsWith(".") || extensionOf(name) !== "css") continue;
          names.push(baseName(name));
        }
      }
      names.sort(s04StringCompare);
      self.snippets = names;
      if (reload) self.requestLoadSnippets();
    });
  };

  CssManager.prototype.onRaw = function (path) {
    if (this.csscache.has(path)) this.csscache.delete(path);
    const name = lastSegment(path);
    const ext = extensionOf(name);
    if (path === this.getThemePath(this.theme)) this.requestLoadTheme();
    if (
      path.startsWith(this.getThemeFolder()) &&
      (name === S04_MANIFEST_FILE || name === S04_THEME_FILE || ext === "css")
    ) {
      this.requestReadThemes();
    }
    if (path.startsWith(this.getSnippetsFolder()) && ext === "css") this.readSnippets(true);
  };

  CssManager.prototype.loadTheme = function (css) {
    const self = this;
    return this.queue.queue(async function () {
      const styleEl = self.styleEl;
      const theme = self.theme;
      let text = "";
      if (css) {
        text = css;
      } else if (theme) {
        text = await self.loadCss(self.getThemePath(theme));
      }
      if (styleEl.textContent !== text) {
        styleEl.textContent = text;
        self.app.workspace.trigger("css-change");
        self.app.workspace.trigger("resize");
      }
    });
  };

  CssManager.prototype.loadSnippets = function () {
    const self = this;
    return this.queue.queue(async function () {
      const styleEl = self.styleEl;
      const extraStyleEls = self.extraStyleEls;
      const enabled = self.enabledSnippets;
      const texts = [];
      for (const name of self.snippets) {
        if (!enabled.has(name)) continue;
        texts.push(await self.loadCss(self.getSnippetPath(name)));
      }
      let changed = false;
      for (let i = 0; i < texts.length; i++) {
        let el = extraStyleEls[i];
        if (!el) {
          el = host.createEl("style", { type: "text/css" });
          extraStyleEls.push(el);
          styleEl.parentNode.insertAfter(el, styleEl);
          changed = true;
        }
        if (el.textContent !== texts[i]) {
          el.textContent = texts[i];
          changed = true;
        }
        styleEl = el;
      }
      const extra = extraStyleEls.length - texts.length;
      for (let i = 0; i < extra; i++) {
        extraStyleEls.pop().detach();
        changed = true;
      }
      if (changed) {
        self.app.workspace.trigger("css-change");
        self.app.workspace.trigger("resize");
      }
    });
  };

  CssManager.prototype.loadCss = async function (path) {
    if (this.csscache.has(path)) return this.csscache.get(path);
    const adapter = this.app.vault.adapter;
    if (await adapter.exists(path)) {
      const css = await adapter.read(path);
      this.csscache.set(path, css);
      return css;
    }
    return "";
  };

  CssManager.prototype.setCssEnabledStatus = function (name, enabled) {
    if (enabled) this.enabledSnippets.add(name);
    else this.enabledSnippets.delete(name);
    this.app.vault.setConfig("enabledCssSnippets", Array.from(this.enabledSnippets));
    this.requestLoadSnippets();
  };

  CssManager.prototype.setTheme = function (name) {
    this.theme = name;
    this.app.vault.setConfig("cssTheme", name);
    this.requestLoadTheme();
  };

  CssManager.prototype.setTranslucency = function (enabled) {
    this.app.vault.setConfig("translucency", enabled);
    if (enabled) this.enableTranslucency();
    else this.disableTranslucency();
  };

  CssManager.prototype.enableTranslucency = function () {
    const { Yl, Uf, Wf, electronWindow } = env();
    if (!(Yl.isDesktopApp && Uf())) return;
    try {
      Wf(electronWindow, true);
      document.body.addClass("is-translucent");
    } catch (err) {
      new host.Notice(host.t.interface.msgUpgradeInstaller());
    }
  };

  CssManager.prototype.disableTranslucency = function () {
    const { Yl, Uf, Wf, electronWindow } = env();
    if (!(Yl.isDesktopApp && Uf())) return;
    document.body.removeClass("is-translucent");
    try {
      Wf(electronWindow, false);
    } catch (err) {}
  };

  CssManager.prototype.isDarkMode = function () {
    return document.body.hasClass("theme-dark");
  };

  CssManager.prototype.getThemeFolder = function () {
    return this.app.vault.configDir + "/themes";
  };

  CssManager.prototype.getSnippetsFolder = function () {
    return this.app.vault.configDir + "/snippets";
  };

  CssManager.prototype.getThemePath = function (name) {
    if (!this.themes.hasOwnProperty(name) && this.oldThemes.includes(name)) {
      return this.getThemeFolder() + "/" + name + ".css";
    }
    return this.getThemeFolder() + "/" + name + "/" + S04_THEME_FILE;
  };

  CssManager.prototype.getSnippetPath = function (name) {
    return this.getSnippetsFolder() + "/" + name + ".css";
  };

  CssManager.prototype.removeTheme = async function (name) {
    const adapter = this.app.vault.adapter;
    const folder = this.getThemeFolder();
    const dir = folder + "/" + name;
    if (await adapter.exists(dir)) await adapter.rmdir(dir, true);
    const legacyPath = folder + "/" + name + ".css";
    const isLegacy = this.oldThemes.includes(name) && (await adapter.exists(legacyPath));
    if (isLegacy) await adapter.remove(legacyPath);
    await this.readThemes();
    if (this.theme === name) this.setTheme("");
  };

  CssManager.prototype.downloadLegacyTheme = function (info) {
    return s04Request(s04RawFileUrl(info.repo, "obsidian.css")).text;
  };

  CssManager.prototype.isThemeInstalled = function (name) {
    return this.themes.hasOwnProperty(name) || this.oldThemes.includes(name);
  };

  CssManager.prototype.hasUpdates = function () {
    return this.updates && Object.keys(this.updates).length > 0;
  };

  CssManager.prototype.checkForUpdate = async function (info) {
    const folder = this.getThemeFolder();
    const updates = this.updates || {};
    const name = info.name;
    const repo = info.repo;
    if (!this.isThemeInstalled(name)) return;
    let installedVersion = this.themes[name] ? this.themes[name].version : undefined;
    const manifestPath = s04RawFileUrl(repo, S04_MANIFEST_FILE);
    let manifest = null;
    try {
      manifest = await s04Request(manifestPath).json;
    } catch (err) {}
    if (!manifest) {
      const css = await this.downloadLegacyTheme(info);
      const hasDir = !!(this.themes[info.name] && this.themes[info.name].dir);
      const cssPath = hasDir ? folder + "/" + name + "/" + S04_THEME_FILE : folder + "/" + name + ".css";
      let current = "";
      try {
        current = await this.app.vault.adapter.read(cssPath);
      } catch (err) {
        return false;
      }
      if (css !== current) {
        updates[name] = { themeInfo: info };
        return true;
      }
      return false;
    }
    const latest = await s04ThemeVersion(repo, manifest);
    if (!installedVersion || (latest && isOlderVersion(installedVersion, latest))) {
      updates[name] = { themeInfo: info, version: latest };
      return true;
    }
    return false;
  };

  CssManager.prototype.checkForUpdates = async function () {
    this.updates = {};
    let themes;
    try {
      themes = await s04CommunityThemes();
    } catch (err) {
      console.error(err);
      new host.Notice(host.t.plugins.customCss.msgFailedToInstallTheme());
      return;
    }
    for (let i = 0; i < themes.length; i++) {
      await this.checkForUpdate(themes[i]);
    }
    const count = Object.keys(this.updates).length;
    new host.Notice(
      count === 0
        ? host.t.plugins.customCss.msgNoUpdatesFound()
        : host.t.plugins.customCss.msgUpdatesFound({ count })
    );
  };

  CssManager.prototype.installLegacyTheme = async function (info) {
    const vault = this.app.vault;
    const name = info.name;
    const css = await this.downloadLegacyTheme(info);
    const folder = this.getThemeFolder();
    if (!(await vault.exists(folder))) await vault.createFolder(folder);
    const dir = folder + "/" + name;
    if (!(await vault.exists(dir))) await vault.createFolder(dir);
    const manifest = { name: info.name, version: "0.0.0", minAppVersion: "0.16.0", author: info.author };
    await vault.adapter.write(dir + "/" + S04_THEME_FILE, css);
    await vault.adapter.write(dir + "/" + S04_MANIFEST_FILE, JSON.stringify(manifest, null, 4));
    const legacyPath = folder + "/" + name + ".css";
    if (await vault.adapter.exists(legacyPath)) await vault.adapter.remove(legacyPath);
    await this.readThemes();
  };

  CssManager.prototype.installTheme = async function (info, version) {
    const name = info.name;
    const repo = info.repo;
    const notice = new host.Notice(host.t.plugins.customCss.msgInstallingTheme({ name }), 0);
    notice.containerEl.addClass("is-loading");
    try {
      let installed = localStorage.getItem("local-themes");
      let list = installed ? JSON.parse(installed) : [];
      if (!Array.isArray(list)) list = [];
      if (!list.contains(name)) {
        list.push(name);
        localStorage.setItem("local-themes", JSON.stringify(list));
      }
    } catch (err) {
      console.error(err);
    }
    if (!version) {
      await this.installLegacyTheme(info);
      delete this.updates[name];
      notice.hide();
      return;
    }
    let manifestText;
    let cssText;
    try {
      manifestText = await s04Request(s04ReleaseUrl(repo, version, S04_MANIFEST_FILE)).text;
      cssText = await s04Request(s04ReleaseUrl(repo, version, S04_THEME_FILE)).text;
    } catch (err) {
      if (manifestText === undefined && err instanceof S04RequestError && err.status === 404) {
        try {
          manifestText = await s04Request(s04RawFileUrl(repo, S04_MANIFEST_FILE)).text;
          cssText = await s04Request(s04RawFileUrl(repo, S04_THEME_FILE)).text;
        } catch (fallbackErr) {
          console.error(fallbackErr);
          notice.containerEl.removeClass("is-loading");
          notice.containerEl.addClass("mod-error");
          notice.setMessage(host.t.plugins.customCss.msgFailedToInstallTheme({ name }));
          setTimeout(() => notice.hide(), 3000);
          return;
        }
      } else {
        console.error(err);
        notice.containerEl.removeClass("is-loading");
        notice.containerEl.addClass("mod-error");
        notice.setMessage(host.t.plugins.customCss.msgFailedToInstallTheme({ name }));
        setTimeout(() => notice.hide(), 3000);
        return;
      }
    }
    if (JSON.parse(manifestText).name !== name) {
      notice.containerEl.removeClass("is-loading");
      notice.setMessage(host.t.plugins.customCss.msgFailedToInstallTheme({ name }) + " Theme name mismatch.");
      setTimeout(() => notice.hide(), 3000);
      return;
    }
    const adapter = this.app.vault.adapter;
    const folder = this.getThemeFolder();
    if (!(await adapter.exists(folder))) await adapter.mkdir(folder);
    const dir = folder + "/" + name;
    if (!(await adapter.exists(dir))) await adapter.mkdir(dir);
    await adapter.write(dir + "/" + S04_MANIFEST_FILE, manifestText);
    await adapter.write(dir + "/" + S04_THEME_FILE, cssText);
    const legacyPath = folder + "/" + name + ".css";
    if (await adapter.exists(legacyPath)) await adapter.remove(legacyPath);
    notice.setMessage(host.t.plugins.customCss.msgSuccessfullyInstalledTheme({ name }));
    notice.containerEl.removeClass("is-loading");
    notice.containerEl.addClass("mod-success");
    setTimeout(() => notice.hide(), 3000);
    delete this.updates[name];
    await this.readThemes();
  };

  CssManager.prototype.getManifest = async function (repo) {
    let manifest = null;
    try {
      manifest = await s04Request(s04RawFileUrl(repo, S04_MANIFEST_FILE)).json;
    } catch (err) {}
    return manifest;
  };

  return CssManager;
}

// g24 manifest declarator aliases.
const ng24CommunityThemesUrl = s04CommunityThemesUrl;
const ng24CommunityThemesEmpty = s04CommunityThemesEmpty;

// ---- n-g27-edit-mode-base.js ----
// g27 edit-mode-base: EditModeBase (orig aZ) — base of the source edit modes.
// Owns the scrollDOM rearrangement (.cm-sizer > .cm-contentContainer >
// gutters + content), the fractional-line scroll protocol, the in-editor
// search bar scope bridging, mode keymaps and the dynamic extension set.

function defineEditModeBase(host) {

  function EditModeBase(app, contentEl, owner) {
    const self = host.CodeMirrorEditor.call(this, app, contentEl, owner) || this;
    self.isScrolling = false;
    self.cssClasses = [];
    const cm = self.cm;
    const scrollDOM = cm.scrollDOM;
    const contentDOM = cm.contentDOM;
    contentDOM.detach();
    const sizerEl = self.sizerEl = scrollDOM.createDiv("cm-sizer");
    const containerEl = sizerEl.createDiv("cm-contentContainer");
    const gutters = scrollDOM.querySelector(".cm-gutters");
    if (gutters) containerEl.appendChild(gutters);
    containerEl.appendChild(contentDOM);
    scrollDOM.addEventListener("scroll", () => self.onScroll());
    self.scope = null;
    self.search = new host.EditorSearchBar(self.editor, self.editorEl, (scope) => {
      if (self.scope) app.keymap.popScope(self.scope);
      self.scope = scope || null;
      if (self.scope) app.keymap.pushScope(self.scope);
    });
    self.editorEl.addEventListener("click", (event) => self.onViewClick(event));
    return self;
  }
  inherit(EditModeBase, host.CodeMirrorEditor);

  methods(EditModeBase, {

    onScroll() {
      this.editorSuggest.reposition();
      if (this.isScrolling) {
        this.isScrolling = false;
        return;
      }
      this.handleScroll();
    },

    handleScroll() {
      this.owner.syncScroll();
    },

    show() {
      this.editorEl.show();
    },

    hide() {
      this.editorEl.hide();
      this.editorSuggest.close();
      this.search.hide();
    },

    focus() {
      const info = this.editor.getScrollInfo();
      this.editor.focus();
      this.editor.scrollTo(info.left, info.top);
      if (host.Platform.isMobileApp && host.keyboard) host.keyboard.show();
    },

    // ------------------------------------------- fractional-line scroll math

    getScroll() {
      const cm = this.cm;
      const doc = cm.state.doc;
      const contentTop = cm.contentDOM.offsetTop;
      const scrollTop = cm.scrollDOM.scrollTop;
      const block = cm.lineBlockAtHeight(Math.max(scrollTop - contentTop, 0));
      const start1 = doc.lineAt(block.from).number;
      const end1 = doc.lineAt(Math.max(block.from, block.to - 1)).number;
      const startLine = start1 - 1;
      const lineSpan = Math.max(1, end1 - start1 + 1);
      let offset = scrollTop - block.top;
      let height = block.height;
      if (startLine === 0) height += contentTop;
      else offset -= contentTop;
      return startLine + (lineSpan * Math.max(offset, 0)) / Math.max(1, height);
    },

    applyScroll(scroll) {
      if (typeof scroll !== "number" || isNaN(scroll)) return;
      const cm = this.cm;
      const doc = cm.state.doc;
      const clamped = scroll < 0 ? 0 : scroll >= doc.lines ? doc.lines - 0.99 : scroll;
      const line = Math.floor(clamped);
      const fraction = clamped - line;
      const docLine = doc.line(line + 1);
      const computeTop = () => {
        const block = cm.lineBlockAt(docLine.from);
        const start1 = doc.lineAt(block.from).number;
        const end1 = doc.lineAt(Math.max(block.from, block.to - 1)).number;
        const lineSpan = Math.max(1, end1 - start1 + 1);
        const inner = (line + 1) - start1;
        const contentTop = cm.contentDOM.offsetTop;
        let top = block.top;
        let height = block.height;
        if (start1 === 1) height += contentTop;
        else top += contentTop;
        return top + ((inner + fraction) * height) / lineSpan;
      };
      const inView = (cm.visibleRanges || []).some(
        (range) => docLine.from >= range.from && docLine.from <= range.to
      );
      this.isScrolling = true;
      if (inView) {
        cm.scrollDOM.scrollTop = computeTop();
        return;
      }
      cm.dispatch({
        effects: [host.CMEditorView.scrollIntoView(docLine.from, { y: "nearest" })],
      });
      cm.requestMeasure({
        read: () => null,
        write: () => {
          const top = computeTop();
          cm.requestMeasure({
            read: () => top,
            write: (value) => { cm.scrollDOM.scrollTop = value; },
          });
        },
      });
    },
  });

  methods(EditModeBase, {

    showSearch(reveal) {
      if (reveal === undefined) reveal = false;
      this.destroyTableCell();
      this.search.show(reveal);
    },

    // -------------------------------------------------------- extensions

    buildLocalExtensions() {
      const extensions = host.CodeMirrorEditor.prototype.buildLocalExtensions.call(this);
      const self = this;
      extensions.push(host.hypermdMode);
      extensions.push(host.cmLiveDecorations);
      extensions.push(host.cmView.scrollHandler.of((update, range) => {
        const cell = self.tableCell;
        return !!(
          cell &&
          cell.containerEl.isShown() &&
          cell.table &&
          cell.table.containsRange(range.anchor, range.head)
        );
      }));
      extensions.push(host.cmKeymapFacet.of([
        {
          key: "Enter",
          preventDefault: true,
          run() {
            if (!self.app.vault.getConfig("smartIndentList")) return false;
            const state = self.cm.state;
            const pos = state.selection.main.from;
            if (host.isSmartIndentTarget(state, state.doc.lineAt(pos))) {
              self.editor.newlineAndIndentOnly();
            } else {
              self.editor.newlineAndIndentContinueMarkdownList();
            }
            return true;
          },
          shift() {
            if (!self.app.vault.getConfig("smartIndentList")) return false;
            self.editor.newlineAndIndentOnly();
            return true;
          },
        },
        {
          key: "Tab",
          run() {
            self.editor.indentList();
            return true;
          },
          shift() {
            self.editor.unindentList();
            return true;
          },
        },
      ]));
      return extensions;
    },

    getDynamicExtensions() {
      const extensions = host.CodeMirrorEditor.prototype.getDynamicExtensions.call(this);
      const vault = this.app.vault;
      const editorEl = this.editorEl;
      if (vault.getConfig("showLineNumber")) {
        extensions.push(host.cmLineNumbersFixed({ fixed: false }));
        extensions.push(host.cmLineNumbersCompute);
        extensions.push(host.cmLineNumbersField());
      }
      if (vault.getConfig("smartIndentList")) extensions.push(host.cmTableCellFilter(this));
      if (vault.getConfig("showIndentGuide")) extensions.push(host.cmIndentGuides);
      const foldHeading = vault.getConfig("foldHeading");
      const foldIndent = vault.getConfig("foldIndent");
      const folding = foldHeading || foldIndent;
      editorEl.toggleClass("is-folding", folding);
      if (folding) {
        extensions.push(host.cmFoldGutter());
        extensions.push(host.cmFoldDecorations);
        if (foldHeading) extensions.push(host.cmFoldHeading);
        if (foldIndent) extensions.push(host.cmFoldIndent);
        extensions.push(host.cmFoldFrontmatter);
      }
      if (vault.getConfig("autoPairBrackets") || vault.getConfig("autoPairMarkdown")) {
        extensions.push([host.cmAutoPair]);
      }
      editorEl.toggleClass("show-properties", vault.getConfig("propertiesInDocument") === "visible");
      return extensions;
    },

    setCssClass(classes) {
      const editorEl = this.editorEl;
      editorEl.removeClasses(this.cssClasses);
      let rest = [];
      if (classes && classes.length) {
        rest = classes.filter((cls) => !editorEl.hasClass(cls));
        if (rest.length) editorEl.addClasses(rest);
      }
      this.cssClasses = rest;
    },

    onCssChange() {
      this.cm.dispatch({ effects: [host.cmClearCacheEffect.of()] });
      this.editor.refresh();
    },

    onViewClick(event) {
      if (event.defaultPrevented) return;
      this.editorSuggest.close();
      setTimeout(() => this.editor.removeHighlights(), 0);
    },

    onUpdate(update, isUserEvent) {
      host.CodeMirrorEditor.prototype.onUpdate.call(this, update, isUserEvent);
      const workspace = this.app.workspace;
      if (update.docChanged) workspace.trigger("editor-change", this.editor, this.owner);
      if (update.selectionSet || isUserEvent || update.focusChanged) {
        workspace.trigger("editor-selection-change", this.editor, this.owner);
      }
    },

    onConfigChanged(configKey) {
      host.CodeMirrorEditor.prototype.onConfigChanged.call(this, configKey);
      if (
        configKey === "showLineNumber" || configKey === "showIndentGuide" ||
        configKey === "foldHeading" || configKey === "foldIndent" ||
        configKey === "propertiesInDocument"
      ) {
        this.updateOptions();
      }
    },
  });

  return EditModeBase;
}

// ---- n-g27-edit-mode.js ----
// g27 edit-mode: MarkdownEditMode (orig j6) — the "source" edit mode of a
// MarkdownView. Extends EditModeBase; reparents title/properties/backlinks into
// the editor sizer, keeps ephemeral cursor/scroll/highlight state, computes
// fold info including the properties block, adds the live-preview properties
// extension, sizes bottom padding and debounces save/fold/internal changes.

function defineMarkdownEditMode(host) {

  // char offset inside a text block -> {line (0-based), ch}
  function ng27TextPos(content, offset) {
    offset = Math.max(0, Math.min(offset, content.length));
    let line = 0;
    let lineStart = 0;
    for (let i = 0; i < offset; i++) {
      if (content.charCodeAt(i) === 10) {
        line++;
        lineStart = i + 1;
      }
    }
    return { line, ch: offset - lineStart };
  }

  function ng27CssPx(el, name, doc) {
    const view = doc || (el && el.ownerDocument) || document;
    const raw = view.defaultView.getComputedStyle(view.documentElement).getPropertyValue(name);
    const value = parseFloat(raw);
    return isNaN(value) ? 0 : value;
  }

  function MarkdownEditMode(view) {
    const self = host.EditModeBase.call(this, view.app, view.contentEl, view) || this;
    self.type = "source";
    self.view = view;
    self.app = view.app;
    self.requestOnInternalDataChange = host.debounce(() => view.onInternalDataChange(), 10);
    self.requestSaveFolds = host.debounce(() => view.onMarkdownFold(), 500);
    self.propertiesExtension = null;
    self.search.applyScope = (scope) => { view.scope = scope; };
    view.addChild(self);
    self.updateReadableLineLength();
    self.updateOptions();
    self.cm.scrollDOM.addEventListener("contextmenu", (event) => self.onViewportMenu(event));
    return self;
  }
  inherit(MarkdownEditMode, host.EditModeBase);

  methods(MarkdownEditMode, {

    show() {
      host.EditModeBase.prototype.show.call(this);
      const sizer = this.sizerEl;
      sizer.prepend(this.view.metadataEditor.containerEl);
      sizer.prepend(this.view.inlineTitleEl);
      sizer.appendChild(this.view.backlinksEl);
    },

    set() {
      return host.EditModeBase.prototype.set.apply(this, arguments);
    },

    clear() {
      host.EditModeBase.prototype.clear.call(this);
      this.propertiesExtension = null;
    },

    destroy() {
      host.EditModeBase.prototype.destroy.call(this);
      this.propertiesExtension = null;
    },

    getSelection() {
      return this.editor.getSelection();
    },

    beforeUnload() {
      this.requestOnInternalDataChange.cancel();
      this.requestSaveFolds.run();
      this.saveHistory();
    },

    // ------------------------------------------------ ephemeral state

    getEphemeralState(state) {
      const sel = this.cm.state.selection.main;
      state.cursor = {
        from: this.editor.offsetToPos(sel.anchor),
        to: this.editor.offsetToPos(sel.head),
      };
      return state;
    },

    setEphemeralState(state) {
      this.setState(state);
      this.setHighlight(state);
    },

    setState(state) {
      state = state || {};
      let focus = false;
      const cursor = state.cursor;
      if (cursor && cursor.from) {
        const info = this.editor.getScrollInfo();
        this.editor.setSelection(cursor.from, cursor.to);
        this.editor.scrollTo(info.left, info.top);
        if (host.Platform.isDesktop) focus = true;
      } else {
        focus = !!state.focus && (!host.Platform.isMobile || !!state.focusOnMobile);
      }
      if (state.focusMetadata) {
        const metadata = this.view.metadataEditor;
        if (this.view.canShowProperties() && metadata && metadata.properties && metadata.properties.length > 0) {
          metadata.focus();
          focus = false;
        } else {
          focus = true;
        }
      }
      if (Object.prototype.hasOwnProperty.call(state, "scroll")) this.applyScroll(state.scroll);
      if (focus) this.focus();
    },

    // ------------------------------------------------------- highlights

    setHighlight(state) {
      if (!state) return;
      const doc = this.cm.state.doc;
      if (state.startLoc != null && state.endLoc !== undefined) {
        const start = { line: state.startLoc.line, ch: state.startLoc.col };
        const end = state.endLoc
          ? { line: state.endLoc.line, ch: state.endLoc.col }
          : { line: doc.lines - 1, ch: doc.line(doc.lines).length };
        this.editor.addHighlights([{ from: start, to: end }], "is-flashing", true, true);
        this.isScrolling = true;
        this.onScroll();
        return;
      }
      if (state.line !== undefined && state.line >= 0) {
        const line = doc.line(Math.min(state.line + 1, doc.lines));
        const from = { line: state.line, ch: 0 };
        const to = { line: state.line, ch: line.text.length };
        this.editor.setSelection(to);
        this.editor.addHighlights([{ from, to }], "is-flashing", true, true);
        this.isScrolling = true;
        this.onScroll();
        return;
      }
      const propertyMatches = state.propertyMatches;
      if (propertyMatches !== undefined) {
        if (!propertyMatches || propertyMatches.length === 0) return;
        if (this.app.vault.getConfig("propertiesInDocument") === "hidden" || this.view.canShowProperties()) {
          host.propertiesPlugin(this.app).then((plugin) => {
            host.focusWhenShown(plugin.containerEl, () => plugin.focusProperty(propertyMatches[0].key));
          });
        } else {
          this.editor.setSelection({ line: 0, ch: 0 });
          this.isScrolling = true;
          this.onScroll();
        }
        return;
      }
      const match = state.match;
      if (match && match.content && match.matches) {
        const ranges = [];
        for (const pair of match.matches) {
          ranges.push({ from: ng27TextPos(match.content, pair[0]), to: ng27TextPos(match.content, pair[1]) });
        }
        if (ranges.length) {
          this.editor.addHighlights(ranges, "is-flashing", true, true);
          this.isScrolling = true;
          this.onScroll();
        }
      }
    },

    highlightSearchMatches(ranges, scroll, moveCursor, flash) {
      if (scroll === undefined) scroll = true;
      if (moveCursor === undefined) moveCursor = true;
      if (flash === undefined) flash = true;
      if (!ranges || ranges.length === 0) {
        this.editor.removeHighlights("is-flashing");
        return;
      }
      this.editor.addHighlights(ranges, "is-flashing", flash, true);
      const first = ranges[0];
      if (moveCursor) this.editor.setSelection(first.from);
      if (scroll) this.editor.scrollIntoView({ from: first.to, to: first.from }, true);
    },
  });

  methods(MarkdownEditMode, {

    // ------------------------------------------------------------- folds

    getFoldInfo() {
      const info = host.EditModeBase.prototype.getFoldInfo.call(this);
      const view = this.view;
      const metadata = view.metadataEditor;
      if (view.canShowProperties() && metadata && metadata.properties && metadata.properties.length > 0) {
        info.folds = (info.folds || []).filter((fold) => fold.from !== 0);
        if (metadata.collapsed) info.folds.unshift({ from: 0, to: 0 });
      }
      return info;
    },

    getDynamicExtensions() {
      const extensions = host.EditModeBase.prototype.getDynamicExtensions.call(this);
      if (!this.sourceMode) {
        if (!this.propertiesExtension) {
          this.propertiesExtension = host.propertiesExtensionFactory(this, this.view);
        }
        extensions.push(this.propertiesExtension);
      }
      return extensions;
    },

    onUpdate(update, isUserEvent) {
      host.EditModeBase.prototype.onUpdate.call(this, update, isUserEvent);
      if (isUserEvent) {
        this.view.requestSave();
        this.requestSaveFolds();
        this.requestOnInternalDataChange();
      }
      const transactions = update.transactions || [];
      let foldChanged = false;
      for (const tr of transactions) {
        if (tr.effects && tr.effects.some((e) => e.is(host.cmFoldEffect) || e.is(host.cmUnfoldEffect))) {
          foldChanged = true;
          break;
        }
      }
      if (foldChanged) this.requestSaveFolds();
    },

    onResize() {
      host.EditModeBase.prototype.onResize.call(this);
      if (this.containerEl.offsetParent) this.updateBottomPadding(this.containerEl.clientHeight);
    },

    updateBottomPadding(height) {
      const view = this.view;
      const contentDOM = this.cm.contentDOM;
      const doc = contentDOM.ownerDocument;
      let padding;
      if (host.Platform.isMobile) {
        let extra = ng27CssPx(doc.documentElement, "--keyboard-height", doc);
        if (this.app.mobileToolbar && this.app.mobileToolbar.isVisible) {
          extra += ng27CssPx(doc.body, "--mobile-toolbar-height", doc);
        }
        padding = Math.round((height + extra) / 2) + "px";
      } else {
        padding = Math.round(height / 2) + "px";
      }
      if (view.backlinksEl && view.backlinksEl.isShown()) {
        padding = "100px";
        view.backlinksEl.style.minHeight = Math.max(0, height / 2 - 100) + "px";
      }
      contentDOM.style.paddingBottom = padding;
    },

    updateReadableLineLength() {
      this.editorEl.toggleClass("is-readable-line-width", !!this.app.vault.getConfig("readableLineLength"));
    },

    onConfigChanged(configKey) {
      host.EditModeBase.prototype.onConfigChanged.call(this, configKey);
      if (configKey === "readableLineLength") this.updateReadableLineLength();
    },

    // ------------------------------------------------------- viewport menu

    onViewportMenu(event) {
      if (event.defaultPrevented || !event.isTrusted) return;
      if (typeof PointerEvent !== "undefined" && event instanceof PointerEvent && event.pointerType === "touch") return;
      const target = event.targetNode || event.target;
      if (!this.sizerEl.contains(target)) return;
      const parent = target.parentElement;
      if (parent && parent.classList && parent.classList.contains("cm-gutters")) return;
      const menu = host.Menu.forEvent(event).addSections(["view", ""]);
      this.app.workspace.trigger("markdown-viewport-menu", menu, this.view, "source", "gutter");
    },
  });

  return MarkdownEditMode;
}

// ---- n-g27-env.js ----
// g27 env: single lazy access point to application-scope (bundle) values.
// bindEnv installs one thunk exactly once at bundle init; env() invokes the
// thunk on EVERY call and returns its result — never cached, so late-bound
// bundle variables stay correct. Before binding, env() yields {}.

let ng27EnvThunk = () => ({});

function bindEnv(t) {
  ng27EnvThunk = t;
}

function env() {
  return ng27EnvThunk();
}

const hostEnv = env;

// ---- n-g27-events.js ----
// g27 events: Events (named-event emitter, orig VT) and Component
// (load/unload lifecycle base, orig jm). Frozen plugin-facing surface:
// Events stores subscriptions in `this._` as {e,name,fn,ctx} records;
// Component owns `_loaded`, `_events` (LIFO cleanups) and `_children`.


function defineEvents() {
  function Events() {
    this._ = {};
  }

  methods(Events, {
    on(name, callback, context) {
      const ref = { e: this, name, fn: callback, ctx: context };
      const list = this._[name] || (this._[name] = []);
      list.push(ref);
      return ref;
    },

    off(name, callback) {
      const list = this._[name];
      if (!list) return;
      if (!callback) {
        delete this._[name];
        return;
      }
      for (let i = list.length - 1; i >= 0; i--) {
        if (list[i].fn === callback) list.splice(i, 1);
      }
      if (list.length === 0) delete this._[name];
    },

    offref(ref) {
      if (!ref) return;
      const list = this._[ref.name];
      if (!list) return;
      const i = list.indexOf(ref);
      if (i >= 0) list.splice(i, 1);
      if (list.length === 0) delete this._[ref.name];
    },

    trigger(name) {
      const list = this._[name];
      if (!list || list.length === 0) return;
      const args = Array.prototype.slice.call(arguments, 1);
      const subs = list.slice();
      for (let i = 0; i < subs.length; i++) this.tryTrigger(subs[i], args);
    },

    tryTrigger(sub, args) {
      try {
        sub.fn.apply(sub.ctx, args);
      } catch (err) {
        // surface on a fresh macrotask: escapes promise machinery, cannot
        // break the remaining subscribers or the trigger caller
        setTimeout(() => { throw err; }, 0);
      }
    },
  });

  return Events;
}

function defineComponent() {
  function Component() {
    this._loaded = false;
    this._events = [];
    this._children = [];
  }

  methods(Component, {
    onload() {},

    onunload() {},

    load() {
      if (this._loaded) return;
      this._loaded = true;
      const pending = [];
      const own = this.onload();
      if (own && typeof own.then === "function") pending.push(own);
      const children = this._children.slice();
      for (let i = 0; i < children.length; i++) {
        const result = children[i].load();
        if (result && typeof result.then === "function") pending.push(result);
      }
      if (pending.length > 0) return Promise.all(pending).then(() => {});
    },

    unload() {
      if (!this._loaded) return;
      this._loaded = false;
      while (this._children.length > 0) this._children.pop().unload();
      while (this._events.length > 0) this._events.pop()();
      this.onunload();
    },

    addChild(child) {
      this._children.push(child);
      if (this._loaded) child.load();
      return child;
    },

    removeChild(child) {
      const i = this._children.indexOf(child);
      if (i >= 0) {
        this._children.splice(i, 1);
        child.unload();
      }
      return child;
    },

    register(cleanup) {
      this._events.push(cleanup);
    },

    registerEvent(ref) {
      this.register(() => ref.e.offref(ref));
    },

    registerDomEvent(target, type, listener, options) {
      target.addEventListener(type, listener, options);
      this.register(() => target.removeEventListener(type, listener, options));
    },

    registerScopeEvent(handler) {
      this.register(() => handler.scope.unregister(handler));
    },

    registerInterval(id) {
      this.register(() => clearInterval(id));
      return id;
    },
  });

  return Component;
}

// ---- n-g27-fileview.js ----
// g27 fileview: FileView (orig MD) — an ItemView bound to one vault file.
// Owns the file binding, header breadcrumbs, rename/delete reaction, view-state
// persistence (state.file) and linked-tab sync inside a tab group.

function defineFileView(host) {
  function FileView(leaf) {
    const self = host.ItemView.call(this, leaf) || this;
    self.allowNoFile = false;
    self.navigation = true;
    self.file = null;
    return self;
  }
  inherit(FileView, host.ItemView);

  methods(FileView, {

    getDisplayText() {
      return this.file ? this.file.basename : host.t.interface.noFile();
    },

    // ------------------------------------------------------------ breadcrumbs

    renderBreadcrumbs() {
      const parentEl = this.titleParentEl;
      parentEl.empty();
      const file = this.file;
      const folder = file && file.parent;
      if (!folder || folder.path === "/") return;
      const app = this.app;
      const vault = app.vault;
      const segments = folder.path.split("/").filter((s) => s.length > 0);
      let prefix = "";
      for (const segment of segments) {
        prefix = prefix ? prefix + "/" + segment : segment;
        const crumb = parentEl.createEl("span", { cls: "view-header-breadcrumb" });
        crumb.setText(segment);
        const dir = vault.getAbstractFileByPath(prefix);
        if (!host.Platform.isMobile) host.setTooltip(crumb, segment);
        crumb.addEventListener("click", () => {
          const explorer = app.internalPlugins.getEnabledPluginById("file-explorer");
          if (explorer && explorer.revealInFolder && dir) explorer.revealInFolder(dir);
        });
        crumb.addEventListener("contextmenu", (event) => {
          if (!dir) return;
          const menu = host.Menu.forEvent(event);
          menu.addSections(["title", "open", "action-primary", "action", "info", "info.copy", "view", "system", "", "danger"]);
          menu.addItem((item) => item
            .setSection("action-primary")
            .setTitle(host.t.plugins.fileExplorer.menuOptNewNote())
            .setIcon("lucide-edit")
            .onClick(async (clickEvent) => {
              const created = await app.fileManager.createNewMarkdownFile(dir, null);
              if (!created) return;
              const leaf = app.workspace.getLeaf(host.Keymap.isModEvent(clickEvent));
              await leaf.openFile(created, { active: true, state: { mode: "source" }, eState: { rename: "all" } });
            }));
          menu.setParentElement(crumb);
          app.workspace.trigger("file-menu", menu, dir, "file-explorer-context-menu");
        });
        app.dragManager.handleDrag(crumb, (evt) => {
          const target = vault.getAbstractFileByPath(prefix);
          if (!(target instanceof host.TFolder)) return null;
          app.dragManager.updateSource([crumb], "is-being-dragged");
          return app.dragManager.dragFolder(evt, target, "file-explorer");
        });
        parentEl.createEl("span", { cls: "view-header-breadcrumb-separator", text: "/" });
      }
    },

    // ------------------------------------------------------------ lifecycle

    onload() {
      host.ItemView.prototype.onload.call(this);
      this.registerEvent(this.app.vault.on("rename", this.onRename, this));
      this.registerEvent(this.app.vault.on("delete", this.onDelete, this));
    },

    getState() {
      const state = host.ItemView.prototype.getState.call(this);
      if (this.file) state.file = this.file.path;
      return state;
    },

    setState(state, result) {
      return (async () => {
        state = state || {};
        let changed = false;
        if (Object.prototype.hasOwnProperty.call(state, "file")) {
          const resolved = this.app.vault.getAbstractFileByPath(state.file);
          if (resolved instanceof host.TFile) changed = await this.loadFile(resolved);
          else changed = await this.loadFile(null);
        }
        if (!this.file && !this.allowNoFile) result.close = true;
        if (changed) {
          result.layout = true;
          result.history = true;
        }
        await host.ItemView.prototype.setState.call(this, state, result);
        if (!state.sync && (result.layout || result.history)) {
          result.done = () => this.syncState();
        }
      })();
    },

    onClose() {
      return (async () => {
        this.contentEl.empty();
        await this.loadFile(null);
      })();
    },

    /** false when `file` is already bound; true after any (re)bind attempt. */
    async loadFile(file) {
      if (file === this.file) return false;
      const previous = this.file;
      if (previous) await this.onUnloadFile(previous);
      this.file = null;
      if (file) {
        try {
          this.file = file;
          await this.onLoadFile(file);
        } catch (err) {
          this.file = null;
          new host.Notice(host.t.interface.msgFailedToLoadFile({ plugin: file.path }));
          console.error(err);
        }
      }
      this.renderBreadcrumbs();
      this.titleEl.setText(this.getDisplayText());
      if (this.leaf.isActiveLeaf()) this.app.workspace.requestActiveLeafEvents();
      this.leaf.updateHeader();
      return true;
    },

    async onLoadFile(file) {},
    async onUnloadFile(file) {},

    // ------------------------------------------------------------ vault events

    async onRename(file) {
      if (file !== this.file) return;
      this.renderBreadcrumbs();
      this.titleEl.setText(file.basename);
      this.app.workspace.onLayoutChange();
      this.leaf.updateHeader();
    },

    async onDelete(file) {
      if (file !== this.file) return;
      const leaf = this.leaf;
      if (this.allowNoFile) {
        await this.loadFile(null);
      } else if (leaf.history.backHistory.length > 0) {
        await leaf.history.back();
      } else {
        await leaf.open(null);
      }
      if (this.leaf.view instanceof host.EmptyView && leaf.parent && leaf.parent.children.length > 1) {
        leaf.detach();
      }
      this.app.workspace.onLayoutChange();
    },

    // ------------------------------------------------------------ linked tabs

    syncState() {
      const group = this.leaf.group;
      if (!group) return;
      for (const leaf of this.app.workspace.getGroupLeaves(group)) {
        if (leaf === this.leaf) continue;
        const view = leaf.view;
        if (view instanceof FileView) view.receiveSyncState(this);
      }
    },

    receiveSyncState(source) {
      if (source.file !== this.file) this.leaf.openFile(source.file);
    },

    canAcceptExtension() {
      return false;
    },
  });

  return FileView;
}

// ---- n-g27-frontmatter.js ----
// g27 frontmatter: readers for well-known properties of a PARSED frontmatter
// object (plain JS object from the YAML parser — never raw text).
// frontmatterEntry(frontmatter, key): string key = own property lookup
// (hasOwnProperty — inherited names never match); RegExp key = first own
// enumerable key (in enumeration order) that test()s true.
// frontmatterStrings: scalar string -> [trimmed]; array -> trimmed string
// elements only (other types dropped, [] possible); anything else -> null.
// frontmatterTags: /^tags$/i via frontmatterStrings, drop empties and entries
// containing a space, prefix "#" unless already present.
// frontmatterAliases: /^aliases$/i via frontmatterStrings, trim again, drop
// empties.

function ng27FmLookup(frontmatter, key) {
  if (frontmatter == null) return null;
  if (typeof key === "string") {
    return Object.prototype.hasOwnProperty.call(frontmatter, key) ? frontmatter[key] : null;
  }
  for (const name of Object.keys(frontmatter)) {
    if (key.test(name)) return frontmatter[name];
  }
  return null;
}

function frontmatterEntry(frontmatter, key) {
  return ng27FmLookup(frontmatter, key);
}

function frontmatterStrings(frontmatter, key) {
  const value = ng27FmLookup(frontmatter, key);
  if (!value) return null;
  if (typeof value === "string") return [value.trim()];
  if (Array.isArray(value)) {
    const out = [];
    for (const item of value) {
      if (typeof item === "string") out.push(item.trim());
    }
    return out;
  }
  return null;
}

function frontmatterTags(frontmatter) {
  const list = frontmatterStrings(frontmatter, /^tags$/i);
  if (list == null) return null;
  const out = [];
  for (const tag of list) {
    if (!tag || tag.indexOf(" ") >= 0) continue;
    out.push(tag.charAt(0) === "#" ? tag : "#" + tag);
  }
  return out;
}

function frontmatterAliases(frontmatter) {
  const list = frontmatterStrings(frontmatter, /^aliases$/i);
  if (list == null) return null;
  const out = [];
  for (const alias of list) {
    const trimmed = alias.trim();
    if (trimmed) out.push(trimmed);
  }
  return out;
}

// ---- n-g27-hover-popover.js ----
// g27 hover-popover: HoverPopover (orig rX) — delayed floating preview with a
// shared global tracker (pending + shown lists, pointer poll, global click).

function defineHoverPopover(host) {

  // ---- shared tracker (module singleton, shared by every instance) --------
  const pending = [];
  const shown = [];
  let pointer = null;      // {x, y, doc} of the last tracked mousemove
  let pollTimer = 0;
  let tracking = false;

  function trackPointer(event) {
    const target = event.targetNode || event.target;
    pointer = {
      x: event.clientX,
      y: event.clientY,
      doc: event.doc || (target && target.ownerDocument) || document,
    };
  }

  function onGlobalClick(event) {
    for (const pop of pending.slice()) pop.hide();
    const target = event.targetNode || event.target;
    const win = event.win
      || (target && target.ownerDocument && target.ownerDocument.defaultView)
      || window;
    for (const pop of shown.slice()) {
      let keep = pop.isFocused;
      if (!keep && target) {
        keep = pop.hoverEl.contains(target);
        if (!keep) {
          for (const child of pop.childHovers) {
            if (child.hoverEl.contains(target)) { keep = true; break; }
          }
        }
      }
      if (!keep) win.setTimeout(() => pop.hide(), 5);
    }
  }

  function poll() {
    if (!pointer) return;
    const under = pointer.doc.elementFromPoint(pointer.x, pointer.y);
    for (const pop of shown.slice()) {
      pop.detect(under);
      pop.transition();
    }
  }

  function ensureTracking() {
    if (tracking) return;
    tracking = true;
    window.addEventListener("click", onGlobalClick, true);
    window.addEventListener("contextmenu", onGlobalClick, true);
    window.addEventListener("mousemove", trackPointer);
    pollTimer = window.setInterval(poll, 500);
  }

  function stopTracking() {
    if (!tracking) return;
    tracking = false;
    window.removeEventListener("click", onGlobalClick, true);
    window.removeEventListener("contextmenu", onGlobalClick, true);
    window.removeEventListener("mousemove", trackPointer);
    window.clearInterval(pollTimer);
    pollTimer = 0;
    pointer = null;
  }

  // ---- the popover ---------------------------------------------------------

  function HoverPopover(parent, targetEl, waitTime, staticPos) {
    const self = host.Component.call(this) || this;
    self.parent = parent;
    self.targetEl = targetEl;
    self.waitTime = waitTime === undefined ? 300 : waitTime;
    self.staticPos = staticPos || null;
    self.onTarget = true;
    self.onHover = false;
    self.isFocused = false;
    self.state = host.PopoverState.Showing;
    self.timer = 0;
    self.observer = null;
    self.hoverEl = createDiv("popover hover-popover");
    self._targetIn = (event) => self.onMouseIn(event);
    self._targetOut = (event) => self.onMouseOut(event);
    self._hoverIn = (event) => {
      if (host.pointerEntered(event, self.hoverEl)) {
        self.onHover = true;
        self.transition();
      }
    };
    self._hoverOut = (event) => {
      if (host.pointerEntered(event, self.hoverEl)) {
        self.onHover = false;
        self.transition();
      }
    };
    if (targetEl) {
      targetEl.addEventListener("mouseover", self._targetIn);
      targetEl.addEventListener("mouseout", self._targetOut);
    }
    self.hoverEl.addEventListener("mouseover", self._hoverIn);
    self.hoverEl.addEventListener("mouseout", self._hoverOut);
    self.timer = host.activeWindow.setTimeout(() => {
      self.timer = 0;
      self.show();
    }, self.waitTime);
    pending.push(self);
    ensureTracking();
    return self;
  }
  inherit(HoverPopover, host.Component);

  methods(HoverPopover, {

    onMouseIn(event) {
      if (this.targetEl && !host.pointerEntered(event, this.targetEl)) return;
      this.onTarget = true;
      this.transition();
    },

    onMouseOut(event) {
      if (this.targetEl && !host.pointerEntered(event, this.targetEl)) return;
      this.onTarget = false;
      this.transition();
    },

    detect(el) {
      const targetEl = this.targetEl;
      if (targetEl) this.onTarget = el === targetEl || targetEl.contains(el);
      this.onHover = el === this.hoverEl || this.hoverEl.contains(el);
    },

    shouldShow() {
      return this.shouldShowSelf() || this.shouldShowChild();
    },

    shouldShowSelf() {
      const doc = this.hoverEl.doc || this.hoverEl.ownerDocument || document;
      return this.onTarget || this.onHover || this.isFocused || this.hoverEl.contains(doc.activeElement);
    },

    shouldShowChild() {
      for (const child of this.childHovers) if (child.shouldShow()) return true;
      return false;
    },

    setIsFocused(focused) {
      this.isFocused = focused;
    },

    clearTimer() {
      if (this.timer) {
        host.activeWindow.clearTimeout(this.timer);
        this.timer = 0;
      }
    },

    transition() {
      const wanted = this.shouldShow();
      if (wanted) {
        if (this.state === host.PopoverState.Hiding) {
          this.state = host.PopoverState.Shown;
          this.clearTimer();
        }
        return;
      }
      if (this.state === host.PopoverState.Showing) {
        this.hide();
        return;
      }
      if (this.state === host.PopoverState.Shown) {
        this.state = host.PopoverState.Hiding;
        this.timer = host.activeWindow.setTimeout(() => {
          this.timer = 0;
          if (this.shouldShow()) this.transition();
          else this.hide();
        }, this.waitTime);
      }
    },
  });

  methods(HoverPopover, {

    show() {
      const targetEl = this.targetEl;
      if (targetEl) {
        const doc = targetEl.doc || targetEl.ownerDocument || document;
        if (!doc.body.contains(targetEl)) {
          this.hide();
          return;
        }
      }
      this.state = host.PopoverState.Shown;
      this.timer = 0;
      this.position();
      this.onShow();
      const pi = pending.indexOf(this);
      if (pi >= 0) pending.splice(pi, 1);
      if (shown.indexOf(this) < 0) shown.push(this);
      ensureTracking();
      this.load();
      runTransition(
        this.hoverEl,
        new host.Transition({ fn: "var(--anim-motion-swing)", duration: 80 }).addProp("opacity", "0", "1", "")
      );
    },

    hide() {
      this.state = host.PopoverState.Hidden;
      const pi = pending.indexOf(this);
      if (pi >= 0) pending.splice(pi, 1);
      const si = shown.indexOf(this);
      if (si >= 0) shown.splice(si, 1);
      if (!pending.length && !shown.length) stopTracking();
      this.clearTimer();
      this.hoverEl.detach();
      const targetEl = this.targetEl;
      if (targetEl) {
        targetEl.removeEventListener("mouseover", this._targetIn);
        targetEl.removeEventListener("mouseout", this._targetOut);
      }
      this.onTarget = true;
      this.onHover = false;
      const hoverEl = this.hoverEl;
      for (const pop of shown.slice()) {
        if (pop === this) continue;
        if (pop.targetEl && hoverEl.contains(pop.targetEl) && !pop.shouldShowSelf()) pop.hide();
      }
      this.onHide();
      this.unload();
    },

    onShow() {
      const prev = this.parent && this.parent.hoverPopover;
      if (prev && prev !== this) prev.hide();
      if (this.parent) this.parent.hoverPopover = this;
      host.hideTooltip();
    },

    onHide() {
      if (this.parent && this.parent.hoverPopover === this) this.parent.hoverPopover = null;
    },
  });

  methods(HoverPopover, {

    position() {
      const targetEl = this.targetEl;
      const point = (p) => ({ top: p.y - 10, bottom: p.y + 10, left: p.x, right: p.x });
      let rect;
      if (this.staticPos) {
        rect = point(this.staticPos);
      } else if (targetEl) {
        if (targetEl.offsetHeight > 300 && pointer) {
          this.staticPos = { x: pointer.x, y: pointer.y };
          rect = point(this.staticPos);
        } else {
          const box = targetEl.getBoundingClientRect();
          rect = {
            top: box.top,
            bottom: box.top + targetEl.offsetHeight,
            left: box.left,
            right: box.left + targetEl.offsetWidth,
          };
        }
      } else if (pointer) {
        rect = point(pointer);
      } else {
        rect = { top: 0, bottom: 0, left: 0, right: 0 };
      }
      const win = targetEl
        ? (targetEl.win || (targetEl.ownerDocument && targetEl.ownerDocument.defaultView) || window)
        : ((pointer && pointer.doc && pointer.doc.defaultView) || window);
      let rtl = false;
      if (targetEl) {
        try { rtl = win.getComputedStyle(targetEl).direction === "rtl"; } catch (e) { /* cross-window */ }
      }
      const mapped = host.rectInTopWindow(rect, win) || { rect, win };
      const topWin = mapped.win || win;
      topWin.document.body.appendChild(this.hoverEl);
      host.positionNear(mapped.rect || rect, this.hoverEl, {
        gap: 10,
        preventOverlap: true,
        horizontalAlignment: rtl ? "right" : "left",
      });
    },

    watchResize(el) {
      if (!this.observer) {
        let fires = 0;
        const self = this;
        this.observer = new ResizeObserver(() => {
          if (self.state !== host.PopoverState.Shown) return;
          self.position();
          fires++;
          if (fires >= 10) {
            self.observer.disconnect();
            self.observer = null;
          }
        });
      }
      this.observer.observe(el);
    },

    onunload() {
      host.Component.prototype.onunload.call(this);
      if (this.observer) {
        this.observer.disconnect();
        this.observer = null;
      }
    },
  });

  Object.defineProperty(HoverPopover.prototype, "childHovers", {
    get() {
      const hoverEl = this.hoverEl;
      return shown.filter((pop) => pop !== this && pop.targetEl && hoverEl.contains(pop.targetEl));
    },
  });

  return HoverPopover;
}

// ---- n-g27-inherit.js ----
// g27 inherit: ES5-style class plumbing.
// inherit(Child, Parent) links BOTH the static chain (Child -> Parent) and the
// instance chain (Child.prototype -> Parent.prototype) with a non-enumerable
// `constructor` own property, and returns Child.
// methods(Class, table) bulk-assigns own enumerable keys onto Class.prototype
// with plain assignment semantics (writable/configurable/enumerable) and
// returns Class.

function inherit(Child, Parent) {
  Child.prototype = Object.create(Parent.prototype, {
    constructor: { value: Child, writable: true, configurable: true },
  });
  Object.setPrototypeOf(Child, Parent);
  return Child;
}

function methods(Class, table) {
  for (const name of Object.keys(table)) Class.prototype[name] = table[name];
  return Class;
}

// ---- n-g27-registry.js ----
// g27 registry: ViewRegistry (orig p0) — app.viewRegistry. Maps view-type
// names to creator functions and file extensions to view types; seeds itself
// with the built-in views. An Events subclass so on/off/trigger/offref work.

function defineViewRegistry(host) {
  function ViewRegistry() {
    const self = host.Events.call(this) || this;
    self.viewByType = {};
    self.typeByExtension = {};
    const builtins = [
      [host.markdownExtensions, host.MarkdownView, host.MarkdownView.VIEW_TYPE],
      [host.imageExtensions, host.ImageView, host.ImageView.VIEW_TYPE],
      [host.audioExtensions, host.AudioView, host.AudioView.VIEW_TYPE],
      [host.videoExtensions, host.VideoView, host.VideoView.VIEW_TYPE],
      [host.pdfExtensions, host.PdfView, host.PdfView.VIEW_TYPE],
      [null, host.ReleaseNotesView, host.releaseNotesType],
    ];
    for (const [extensions, ViewClass, type] of builtins) {
      const creator = (leaf) => new ViewClass(leaf);
      if (extensions) self.registerViewWithExtensions(extensions, type, creator);
      else self.registerView(type, creator);
    }
    return self;
  }
  inherit(ViewRegistry, host.Events);

  methods(ViewRegistry, {
    registerView(type, creator) {
      if (Object.prototype.hasOwnProperty.call(this.viewByType, type)) {
        throw new Error('Attempting to register an existing view type "' + type + '"');
      }
      this.viewByType[type] = creator;
      this.trigger("view-registered", type);
    },

    unregisterView(type) {
      if (!Object.prototype.hasOwnProperty.call(this.viewByType, type)) return;
      delete this.viewByType[type];
      this.trigger("view-unregistered", type);
    },

    registerExtensions(extensions, type) {
      // all-or-nothing: validate every extension before writing any
      for (const ext of extensions) {
        if (Object.prototype.hasOwnProperty.call(this.typeByExtension, ext)) {
          throw new Error('Attempting to register an existing file extension "' + ext + '"');
        }
      }
      for (const ext of extensions) this.typeByExtension[ext] = type;
      this.trigger("extensions-updated");
    },

    unregisterExtensions(extensions) {
      for (const ext of extensions) delete this.typeByExtension[ext];
      this.trigger("extensions-updated");
    },

    registerViewWithExtensions(extensions, type, creator) {
      this.registerView(type, creator);
      if (extensions) this.registerExtensions(extensions, type);
    },

    getViewCreatorByType(type) {
      return this.viewByType[type];
    },

    getTypeByExtension(ext) {
      return this.typeByExtension[ext];
    },

    isExtensionRegistered(ext) {
      return Object.prototype.hasOwnProperty.call(this.typeByExtension, ext);
    },
  });

  return ViewRegistry;
}

