/** A plain digit-string test shared by the canvas colour theming. */
const s13DigitsRe = /^(\d+)$/;
/** "r, g, b" triple used by the canvas colour parser. */
const s13RgbRe = /^\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*$/i;

/**
 * Client rect of `el` as {left, top, width, height, cx, cy, minX, minY, maxX, maxY},
 * offset by the element's border (clientLeft/clientTop) so it lines up with layout coords.
 */
function s13DomRect(el) {
  const r = el.getBoundingClientRect();
  const left = r.left + el.clientLeft;
  const top = r.top + el.clientTop;
  const width = el.clientWidth;
  const height = el.clientHeight;
  return { left, top, width, height, cx: left + width / 2, cy: top + height / 2, minX: -width / 2, minY: -height / 2, maxX: width / 2, maxY: height / 2 };
}

/**
 * The part of `el` that is actually visible: the element's client rect clipped by every
 * scrollable ancestor (and the window). Returned in client coordinates scaled by the
 * element's own pixel ratio correction. A `.print` ancestor means "everything".
 */
function s13VisibleRect(el) {
  if (el.closest(".print")) return { top: 0, left: 0, bottom: Infinity, right: Infinity };
  const r = el.getBoundingClientRect();
  const scale = r.width > 0 ? el.clientWidth / Math.round(r.width) : r.height > 0 ? el.clientHeight / Math.round(r.height) : 1;
  const doc = el.ownerDocument;
  const win = doc.defaultView || window;
  let clipLeft = 0;
  let clipRight = win.innerWidth;
  let clipTop = 0;
  let clipBottom = win.innerHeight;
  let node = el.parentNode;
  while (node && node != doc.body) {
    if (node.nodeType == 1) {
      const style = window.getComputedStyle(node);
      if ((node.scrollHeight > node.clientHeight || node.scrollWidth > node.clientWidth) && style.overflow != "visible") {
        const pr = node.getBoundingClientRect();
        clipLeft = Math.max(clipLeft, pr.left);
        clipRight = Math.min(clipRight, pr.right);
        clipTop = Math.max(clipTop, pr.top);
        clipBottom = Math.min(node == el.parentNode ? win.innerHeight : clipBottom, pr.bottom);
      }
      node = style.position == "absolute" || style.position == "fixed" ? node.offsetParent : node.parentNode;
    } else {
      if (node.nodeType != 11) break;
      node = node.host;
    }
  }
  return {
    left: scale * (clipLeft - r.left),
    right: scale * (Math.max(clipLeft, clipRight) - r.left),
    top: scale * (clipTop - r.top),
    bottom: scale * (Math.max(clipTop, clipBottom) - r.top),
  };
}

/**
 * Calls `onChange` whenever `el` scrolls inside its current window or crosses the
 * intersection-observer threshold. Returns a disposer. `el` must offer isShown(), win and
 * onNodeInserted() (Component instances do).
 */
function s13ScrollWatch(el, onChange) {
  let win = null;
  const observer = new IntersectionObserver(onChange, { threshold: unitSteps(1e3) });
  function onScroll(event) {
    if (win && event.target.contains(el)) onChange();
  }
  function sync() {
    const prev = win;
    const next = el.isShown() ? el.win : null;
    if (next === prev) return;
    if (prev) prev.removeEventListener("scroll", onScroll, { capture: true });
    if (next) next.addEventListener("scroll", onScroll, { capture: true, passive: true });
    win = next;
    onChange();
  }
  observer.observe(el);
  sync();
  const offInserted = el.onNodeInserted(sync);
  return function () {
    offInserted();
    observer.disconnect();
    if (win) {
      win.removeEventListener("scroll", onScroll, { capture: true });
      win = null;
    }
  };
}

/** Joins key names for display ("Ctrl + Alt" style), translating modifiers on macOS. */
function s13KeyNames(keys, host) {
  const names = keys.map((k) => (Object.prototype.hasOwnProperty.call(host.keyNames, k) ? host.keyNames[k] : k));
  return names.join(host.Platform.isMacOS ? " " : " + ");
}

/** Reads the four padding values of a view config into {top,bottom,start,end} lengths. */
function s13PaddingBox(config) {
  return {
    top: floatOr(config.paddingTop, 0),
    bottom: floatOr(config.paddingBottom, 0),
    start: floatOr(config.paddingInlineStart, 0),
    end: floatOr(config.paddingInlineEnd, 0),
  };
}

/**
 * Anchor point for an edge interaction: `placement` ("left" | "top" | "right" | "bottom" |
 * "center" | a corner name) refines the origin; the rect itself is always returned.
 */
function s13AnchorRect(origin, box, placement) {
  if (placement) {
    origin = placement === "center" ? centeredOrigin(origin, box) : (function (r, side) {
      const x = r.x;
      const y = r.y;
      const w = r.width;
      const h = r.height;
      switch (side) {
        case "left": return point(x, y - h / 2);
        case "top": return point(x - w / 2, y);
        case "right": return point(x - w, y - h / 2);
        case "bottom": return point(x - w / 2, y - h);
      }
    })(rectAt(origin, box), placement);
  }
  return rectAt(origin, box);
}

/** Resize handle geometry: which zero-size rect a side/corner drag starts from. */
function s13ResizeOrigin(side, point_, box) {
  const x = box.x;
  const y = box.y;
  const w = box.width;
  const h = box.height;
  let source;
  let resizeX;
  let resizeY;
  switch (side) {
    case "top":
    case "bottom":
      source = rect(x, point_.y, w, 0);
      resizeX = false;
      resizeY = true;
      break;
    case "left":
    case "right":
      source = rect(point_.x, y, 0, h);
      resizeX = true;
      resizeY = false;
      break;
    case "topleft":
    case "topright":
    case "bottomleft":
    case "bottomright":
      source = rect(point_.x, point_.y, 0, 0);
      resizeX = true;
      resizeY = true;
  }
  return { source, resizeX, resizeY };
}

/**
 * The node whose bounding box comes closest to `point` (within `maxDistance`), answered as
 * {side, node} where side is the nearest edge midpoint direction. Null when nothing is in
 * range.
 */
function s13NearestSide(point_, nodes, maxDistance) {
  let best = [Infinity, null];
  for (const node of nodes) {
    const b = node.getBBox();
    const sides = [["top", sideMidpoint(b, "top")], ["right", sideMidpoint(b, "right")], ["bottom", sideMidpoint(b, "bottom")], ["left", sideMidpoint(b, "left")]];
    for (const [side, mid] of sides) {
      const d = distance(point_, mid);
      if (d <= maxDistance) return { side, node };
      if (d < best[0]) best = [d, { side, node }];
    }
  }
  return best[1];
}

/**
 * Aligns two lists sorted in place by their x (axis "x") or y key, returning the runs
 * where source and destination items share a key. `delta` is the current best offset; a
 * smaller non-zero offset found along the way resets the accumulated matches.
 */
function s13MatchSpans(source, dest, delta, axis) {
  if (source.length === 0 || dest.length === 0) return null;
  const key = axis === "x" ? boxX : boxY;
  sortByKey(source, key);
  sortByKey(dest, key);
  let bestDelta = delta;
  const matches = [];
  let srcRun = [];
  let dstRun = [];
  let lastKey = Infinity;
  for (const item of source) {
    const k = key(item);
    if (k !== lastKey) {
      lastKey = k;
      if (srcRun.length > 0 || dstRun.length > 0) {
        matches.push({ src: srcRun, dest: dstRun });
        srcRun = [];
        dstRun = [];
      }
      // binary search for the first dest with key >= k
      let lo = 0;
      let hi = dest.length - 1;
      while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        const diff = k - key(dest[mid]);
        if (diff > 0) lo = mid + 1;
        else if (diff < 0) hi = mid - 1;
        else { lo = hi = mid; break; }
      }
      if (lo !== hi) {
        if (hi < 0) hi = 0;
        else if (lo >= dest.length - 1) lo = dest.length - 1;
        else {
          const leftDiff = key(dest[lo]) - k;
          const rightDiff = k - key(dest[hi]);
          if (leftDiff === rightDiff) {
            if (leftDiff === bestDelta) hi = lo;
            else lo = hi;
          } else {
            const pick = leftDiff < rightDiff ? lo : hi;
            lo = hi = pick;
          }
        }
      }
      const destKey = key(dest[lo]);
      const off = destKey - k;
      if (off === bestDelta || Math.abs(off) < Math.abs(bestDelta)) {
        if (off !== bestDelta) {
          matches.length = 0;
          srcRun = [];
          dstRun = [];
          bestDelta = off;
        }
        while (lo > 0 && key(dest[lo - 1]) === destKey) lo--;
        while (hi < dest.length - 1 && key(dest[hi + 1]) === destKey) hi++;
        srcRun.push(item);
        for (let c = lo; c <= hi; c++) dstRun.push(dest[c]);
      }
    } else if (srcRun.length > 0 && key(srcRun[srcRun.length - 1]) === k) {
      srcRun.push(item);
    }
  }
  if (srcRun.length > 0 || dstRun.length > 0) matches.push({ src: srcRun, dest: dstRun });
  return matches.length === 0 ? null : { matches, delta: bestDelta };
}

/**
 * Applies a canvas colour name/custom value to `el`: clears previous colour classes, sets
 * `is-themed`, then either a numbered `mod-canvas-color-N` class or a custom
 * `--canvas-color` property parsed through the host colour parser.
 */
function s13ApplyCanvasColor(el, color, host) {
  color = (color || "").trim();
  const classes = Array.from(el.classList);
  for (const cls of classes) {
    if (cls.startsWith("mod-canvas-color")) el.removeClass(cls);
  }
  el.style.removeProperty("--canvas-color");
  el.toggleClass("is-themed", !!color);
  if (!color) return;
  if (s13DigitsRe.test(color)) {
    el.addClass("mod-canvas-color-" + color);
    return;
  }
  const parsed = host.s13ParseColor(color);
  if (parsed) {
    el.addClass("mod-canvas-color-custom");
    el.style.setProperty("--canvas-color", `${parsed.r},${parsed.g},${parsed.b}`);
  }
}

// ---- s13-mobile.js ----
// Mobile shell pieces: the tab-switcher item and switcher, the bottom toolbar, the
// share-intent handler and the audio recorder plugin.

// Cross-factory class references; only touched from method bodies at runtime.
let S13MobileTabItem = null;

const s13Div = (...args) => env().createDiv(...args);
const i18nMobile = () => env().gm.interface.mobile;

/** One tab preview tile inside the mobile tab switcher. */
function defineS13MobileTabItem(host) {
  function MobileTabItem(leaf, switcher) {
    const self = this;
    this.app = leaf.app;
    this.leaf = leaf;
    this.switcher = switcher;
    this.containerEl = s13Div("mobile-tab", (el) => {
      const preview = el.createDiv("mobile-tab-preview");
      const pin = preview.createDiv("mobile-tab-pin", (pinEl) => {
        host.setIcon(pinEl, "lucide-pin");
        pinEl.addEventListener("click", (event) => {
          event.preventDefault();
          self.leaf.setPinned(false);
        });
      });
      const close = preview.createDiv("close-button", (closeEl) => {
        host.setIcon(closeEl, "lucide-x");
        closeEl.addEventListener("click", (event) => {
          event.preventDefault();
          self.containerEl.detach();
          self.leaf.detach();
        });
      });
      pin.toggle(leaf.pinned);
      close.toggle(!leaf.pinned);
      leaf.on("pinned-change", () => {
        pin.toggle(self.leaf.pinned);
        close.toggle(!self.leaf.pinned);
      });
      self.previewImgEl = preview.createEl("img", "mobile-tab-preview-embed");
      host.setIcon(self.placeholderEl = preview.createDiv("mobile-tab-preview-empty"), leaf.getIcon());
      self.previewImgEl.src = switcher.cacheDir + "leaf-" + leaf.id + ".png?" + Date.now();
      self.previewImgEl.addEventListener("error", () => self.togglePlaceholder(true));
      self.previewImgEl.addEventListener("load", () => self.togglePlaceholder(leaf.view instanceof host.EmptyView));
      self.titleEl = el.createDiv({ cls: "mobile-tab-title", text: leaf.getDisplayText() });
      el.addEventListener("click", (event) => {
        if (!event.defaultPrevented) {
          event.preventDefault();
          self.onClick();
        }
      });
      el.addEventListener("contextmenu", (event) => {
        if (!event.defaultPrevented) {
          event.preventDefault();
          leaf.onOpenTabHeaderMenu(event, el);
        }
      });
    });
  }

  MobileTabItem.prototype.togglePlaceholder = function (show) {
    this.placeholderEl.toggle(show);
    this.previewImgEl.toggle(!show);
  };

  MobileTabItem.prototype.onClick = function () {
    this.app.workspace.setActiveLeaf(this.leaf);
    this.switcher.hide();
  };

  MobileTabItem.prototype.render = function () {
    const el = this.containerEl;
    const leaf = this.leaf;
    el.removeClass("is-active");
    this.titleEl.setText(leaf.getDisplayText());
  };

  S13MobileTabItem = MobileTabItem;
  return MobileTabItem;
}

/** Full-screen overlay listing open tabs with live screenshot previews. */
function defineS13TabSwitcher(host) {
  function TabSwitcher(app) {
    const self = this;
    this.cacheDir = "";
    this.tabPreviewLookup = new WeakMap();
    this.isVisible = false;
    this.requestRender = debounceCall(() => self.render(), 100);
    this.app = app;
    this.containerEl = s13Div("mobile-tab-switcher");
    this.scrollEl = this.containerEl.createDiv("mobile-tab-switcher-scroll");
    this.innerScrollEl = this.scrollEl.createDiv("mobile-tab-switcher-inner-scroll");
    const menuBar = this.menuBarEl = this.containerEl.createDiv("mobile-tab-switcher-menubar");
    menuBar.createDiv("mobile-tab-switcher-menu-spacer", (el) => {
      el.createDiv({ cls: "clickable-icon" }, (icon) => {
        host.setIcon(icon, "lucide-plus");
        icon.addEventListener("click", () => {
          app.commands.executeCommandById("workspace:new-tab");
          self.hide();
        });
      });
    });
    menuBar.createDiv({ cls: "mobile-tab-switcher-menu-button tappable" }, (el) => {
      self.tabCountEl = el.createSpan();
      host.setIcon(el.createSpan("mobile-tab-switcher-menu-button-chevron"), "lucide-chevron-down");
    }).addEventListener("click", (event) => self.showTabManagementMenu(event));
    menuBar.createDiv("mobile-tab-switcher-menu-spacer", (el) => {
      el.createDiv({ cls: "clickable-icon", text: env().gm.dialogue.buttonDone() }, (done) => {
        done.addEventListener("click", () => self.hide());
      });
    });
    this.setupCacheDir();
    if (host.Platform.isMobileApp && env().xm) {
      env().xm.addListener("screenshotSaved", (event) => {
        const uri = host.s13CapacitorModule.Ii.convertFileSrc(event.uri);
        const images = self.innerScrollEl.findAll("img");
        for (const img of images) {
          if (img.src.startsWith(uri)) {
            img.src = uri + "?" + Date.now();
            return;
          }
        }
      });
    }
    app.workspace.on("layout-change", this.onLayoutChange, this);
  }

  TabSwitcher.prototype.onLayoutChange = function () {
    if (this.isVisible) this.requestRender();
  };

  TabSwitcher.prototype.setupCacheDir = async function () {
    const app = this.app;
    if (host.Platform.isMobileApp && env().Dm) {
      const result = await env().Dm.getUri({
        path: app.appId + "/tab-preview",
        directory: host.s13CapacitorDirectory.Cache,
      });
      this.cacheDir = host.s13CapacitorModule.Ii.convertFileSrc(result.uri);
      if (!this.cacheDir.endsWith("/")) this.cacheDir += "/";
    }
  };

  TabSwitcher.prototype.render = function () {
    const self = this;
    const app = this.app;
    const lookup = this.tabPreviewLookup;
    let count = 0;
    app.workspace.iterateRootLeaves(() => { count++; });
    const renderGroup = (group) => {
      const container = self.innerScrollEl.createDiv("mobile-tab-group-container");
      for (const child of group.children) {
        const wrapper = container.createDiv("mobile-tab-wrapper");
        let item = lookup.get(child);
        if (item == null) {
          item = new S13MobileTabItem(child, self);
          lookup.set(child, item);
        }
        item.render();
        wrapper.append(item.containerEl);
      }
      return container;
    };
    const groups = [];
    const walk = (split) => {
      for (const child of split.children) {
        if (child instanceof host.WorkspaceTabs) groups.push(renderGroup(child));
        else if (child instanceof host.WorkspaceSplit) walk(child);
      }
    };
    walk(app.workspace.rootSplit);
    this.innerScrollEl.setChildrenInPlace(groups);
    this.tabCountEl.setText(env().gm.nouns.tabsWithCount({ count }));
    const active = app.workspace.getMostRecentLeaf();
    if (active) {
      const item = this.tabPreviewLookup.get(active);
      if (item != null) item.containerEl.addClass("is-active");
    }
  };

  TabSwitcher.prototype.show = async function () {
    this.isVisible = true;
    host.s13OverlayPush(this);
    const leaf = this.app.workspace.getMostRecentLeaf();
    if (leaf && host.Platform.isMobileApp && env().xm) {
      const view = leaf.view;
      let target = view.containerEl;
      if (view instanceof host.ItemView && view.contentEl.isShown()) target = view.contentEl;
      document.body.addClass("is-screenshotting");
      await env().sleep(16);
      setTimeout(() => document.body.removeClass("is-screenshotting"), 100);
      const rect = target.getBoundingClientRect();
      const shotRect = rect.width > 0 && rect.height > 0
        ? { x: Math.round(rect.x), y: Math.round(rect.y), width: Math.round(rect.width), height: Math.round(rect.height) }
        : undefined;
      try {
        await env().xm.takeScreenshot({
          path: this.app.appId + "/tab-preview/leaf-" + leaf.id + ".png",
          rect: shotRect,
        });
      } catch (error) {
        console.error(error);
      }
    }
    this.render();
    document.body.appendChild(this.containerEl);
    const active = this.app.workspace.getMostRecentLeaf();
    if (active) {
      this.tabPreviewLookup.get(active)?.containerEl.scrollIntoView({ block: "nearest" });
    }
    runTransition(this.containerEl, new host.Transition({ duration: 90, fn: "var(--anim-motion-swing)" })
      .addProp("opacity", "0", "1", "")
      .addProp("transform", "scale(1.1)", "scale(1)", ""));
  };

  TabSwitcher.prototype.showTabManagementMenu = function (event) {
    const self = this;
    const menu = host.Menu.forEvent(event);
    menu.addSections(["open", "danger"]);
    menu.addItem((item) => item.setTitle(env().gm.commands.newTab()).setIcon("lucide-plus").setSection("open").onClick(() => {
      self.app.commands.executeCommandById("workspace:new-tab");
    })).addItem((item) => item.setTitle(env().gm.commands.undoCloseTab()).setSection("open").setIcon("lucide-undo-2").setDisabled(!self.app.workspace.hasUndoHistory()).onClick(() => {
      self.app.commands.executeCommandById("workspace:undo-close-pane");
    }));
    const leaf = this.app.workspace.getMostRecentLeaf();
    const siblings = leaf ? leaf.parent.children.slice() : [];
    if (siblings.length > 1) {
      menu.addItem((item) => item.setTitle(env().gm.interface.menu.closeTabsWithCount({ count: siblings.length })).setIcon("lucide-archive-x").setDisabled(!leaf).setSection("danger").setWarning(true).onClick(() => {
        if (leaf) for (const sibling of siblings) sibling.detach();
      }));
    }
    if (!this.isVisible) {
      menu.addItem((item) => item.setTitle(env().gm.interface.menu.close()).setSection("danger").setDisabled(!leaf).setWarning(true).setIcon("lucide-x").onClick(() => {
        leaf?.detach();
      }));
    }
  };

  TabSwitcher.prototype.hide = function () {
    const el = this.containerEl;
    this.isVisible = false;
    host.s13OverlayPop(this);
    runTransition(el, new host.Transition({ duration: 90, fn: host.s13EaseStandard })
      .addProp("opacity", "1", "0", "")
      .addProp("transform", "scale(1)", "scale(1.1)", ""), () => el.detach());
  };

  TabSwitcher.prototype.close = function () {
    this.hide();
  };

  return TabSwitcher;
}

/** The floating bottom toolbar shown on mobile while editing. */
function defineS13MobileToolbar(host) {
  function MobileToolbar(app) {
    const self = this;
    this.isVisible = false;
    this.lastKeyboardHeight = 0;
    this.hasKeyboardVisible = false;
    this.isMultiWindowMode = false;
    this.lastCommandIds = "";
    this.app = app;
    this.spacerEl = s13Div("mobile-toolbar-spacer");
    const wrapperEl = this.wrapperEl = s13Div("mobile-toolbar");
    const containerEl = this.containerEl = wrapperEl.createDiv("mobile-toolbar-options-container");
    const listWrap = this.optionsContainerListEl = containerEl.createDiv("mobile-toolbar-options-list-container mod-raised");
    this.optionsListEl = listWrap.createDiv("mobile-toolbar-options-list");
    if (host.Platform.isIosApp && host.Platform.isMobile) {
      containerEl.createDiv("mobile-toolbar-floating-options mod-raised", (el) => {
        el.createDiv("mobile-toolbar-option", (option) => {
          host.setIcon(option, "keyboard-toggle");
          option.addEventListener("mousedown", (event) => event.preventDefault());
          option.addEventListener("click", (event) => {
            app.commands.executeCommandById("editor:toggle-keyboard", event);
            event.preventDefault();
          });
        });
      });
    }
    this.update = debounceCall(this.update.bind(this), 0, true);
    window.addEventListener("keyboardWillHide", (event) => {
      self.animateToKeyboardHeight();
      if (!event.hasPhysicalKeyboard) {
        self.hasKeyboardVisible = false;
        if (host.Platform.isAndroidApp) self.update();
      }
    });
    window.addEventListener("keyboardWillShow", () => {
      self.animateToKeyboardHeight();
      self.hasKeyboardVisible = true;
      if (host.Platform.isAndroidApp) self.update();
    });
    window.addEventListener("focusout", () => self.update());
    window.addEventListener("focusin", () => self.update());
    if (host.Platform.isAndroidApp) {
      window.addEventListener("multiWindowModeChanged", (event) => {
        self.isMultiWindowMode = event.isMultiWindowMode;
        self.update();
      });
      if (env().Im) {
        env().Im.isMultiWindowMode().then((result) => {
          self.isMultiWindowMode = result.isMultiWindowMode;
          self.update();
        });
      }
    }
  }

  MobileToolbar.prototype.compileToolbar = function () {
    const app = this.app;
    const listEl = this.optionsListEl;
    const commands = app.vault.getConfig("mobileToolbarCommands");
    const serialized = JSON.stringify(commands);
    if (serialized === this.lastCommandIds) return;
    listEl.empty();
    const registry = app.commands;
    for (const id of commands) {
      const command = registry.findCommand(id);
      if (!command) continue;
      listEl.createDiv("mobile-toolbar-option", (option) => {
        const icon = command.icon || "question-mark-glyph";
        host.setIcon(option, icon);
        option.addEventListener("click", (event) => {
          registry.executeCommandById(id, event);
          event.preventDefault();
        });
        option.addEventListener("mousedown", (event) => event.preventDefault());
      });
    }
    this.lastCommandIds = serialized;
  };

  MobileToolbar.prototype.update = function () {
    this.lastKeyboardHeight = floatOr(getComputedStyle(document.documentElement).getPropertyValue("--keyboard-height"), 0);
    const app = this.app;
    const visible = this.isVisible;
    let editing = app.workspace.activeEditor?.editor.hasFocus();
    if (host.Platform.isAndroidApp && editing) {
      editing = this.hasKeyboardVisible || this.isMultiWindowMode;
    }
    if (editing) {
      if (!visible) this.show();
    } else if (visible) {
      this.hide();
    }
  };

  MobileToolbar.prototype.animateToKeyboardHeight = function () {
    if (!this.isVisible) return;
    const el = this.wrapperEl;
    const height = floatOr(getComputedStyle(document.documentElement).getPropertyValue("--keyboard-height"), 0);
    const delta = height - this.lastKeyboardHeight + "px";
    this.lastKeyboardHeight = height;
    if (host.Platform.isIosApp) {
      runTransition(el, new host.Transition({ duration: 300, fn: "cubic-bezier(.12,0,.44,.99)" })
        .addProp("transform", "translateY(" + delta + ")", ""));
    }
    if (host.Platform.isAndroidApp) {
      runTransition(el, new host.Transition({ duration: 350, fn: "cubic-bezier(.22,.25,0,1)" })
        .addProp("transform", "translateY(" + delta + ")", ""));
    }
  };

  MobileToolbar.prototype.show = function () {
    if (this.app.vault.getConfig("mobileToolbarCommands").length === 0) {
      this.hide();
      return;
    }
    this.app.mobileNavbar.hide();
    if (this.isVisible) return;
    this.isVisible = true;
    this.compileToolbar();
    const app = this.app;
    app.dom.appContainerEl.appendChild(this.spacerEl);
    app.dom.appContainerEl.appendChild(this.wrapperEl);
    document.body.addClass("mod-toolbar-open");
  };

  MobileToolbar.prototype.hide = function () {
    this.isVisible = false;
    this.spacerEl.detach();
    this.wrapperEl.detach();
    this.app.mobileNavbar.show();
    document.body.removeClass("mod-toolbar-open");
  };

  return MobileToolbar;
}

/** Handles content shared into the app from other apps (mobile share sheet). */
function defineS13ShareIntent(host) {
  function ShareIntent(app) {
    this.app = app;
  }

  ShareIntent.prototype.setupNative = function () {
    const self = this;
    if (env().Em && env().xm) {
      env().xm.addListener("appShareIntent", async (intent) => {
        env().Lv();
        if (intent.type === "text") await self.handleShareText(intent.text);
        else if (intent.type === "files") await self.handleShareFiles(intent.files);
      });
    }
  };

  ShareIntent.prototype.setupWorkspace = function () {
    const app = this.app;
    const workspace = app.workspace;
    workspace.on("receive-text-menu", (menu, text) => {
      const view = workspace.getActiveViewOfType(host.MarkdownView);
      if (!view) return;
      menu.addItem((item) => item.setSection("options").setTitle(i18nMobile().actionInsertTextIntoFile({ filename: view.file.basename })).setIcon("lucide-file").onClick(() => {
        const insert = "\n" + text + "\n";
        if (view.getMode() === "preview") app.fileManager.insertIntoFile(view.file, insert);
        else view.editor.insertText(insert);
      }));
      menu.addItem((item) => item.setSection("options").setTitle(i18nMobile().actionChooseFileToInsert()).setIcon("lucide-navigation").onClick(() => {
        new host.s13FilePickerModal(app, text).open();
      }));
    });
    workspace.on("receive-files-menu", (menu, files) => {
      const view = workspace.getActiveViewOfType(host.MarkdownView);
      if (!view) return;
      menu.addItem((item) => item.setTitle(i18nMobile().actionInsertLinkIntoFile({ filename: view.file.basename })).setIcon("lucide-file").onClick(() => {
        const links = files.map((file) => {
          const link = app.fileManager.generateMarkdownLink(file, view.file.path);
          return host.s13IsMediaFile(file.extension) ? "!" + link : link;
        });
        view.editor.insertText("\n" + links.join("\n") + "\n");
      }));
    });
  };

  ShareIntent.prototype.handleShareText = async function (text) {
    const menu = new host.Menu().addSections(["title", "options", "danger"])
      .addItem((item) => item.setSection("title").setTitle(ellipsize(text, 300)).setIcon("lucide-list-end").setIsLabel(true).titleEl.addClass("u-muted", "u-small"))
      .addItem((item) => item.setSection("options").setTitle(i18nMobile().actionInsertTextDesc()).removeIcon().setIsLabel(true).titleEl.addClass("u-muted", "u-small"));
    this.app.workspace.trigger("receive-text-menu", menu, text);
    menu.addItem((item) => item.setSection("danger").setTitle(env().gm.dialogue.buttonCancel()).setIcon("lucide-x").onClick(() => null))
      .showAtPosition({ x: 0, y: 0 });
  };

  ShareIntent.prototype.handleShareFiles = async function (files) {
    const self = this;
    new host.Menu()
      .addItem((item) => item.setTitle(env().createFragment((frag) => {
        for (const file of files) frag.createDiv({ text: file.name });
      })).removeIcon().setIsLabel(true).titleEl.addClass("u-muted", "u-small"))
      .addSeparator()
      .addItem((item) => item.setTitle(i18nMobile().actionImport()).setIcon("lucide-files").onClick(() => self.importFiles(files)))
      .addItem((item) => item.setTitle(env().gm.dialogue.buttonCancel()).setIcon("lucide-x").onClick(() => null))
      .showAtPosition({ x: 0, y: 0 });
  };

  ShareIntent.prototype.importFiles = async function (files) {
    const imported = [];
    const notice = new host.Notice(i18nMobile().msgImporting(), 0);
    let done = 0;
    const vault = this.app.vault;
    for (const file of files) {
      try {
        if (files.length > 1) notice.setMessage(i18nMobile().msgImporting() + " (" + done + "/" + files.length + ")");
        const response = await fetch(host.s13CapacitorModule.Ii.convertFileSrc(file.uri));
        const buffer = await response.arrayBuffer();
        const name = file.name || lastSegment(file.uri);
        const base = baseName(name);
        const ext = extensionOf(name);
        let path;
        if (ext === "md") {
          path = vault.getAvailablePath(base, ext);
        } else {
          path = await vault.getAvailablePathForAttachments(base, ext, this.app.workspace.getActiveFile());
        }
        const created = await vault.createBinary(path, buffer);
        imported.push(created);
        done++;
      } catch (error) {
        notice.hide();
        new host.Notice(i18nMobile().msgFailedToImportFile({ filename: file.name }));
        new host.Notice(ellipsize(error.toString(), 100));
        return;
      }
    }
    notice.hide();
    const menu = new host.Menu()
      .addItem((item) => item.setTitle(i18nMobile().msgImportSuccess()).removeIcon().setIsLabel(true))
      .addSeparator();
    menu.addItem((item) => item.setTitle(env().gm.dialogue.buttonDone()).setIcon("lucide-check").onClick(() => null));
    this.app.workspace.trigger("receive-files-menu", menu, imported);
    menu.showAtPosition({ x: 0, y: 0 });
  };

  return ShareIntent;
}

/** Records microphone audio and saves it as a note attachment. */
function defineS13AudioRecorder(host) {
  function AudioRecorder() {
    this.id = "audio-recorder";
    this.name = env().gm.plugins.audioRecorder.name();
    this.description = env().gm.plugins.audioRecorder.desc();
    this.app = null;
    this.plugin = null;
    this.recording = false;
    this.recorder = null;
    this.extension = "";
  }

  AudioRecorder.prototype.init = function (app, plugin) {
    this.app = app;
    this.plugin = plugin;
    plugin.registerRibbonItem(env().gm.plugins.audioRecorder.actionToggle(), "lucide-mic", this.onRecordAudio.bind(this));
    plugin.registerGlobalCommand({
      id: "audio-recorder:start",
      name: env().gm.plugins.audioRecorder.actionStart(),
      icon: "lucide-play-circle",
      checkCallback: (checking) => {
        if (this.recording) return false;
        if (!checking) this.onStartRecording();
        return true;
      },
    });
    plugin.registerGlobalCommand({
      id: "audio-recorder:stop",
      name: env().gm.plugins.audioRecorder.actionStop(),
      icon: "lucide-stop-circle",
      checkCallback: (checking) => {
        if (!this.recording) return false;
        if (!checking) this.onStopRecording();
        return true;
      },
    });
  };

  AudioRecorder.prototype.checkPermission = async function () {
    if (host.Platform.isDesktopApp && host.s13PlatformOs === "macOS") {
      const electron = env().If("electron");
      if (!electron) {
        this.showRecordingMessage(env().gm.plugins.audioRecorder.msgAccessDenied(), true);
        return false;
      }
      const prefs = electron.remote.systemPreferences;
      const status = prefs.getMediaAccessStatus("microphone");
      if (["denied", "restricted", "unknown"].includes(status)) {
        this.showRecordingMessage(env().gm.plugins.audioRecorder.msgAccessDenied(), true);
        return false;
      }
      if (status === "not-determined") {
        this.showRecordingMessage(env().gm.plugins.audioRecorder.msgPendingGrant(), false);
        return await prefs.askForMediaAccess("microphone");
      }
      return status === "granted";
    }
    return true;
  };

  AudioRecorder.prototype.onRecordAudio = async function () {
    if (!(await this.checkPermission())) return;
    if (this.recording) this.onStopRecording();
    else await this.onStartRecording();
  };

  AudioRecorder.prototype.onStartRecording = async function () {
    if (host.s13IsIos && !navigator.mediaDevices) {
      new host.Notice("This functionality requires iOS 14.5.");
      return;
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: false });
      await this.startRecording(stream);
    } catch (error) {
      if (error.message.includes("Requested device not found") && this.plugin.addedButtonEls.length > 0) {
        const message = env().gm.plugins.audioRecorder.msgNoMicrophone();
        this.showRecordingMessage(message, true);
      } else {
        if (error.message.includes("denied")) new host.Notice(error.message);
        console.error(error);
      }
      return;
    }
    this.recording = true;
    this.plugin.addedButtonEls.forEach((el) => {
      host.setIcon(el, "lucide-mic");
      el.addClass("is-active");
    });
  };

  AudioRecorder.prototype.onStopRecording = function () {
    this.recording = false;
    this.recorder.stop();
    this.plugin.addedButtonEls.forEach((el) => el.removeClass("is-active"));
  };

  AudioRecorder.prototype.startRecording = function (stream) {
    const self = this;
    const chunks = [];
    let mime = 'audio/webm;codecs="opus"';
    this.extension = "webm";
    if (MediaRecorder.isTypeSupported(s13AudioMime)) {
      mime = s13AudioMime;
      this.extension = "m4a";
    }
    this.recorder = new MediaRecorder(stream, { mimeType: mime });
    this.recorder.addEventListener("dataavailable", (event) => {
      if (event.data.size > 0) chunks.push(event.data);
    });
    this.recorder.addEventListener("stop", async () => {
      this.recorder = null;
      stream.getTracks().forEach((track) => track.stop());
      let blob = new Blob(chunks, { type: mime });
      if (this.extension === "webm") {
        try {
          blob = await host.s13AudioConverter()(blob);
        } catch (error) {
          console.error(error);
        }
      }
      const buffer = await blob.arrayBuffer();
      await self.saveRecording(buffer);
      keepAwake?.release();
    });
    this.recorder.start();
    let keepAwake = null;
    if (env().Em) keepAwake = host.s13KeepAwake();
  };

  AudioRecorder.prototype.saveRecording = async function (buffer) {
    const app = this.app;
    const workspace = app.workspace;
    const name = "Recording " + window.moment().format("YYYYMMDDHHmmss");
    const activeFile = workspace.getActiveFile();
    const view = workspace.getActiveViewOfType(host.MarkdownView);
    const path = await app.vault.getAvailablePathForAttachments(name, this.extension, activeFile);
    const file = await app.vault.createBinary(path, buffer);
    if (view) {
      const link = app.fileManager.generateMarkdownLink(file, view.file.path);
      view.editor.replaceSelection("\n!" + link + "\n");
    } else {
      await workspace.getUnpinnedLeaf().openFile(file, { active: true });
    }
  };

  AudioRecorder.prototype.showRecordingMessage = function (message, isError) {
    if (this.plugin.addedButtonEls.length > 0) {
      host.displayTooltip(this.plugin.addedButtonEls[0], message, {
        placement: "right",
        classes: isError ? ["mod-error"] : [],
      });
    }
  };

  return AudioRecorder;
}

// ---- s13-spatial.js ----
// Compatibility shim: the implementation lives in n-g31-spatial.js. Tests and
// historical importers address this module by its original file name.

const s13Compare = ng31Compare;
const s13Swap = ng31Swap;
const s13IndexOf = ng31IndexOf;
const s13SelectKth = ng31SelectKth;
const s13Quickselect = ng31Quickselect;
const s13QuickselectChunks = ng31QuickselectChunks;
const s13NewNode = ng31NewNode;
const s13GrowBounds = ng31GrowBounds;
const s13ChildrenBounds = ng31ChildrenBounds;
const s13SubtreeBounds = ng31SubtreeBounds;
const s13BoundsMinX = ng31BoundsMinX;
const s13BoundsMinY = ng31BoundsMinY;
const s13BoundsSpan = ng31BoundsSpan;
const s13BoundsArea = ng31BoundsArea;
const s13BoundsContains = ng31BoundsContains;
const s13BoundsOverlap = ng31BoundsOverlap;
const s13CellRange = ng31CellRange;
const s13ExtendRange = ng31ExtendRange;

// ---- s13-ui.js ----
// Small UI pieces of the slice: the bases summary-formula menu pages, the view
// switcher suggestion modal, the file picker modal, the thumbnail background helper,
// the canvas help modal and the quick-actions registry.

// Classes produced by the define* factories; referenced across factories only inside
// method bodies that run after every factory has executed.
let S13SummaryFormulaListPage = null;
let S13SummaryFormulaPage = null;

const s13BasesT = () => s13BasesI18n();

/** Suggestion modal listing the available view types for a bases file. */
function defineS13ViewSwitcherModal(host) {
  function ViewSwitcherModal(parentArg, controller, options) {
    const self = host.FuzzySuggestModal.call(this, parentArg) || this;
    self.options = options;
    self.controller = controller;
    self.setInstructions([
      { command: "↑↓", purpose: env().gm.plugins.commandPalette.instructionNavigate() },
      { command: "↵", purpose: env().gm.plugins.commandPalette.instructionUse() },
      { command: "esc", purpose: env().gm.plugins.commandPalette.instructionDismiss() },
    ]);
    self.scope.register(null, "Tab", () => false);
    self.scope.register(null, "Enter", (event) => {
      if (!event.isComposing) {
        self.selectActiveSuggestion(event);
        return false;
      }
    });
    return self;
  }
  inherit(ViewSwitcherModal, host.FuzzySuggestModal);

  ViewSwitcherModal.prototype.getItems = function () {
    return this.options;
  };

  ViewSwitcherModal.prototype.renderSuggestion = function (item, el) {
    host.FuzzySuggestModal.prototype.renderSuggestion.call(this, item, el);
    if (item === this.controller.viewName) {
      el.createSpan({ cls: "flair toolbar-badge", text: env().gm.setting.appearance.labelCurrentlyActive() });
    }
  };

  ViewSwitcherModal.prototype.getItemText = function (item) {
    return item;
  };

  ViewSwitcherModal.prototype.onChooseItem = function (item) {
    this.controller.selectView(item);
  };

  return ViewSwitcherModal;
}

/**
 * Controller of the summary-formula picker: a page stack inside one menu, with
 * Escape going back and closing at the root.
 */
function defineS13SummaryMenu(host) {
  function SummaryMenu(queryController, viewConfig, propertyId, ctx, containerEl) {
    this.pageStack = [];
    this.viewConfig = null;
    const app = this.app = queryController.app;
    this.queryController = queryController;
    this.viewConfig = viewConfig;
    this.containerEl = containerEl;
    this.propertyId = propertyId;
    this.ctx = ctx;
    this.scope = new host.Scope(app.scope);
    this.scope.register([], "Escape", () => this.close());
    const name = parsePropertyId(propertyId).name;
    this.menu = new host.s13BasesMenu(app, containerEl, name);
    this.menu.setOpen(true);
    this.show(new S13SummaryFormulaListPage(this));
  }

  SummaryMenu.prototype.show = function (page) {
    this.menu.scrollEl.setChildrenInPlace([page.containerEl]);
    page.onShow();
    this.pageStack.push(page);
    this.app.keymap.pushScope(page.scope);
  };

  SummaryMenu.prototype.isOpen = function () {
    return this.menu.isOpen;
  };

  SummaryMenu.prototype.close = function () {
    let page;
    while ((page = this.pageStack.pop())) this.app.keymap.popScope(page.scope);
    this.menu.setAutoDestroy(this.containerEl);
    this.menu.setOpen(false);
  };

  SummaryMenu.prototype.back = function () {
    const page = this.pageStack.pop();
    if (page) this.app.keymap.popScope(page.scope);
    const prev = this.pageStack.at(-1);
    if (prev) {
      this.menu.scrollEl.setChildrenInPlace([prev.containerEl]);
      prev.onShow();
    }
  };

  SummaryMenu.prototype.selectSummaryFormula = function (formula) {
    this.viewConfig.setSummaryKey(this.propertyId, formula);
  };

  SummaryMenu.prototype.getSelectedSummaryKey = function () {
    return this.viewConfig.getSummaryKey(this.propertyId);
  };

  return SummaryMenu;
}

/** Page of the summary menu listing built-in and custom summary formulas. */
function defineS13SummaryFormulaListPage(host) {
  const collator = new Intl.Collator(undefined, { usage: "sort", sensitivity: "base", numeric: true }).compare;

  function FormulaListPage(controller) {
    const self = host.s13BasesToolbarPage.call(this, controller) || this;
    self.query = "";
    self.searchComponent = new host.SearchComponent(self.containerEl)
      .setPlaceholder(s13BasesT().placeholderSearchProperty())
      .onChange((query) => {
        self.query = query;
        self.renderSummaryFormulaList();
      });
    const itemsEl = self.containerEl.createDiv("bases-toolbar-items");
    self.chooser = new host.GroupedSuggestionList(self, itemsEl, self.scope);
    self.scope.register([], "ArrowRight", () => {
      const selected = self.chooser.getSelectedValue();
      if (selected?.type === "formula") self.showFormulaPage(selected.name);
    });
    return self;
  }
  inherit(FormulaListPage, host.s13BasesToolbarPage);

  FormulaListPage.prototype.onShow = function () {
    this.searchComponent.autoSelect();
    this.renderSummaryFormulaList();
  };

  FormulaListPage.prototype.showFormulaPage = function (name) {
    this.controller.show(new S13SummaryFormulaPage(this.controller, name));
  };

  FormulaListPage.prototype.selectSuggestion = function (item, el) {
    if (item.type === "action") item.callback();
    else if (item.type === "formula") {
      this.controller.selectSummaryFormula(item.name);
      this.controller.close();
    }
    const selectedEl = this.chooser.getSelectedElement();
    if (selectedEl) {
      selectedEl.empty();
      this.renderSuggestion(item, selectedEl);
    }
  };

  /** All summary formulas for the property: type defaults plus user-defined ones. */
  FormulaListPage.prototype.getSummaryFormulas = function () {
    const baseId = host.s13FormulaBaseForType(this.controller.propertyId);
    const result = {};
    const evaluated = this.controller.queryController.mockContext.evaluateIdent(baseId);
    const defaults = host.s13SummaryFormulasForType(evaluated.type);
    for (const name in defaults) result[name] = { formula: new host.s13FormulaValue(defaults[name]), custom: false };
    const custom = this.controller.queryController.query.summaryFormulas;
    if (custom) for (const name in custom) result[name] = { formula: custom[name], custom: true };
    return result;
  };

  FormulaListPage.prototype.renderSummaryFormulaList = function () {
    const self = this;
    const prepared = prepareQuery(this.query);
    const suggestions = [];
    const formulas = this.getSummaryFormulas();
    const names = Object.keys(formulas);
    names.sort(collator);
    for (const name of names) {
      if (fuzzyMatchJs(prepared, name)) {
        const entry = formulas[name];
        suggestions.push({ type: "formula", name, group: "formulas", formula: entry.formula, custom: entry.custom });
      }
    }
    const query = this.query.trim();
    if (query && !Object.hasOwn(names, query)) {
      suggestions.push({
        type: "action",
        name: s13BasesT().actionAddSummary({ name: query }),
        icon: "lucide-plus",
        group: "actions",
        callback: () => {
          const name = self.query.trim() || s13BasesT().labelUntitledProperty();
          self.controller.queryController.query.setSummaryFormula(name, new host.s13FormulaValue(""));
          self.controller.selectSummaryFormula(name);
          self.controller.show(new S13SummaryFormulaPage(self.controller, name));
        },
      });
    } else {
      suggestions.push({
        type: "action",
        name: s13BasesT().buttonAddSummary(),
        icon: "lucide-square-function",
        group: "actions",
        callback: () => {
          const name = uniqueName(new Set(names), "new summary");
          self.controller.selectSummaryFormula(name);
          self.controller.show(new S13SummaryFormulaPage(self.controller, name));
        },
      });
    }
    if (this.controller.getSelectedSummaryKey() !== null) {
      suggestions.push({
        type: "action",
        name: s13BasesT().buttonHideSummary(),
        icon: "lucide-trash-2",
        group: "actions",
        callback: () => {
          self.controller.selectSummaryFormula(null);
          self.controller.close();
        },
      });
    }
    this.chooser.setSuggestions(suggestions);
  };

  FormulaListPage.prototype.renderSuggestion = function (item, el) {
    const self = this;
    el.addClass("bases-toolbar-menu-item", "bases-summary-menu-item");
    el.toggleClass("mod-active", this.controller.getSelectedSummaryKey() === item.name);
    const info = el.createDiv("bases-toolbar-menu-item-info");
    const iconEl = info.createDiv("bases-toolbar-menu-item-info-icon");
    if (item.type === "action") {
      host.setIcon(iconEl, item.icon);
      info.createDiv({ cls: "bases-toolbar-menu-item-name", text: item.name });
    } else if (item.type === "formula") {
      info.createDiv({ cls: "bases-toolbar-menu-item-name", text: item.name });
      if (item.formula.formula instanceof host.s13FormulaParseError) {
        iconEl.addClass("mod-error");
        setElementTooltip(iconEl, item.formula.formula.getErrorMessage());
      } else {
        iconEl.removeClass("mod-error");
      }
      const value = item.formula.getValue(this.controller.ctx);
      if (value && value !== host.s13BasesValueEmpty.value) {
        if (value instanceof host.s13ErrorValue) {
          info.createDiv({ cls: "bases-toolbar-menu-item-value", text: env().gm.dialogue.labelError() });
          host.setIcon(iconEl, value.icon);
        } else {
          const text = value instanceof host.s13NumberValue ? host.s13NumberFormat({}).format(value.data) : value.toString();
          info.createDiv({ cls: "bases-toolbar-menu-item-value", text });
          host.setIcon(iconEl, value.icon);
        }
      } else {
        host.setIcon(iconEl, "lucide-square-function");
      }
      const chevron = el.createDiv("clickable-icon bases-toolbar-menu-item-icon");
      host.setIcon(chevron, "lucide-chevron-right");
      chevron.addEventListener("click", (event) => {
        event.preventDefault();
        const index = self.chooser.selectedItem;
        const selected = self.chooser.values[index];
        if (selected.type === "formula") {
          if (!selected.custom) self.controller.queryController.query.setSummaryFormula(selected.name, selected.formula);
          self.showFormulaPage(selected.name);
        }
      });
    }
  };

  S13SummaryFormulaListPage = FormulaListPage;
  return FormulaListPage;
}

/** Page of the summary menu editing one summary formula. */
function defineS13SummaryFormulaPage(host) {
  function FormulaPage(controller, formulaName) {
    const self = host.s13BasesToolbarPage.call(this, controller) || this;
    self.formulaName = formulaName;
    const query = self.query = controller.queryController.query;
    const header = self.containerEl.createDiv("bases-toolbar-menu-container-header");
    const back = header.createDiv("back-button");
    host.setIcon(back.createDiv("back-icon"), "lucide-chevron-left");
    back.createDiv({ text: s13BasesT().titleEditProperty({ formulaName }), cls: "back-label" });
    back.addEventListener("click", () => self.controller.back());
    const more = header.createDiv("clickable-icon");
    host.setIcon(more, "lucide-more-vertical");
    const close = header.createDiv("close-icon clickable-icon");
    host.setIcon(close, "lucide-x");
    close.addEventListener("click", () => controller.close());
    self.scope.register([], "Escape", () => self.controller.back());
    const form = self.containerEl.createDiv("bases-toolbar-menu-form");
    form.createDiv("input-row", (row) => {
      row.createDiv({ cls: "input-row-label", text: s13BasesT().labelSummaryName() });
      const input = new host.TextComponent(row.createDiv("input-row-content"))
        .setPlaceholder(formulaName)
        .setValue(formulaName)
        .autoSelect()
        .inputEl;
      input.addEventListener("blur", () => {
        const value = input.value.trim();
        if (value !== formulaName) {
          query.renameSummaryFormula(formulaName, value);
          formulaName = self.formulaName = value;
        }
      });
      input.addEventListener("keydown", (event) => {
        if (event.isComposing || event.defaultPrevented) return;
        if (event.key === "Escape") {
          event.preventDefault();
          input.value = formulaName;
          input.blur();
        } else if (event.key === "Enter") {
          event.preventDefault();
          input.blur();
        }
      });
    });
    const stored = query.summaryFormulas ?? {};
    const formula = Object.hasOwn(stored, formulaName) ? stored[formulaName] : null;
    const row = form.createDiv("input-row");
    host.s13FormulaEditor.appendHelpIcon(row.createDiv({ cls: "input-row-label", text: s13BasesT().labelFormula() }));
    const content = row.createDiv("input-row-content");
    new host.s13FormulaEditor(content, formula, {
      updateFormula: (value) => query.setSummaryFormula(formulaName, value),
      extensions: [new host.s13FormulaEditorExtensions(new host.s13SummaryValuesEditor(self.controller.app))],
      placeholder: "values.reduce( ... )",
    });
    more.addEventListener("click", (event) => self.showActions(event, more));
    return self;
  }
  inherit(FormulaPage, host.s13BasesToolbarPage);

  FormulaPage.prototype.showActions = function (event, target) {
    const self = this;
    if (target && target.hasClass("has-active-menu")) return;
    const menu = host.Menu.forEvent(event);
    menu.addSections(["danger"]);
    if (target) menu.setParentElement(target);
    menu.addItem((item) => item.setTitle(s13BasesT().actionDeleteSummary()).setSection("danger").setWarning(true).onClick(() => {
      self.query.deleteSummaryFormula(self.formulaName);
      self.controller.back();
    }));
    menu.showAtMouseEvent(event);
  };

  S13SummaryFormulaPage = FormulaPage;
  return FormulaPage;
}

/** Quick-switcher style modal for picking a file to insert at the cursor. */
function defineS13FilePickerModal(host) {
  function FilePickerModal(parentArg, text) {
    const self = host.s13QuickSwitcherModalBase.call(this, parentArg) || this;
    self.emptyStateText = env().gm.plugins.quickSwitcher.labelNoNoteCreateNew();
    self.allowCreateNewFile = true;
    self.text = text;
    self.shouldShowUnresolved = true;
    self.shouldShowNonImageAttachments = false;
    self.shouldShowImages = false;
    self.shouldShowNonAttachments = false;
    self.shouldShowAllTypes = false;
    self.setPlaceholder("Choose file to insert");
    self.setInstructions([
      { command: "↑↓", purpose: "to navigate" },
      { command: "↵", purpose: "to select" },
      { command: "esc", purpose: "to dismiss" },
    ]);
    return self;
  }
  inherit(FilePickerModal, host.s13QuickSwitcherModalBase);

  FilePickerModal.prototype.onChooseSuggestion = async function (suggestion) {
    const app = this.app;
    let file = null;
    try {
      if (!suggestion) {
        file = await app.fileManager.createNewMarkdownFileFromLinktext(this.inputEl.value, "");
      } else if (suggestion.type === "unresolved") {
        file = await app.fileManager.createNewMarkdownFileFromLinktext(suggestion.linktext, "");
      } else if (suggestion.type === "file" || suggestion.type === "alias") {
        file = suggestion.file;
      }
    } catch (error) {
      new host.Notice(error.toString());
    }
    if (file) {
      await app.fileManager.insertIntoFile(file, this.text);
      await app.workspace.getLeaf().openFile(file);
    }
  };

  return FilePickerModal;
}

/** Caches downscaled data-URL backgrounds for remote images (canvas covers etc.). */
function defineS13Thumbnailer(host) {
  function Thumbnailer() {
    this.items = {};
    this.queue = new host.SerialTaskQueue();
  }

  Thumbnailer.prototype.thumbnailBg = function (el, url) {
    const self = this;
    const items = this.items;
    if (Object.hasOwn(items, url)) {
      el.style.backgroundImage = `url("${items[url]}")`;
      return;
    }
    const raw = `url("${url}")`;
    el.style.backgroundImage = raw;
    let format = "";
    try {
      format = extensionOf(new URL(url).pathname);
      if (format === "gif" || format === "svg") return;
    } catch (e) { /* keep empty format */ }
    this.queue.queue(async () => {
      if (el.style.backgroundImage !== raw) return;
      if (Object.hasOwn(items, url)) {
        el.style.backgroundImage = `url("${items[url]}")`;
        return;
      }
      const image = new Image();
      image.crossOrigin = "anonymous";
      await new Promise((resolve) => {
        const done = () => resolve();
        image.addEventListener("load", done);
        image.addEventListener("error", done);
        env().activeWindow.setTimeout(done, 10000);
        image.src = url;
      });
      if (!el.isShown() || el.style.backgroundImage !== raw) return;
      const width = image.naturalWidth;
      const height = image.naturalHeight;
      if (width === 0 || height === 0) {
        items[url] = url;
        return;
      }
      const scale = Math.max(el.offsetWidth / width, el.offsetHeight / height);
      const ratio = scale * el.win.devicePixelRatio;
      if (ratio <= 0 || ratio > 0.5) {
        items[url] = url;
        return;
      }
      const w = Math.ceil(width * ratio);
      const h = Math.ceil(height * ratio);
      const canvas = document.createElement("canvas");
      const ctx = canvas.getContext("2d");
      ctx.imageSmoothingQuality = "high";
      canvas.width = w;
      canvas.height = h;
      ctx.drawImage(image, 0, 0, w, h);
      const data = canvas.toDataURL(format === "png" ? "image/png" : "image/jpeg");
      items[url] = data;
      el.style.backgroundImage = `url("${data}")`;
    });
  };

  Thumbnailer.prototype.clear = function () {
    this.items = {};
  };

  return Thumbnailer;
}

/** Help modal listing the canvas mouse/keyboard shortcuts. */
function defineS13CanvasHelpModal(host) {
  function CanvasHelpModal(view) {
    const self = host.Modal.call(this, view.app) || this;
    self.modalEl.addClass("mod-canvas-help");
    self.setTitle(s13CanvasI18n().labelCanvasHelp());
    const root = self.contentEl.createDiv("canvas-help");
    const addInstruction = (label, combos) => {
      root.createDiv({ cls: "canvas-instruction" }, (row) => {
        row.createDiv({ cls: "canvas-instruction-label", text: label });
        row.createDiv({ cls: "canvas-instruction-desc" }, (desc) => {
          for (const combo of combos) {
            desc.createSpan({ cls: "setting-hotkey", text: s13KeyNames(combo, host) });
          }
        });
      });
    };
    let panExtra = [["Shift", "Scroll"]];
    let horizontal = [["Shift", "Scroll"]];
    let zoom = [["Mod", "Scroll"], ["Space", "Scroll"]];
    if (view.plugin.options.defaultWheelBehavior === "zoom") {
      const swapped = [zoom, panExtra];
      panExtra = swapped[0];
      zoom = swapped[1];
      horizontal = [["Mod", "Shift", "Scroll"], ["Shift", "Space", "Scroll"]];
    }
    addInstruction(s13CanvasI18n().labelPan(), [["Space", "Drag"]].concat(panExtra));
    addInstruction(s13CanvasI18n().labelPanHorizontal(), horizontal);
    addInstruction(s13CanvasI18n().labelZoom(), zoom);
    addInstruction(s13CanvasI18n().actionZoomToFit(), [["Shift", "1"]]);
    addInstruction(s13CanvasI18n().actionZoomToSelection(), [["Shift", "2"]]);
    addInstruction(s13CanvasI18n().labelSelectAll(), [["Mod", "A"]]);
    addInstruction(s13CanvasI18n().labelAddRemoveSelection(), [["Shift", "Click"], ["Shift", "Drag to select"]]);
    addInstruction(s13CanvasI18n().actionCreateWithSize(), [["Mod", "Drag to select"]]);
    addInstruction(s13CanvasI18n().labelCloneCard(), [[host.Platform.isMacOS ? "Alt" : "Ctrl", "Drag"]]);
    addInstruction(s13CanvasI18n().labelConstrainMovementAxis(), [["Shift", "Drag"]]);
    addInstruction(s13CanvasI18n().labelDisableDragSnapping(), [[host.Platform.isMacOS ? "Ctrl" : "Alt"]]);
    addInstruction(s13CanvasI18n().labelRemoveCard(), [["Backspace"], ["Delete"]]);
    addInstruction(env().gm.setting.mobileToolbar.optionUndo(), [["Mod", "Z"]]);
    addInstruction(env().gm.setting.mobileToolbar.optionRedo(), [["Mod", "Y"], ["Mod", "Shift", "Z"]]);
    return self;
  }
  inherit(CanvasHelpModal, host.Modal);

  return CanvasHelpModal;
}

/** Registry of quick actions exposed to the mobile shell (OBS_QUICK_ACTION bridge). */
function defineS13QuickActions(host) {
  function QuickActions() {
    this.registeredActions = {};
  }

  QuickActions.prototype.load = function () {
    if (window.OBS_QUICK_ACTION_LISTENER != null) {
      window.OBS_QUICK_ACTION_LISTENER.remove();
      delete window.OBS_QUICK_ACTION_LISTENER;
    }
    if (window.OBS_QUICK_ACTION) {
      const pending = window.OBS_QUICK_ACTION;
      delete window.OBS_QUICK_ACTION;
      this.fireAction(pending);
    }
    if (host.capacitorApp) {
      host.capacitorApp.addListener("quickActionSelected", (event) => this.fireAction(event.id));
    }
  };

  QuickActions.prototype.registerQuickAction = function (id, action) {
    if (host.Platform.isMobileApp && host.capacitorApp) {
      this.registeredActions[id] = action;
      this.updateQuickActions();
    }
  };

  QuickActions.prototype.unregisterQuickAction = function (id) {
    delete this.registeredActions[id];
    this.updateQuickActions();
  };

  QuickActions.prototype.fireAction = function (id) {
    if (Object.hasOwn(this.registeredActions, id)) this.registeredActions[id].callback();
  };

  QuickActions.prototype.updateQuickActions = function () {
    const actions = Object.entries(this.registeredActions).map(([id, action]) => ({
      id,
      title: action.title,
      iconName: action.iconName,
      description: action.description,
    }));
    host.capacitorApp.setQuickActions({ actions });
  };

  return QuickActions;
}

