// ---- s14-startup.js ----
// Startup-time modal (s14): the "Startup time" dialog shown from the help/startup menu.
//
//   L7  StartupStat — one label/description/value row inside the modal (not a Component, just a
//       small builder object the modal composes lists from).
//   I7  StartupTimeModal — DialogModal listing device info and the recorded startup timings
//       (total, initialization, vault, workspace, core + community plugins) with a copy button.

/** One stat row: heading flag, label, optional description and a right-aligned value (was `L7`). */
class S14StartupStat {
  constructor(containerEl) {
    this.containerEl = containerEl.createDiv("startup-stat");
    this.infoEl = this.containerEl.createDiv("startup-info");
  }

  setHeading(isHeading) {
    this.containerEl.toggleClass("mod-heading", isHeading);
    return this;
  }

  addLabel(text) {
    this.infoEl.createSpan({ cls: "startup-label", text });
    return this;
  }

  addDesc(text) {
    this.infoEl.createSpan({ cls: "startup-desc", text });
    return this;
  }

  addValue(text) {
    this.containerEl.createDiv({ cls: "startup-value", text });
    return this;
  }
}

function defineStartupStat(host) {
  return S14StartupStat;
}

const s14Fmt = (host) => new host.s13NumberFormat({ maximumFractionDigits: 0 });
const s14Ms = (formatter, value) => formatter.format(value) + "ms";

/** Dialog listing where startup time went, with a button that copies the breakdown (was `I7`). */
function defineStartupTimeModal(host) {
  class StartupTimeModal extends host.DialogModal {
    constructor(app) {
      super(app);
      const t = env();
      this.setTitle("Startup time");
      this.modalEl.addClass("mod-lg", "mod-scrollable-content", "mod-plugin-debug");

      const fmt = s14Fmt(host);
      const ms = (v) => s14Ms(fmt, v);
      const Stat = S14StartupStat;
      const i18n = t.gm;

      // ---- device / environment ----
      const deviceList = this.contentEl.createDiv("startup-stat-list");
      const device = new Stat(deviceList).addLabel("Device");
      const os = new Stat(deviceList).addLabel("Operating system");
      const build = new Stat(deviceList).addLabel("Basalt");
      const platform = host.Platform;
      if (platform.isMobileApp) {
        device.addValue(`${platform.manufacturer} ${platform.model}`);
        os.addValue(`${platform.osName} ${platform.osVersion}`);
        build.addDesc(platform.version);
        build.addLabel("Build");
        build.addDesc(platform.build);
      } else if (platform.isDesktopApp) {
        device.containerEl.hide();
        os.addValue(`${platform.osName} ${platform.osVersion}`);
        build.addDesc(platform.version);
        build.addLabel("Installer");
        build.addDesc(platform.build);
      }

      // ---- core timings ----
      const coreList = this.contentEl.createDiv("startup-timing-list");
      const root = app.vault.getRoot();
      new Stat(coreList).setHeading(true).addLabel("Total app startup").addValue(ms(t.hD()));
      new Stat(coreList).addLabel("Initialization").addValue(ms(t.hD("initialization")));
      new Stat(coreList)
        .addLabel("Vault")
        .addDesc(i18n.nouns.fileWithCount({ count: root.getFileCount() }))
        .addValue(ms(t.hD("vault")));
      new Stat(coreList)
        .addLabel("Workspace")
        .addDesc(`${t.sD.views} tabs (${t.sD.deferredViews} deferred)`)
        .addValue(ms(t.hD("workspace")));
      new Stat(coreList)
        .addLabel("Core plugins")
        .addDesc(i18n.nouns.pluginActiveWithCount({ count: app.internalPlugins.getEnabledPlugins().length }))
        .addValue(ms(t.hD("corePlugins")));

      // ---- community plugins, slowest first ----
      const community = t.uD("communityPlugins");
      if (community) {
        const pluginList = this.contentEl.createDiv("startup-timing-list");
        const count = Object.keys(app.plugins.plugins).length;
        const timings = Object.values(community.children).map((c) => ({ id: c.key, time: c.duration }));
        new Stat(pluginList)
          .setHeading(true)
          .addLabel("Community plugins")
          .addDesc(i18n.nouns.pluginActiveWithCount({ count }))
          .addValue(ms(t.hD("communityPlugins")));
        timings.sort((a, b) => b.time - a.time);
        for (const { id, time } of timings) {
          const manifest = app.plugins.manifests[id];
          new Stat(pluginList).addLabel(manifest ? manifest.name : id).addDesc(manifest ? manifest.version : "").addValue(ms(time));
        }
      }

      const copyText = () => {
        const lines = ["Basalt start-up time breakdown", ""];
        if (platform.isDesktopApp) {
          lines.push(`Basalt version: ${platform.version}`);
          lines.push(`Installer version: ${platform.build}`);
          lines.push(`Operating system: ${platform.osName} ${platform.osVersion}`);
        }
        if (platform.isMobileApp) {
          lines.push(`Basalt version: ${platform.version} (${platform.build})`);
          lines.push(`API version: ${t.gte}`);
          lines.push(`Operating system: ${platform.osName} ${platform.osVersion} (${platform.manufacturer} ${platform.model})`);
          if (platform.isAndroidApp) lines.push(`Webview version: ${t.rD(navigator.userAgent)}`);
        }
        lines.push("");
        const fileCount = app.vault.getRoot().getFileCount();
        const pluginCount = Object.keys(app.plugins.plugins).length;
        lines.push(`- Total startup time: ${ms(t.hD())}`);
        lines.push(`- Initialization: ${ms(t.hD("initialization"))}`);
        const icloud = t.hD("icloud");
        if (icloud) lines.push(`- iCloud: ${ms(icloud)}`);
        lines.push(`- Vault (${fmt.format(fileCount)} files): ${ms(t.hD("vault"))}`);
        lines.push(`- Workspace (${t.sD.views} tabs, ${t.sD.deferredViews} deferred): ${ms(t.hD("workspace"))}`);
        lines.push(`- Core plugins: ${ms(t.hD("corePlugins"))}`);
        const communityTimings = t.uD("communityPlugins");
        if (communityTimings) {
          lines.push(`- Community plugins (${fmt.format(pluginCount)} active): ${ms(t.hD("communityPlugins"))}`);
          const timings = Object.values(communityTimings.children)
            .map((c) => ({ id: c.key, time: c.duration }))
            .sort((a, b) => b.time - a.time);
          for (const { id, time } of timings) {
            const manifest = app.plugins.manifests[id];
            lines.push(`  - ${manifest.name} (${manifest.version}): ${ms(time)}`);
          }
        }
        return lines.join("\n");
      };

      return this.addButton("mod-secondary", i18n.interface.labelCopy(), async () => {
        await navigator.clipboard.writeText(copyText());
        new t.fb(i18n.interface.copied({ context: "generic" }));
        return true;
      }).addButton("mod-cancel", i18n.dialogue.buttonDone(), () => {});
    }
  }
  return StartupTimeModal;
}

// ---- s15-slash.js ----
// Own Basalt implementation of the Slash-command core plugin.
//
// Registers an editor suggest that triggers on "/query" text, lists matching
// commands from the command palette plugin and executes the picked command.
// The trigger pattern is kept as data (replaces C9) and the plugin/suggest
// classes keep their observable behaviour.

const SH = () => env();

/** Trigger pattern for slash commands: a slash followed by non-space text (replaces C9). */
const s15SlashCommandPattern = /(^|\s)\/([^\s\/]*)$/;

let slashCache = null;

function buildSlashClasses() {
  const EditorSuggest = SH().NI;

  // -- E9: slash command suggest ------------------------------------------------
  function SlashCommandSuggest(app) {
    const self = EditorSuggest.apply(this, arguments) || this;
    return self;
  }
  inherit(SlashCommandSuggest, EditorSuggest);

  SlashCommandSuggest.prototype.onTrigger = function (cursor, editor, file) {
    if (!file) return null;
    const line = cursor.line;
    const before = editor.getLine(line).substr(0, cursor.ch);
    const match = before.match(s15SlashCommandPattern);
    if (!match) return null;
    const startCh = match.index + match[1].length;
    const query = match[2];
    return {
      start: { line, ch: startCh },
      end: { line, ch: cursor.ch },
      query,
    };
  };

  SlashCommandSuggest.prototype.selectSuggestion = function (suggestion, evt) {
    const context = this.context;
    this.close();
    if (!context) return;
    context.editor.replaceRange("", context.start, context.end);
    SH().K6(suggestion.item);
  };

  SlashCommandSuggest.prototype.getSuggestions = function (context) {
    const commands = this.app.internalPlugins.getPluginById("command-palette").instance.getCommands();
    const finder = prepareFuzzyFinder(context.query);
    const hits = [];
    for (const command of commands) {
      const match = finder(command.name);
      if (match) hits.push({ match, item: command });
    }
    sortHitsByScore(hits);
    return hits;
  };

  SlashCommandSuggest.prototype.renderSuggestion = function (suggestion, el) {
    el.addClass("mod-complex");
    const content = el.createSpan("suggestion-content");
    const aux = el.createSpan("suggestion-aux");
    const title = content.createDiv("suggestion-title");
    const command = suggestion.item;
    const name = command.name;
    const sep = name.indexOf(": ");
    if (sep !== -1) {
      const prefix = name.slice(0, sep);
      const rest = name.slice(sep + 2);
      renderResults(title.createSpan("suggestion-prefix"), prefix, suggestion.match);
      renderResults(title.createSpan(), rest, suggestion.match, -(sep + 2));
    } else {
      renderResults(title.createSpan(), name, suggestion.match);
    }
    const hotkeyManager = this.app.hotkeyManager;
    const hotkeys = hotkeyManager.getHotkeys(command.id);
    const defaults = hotkeyManager.getDefaultHotkeys(command.id);
    if (hotkeys) {
      for (const hotkey of hotkeys) {
        aux.createEl("kbd", { cls: "suggestion-hotkey", text: SH().Rb(hotkey) });
      }
    } else if (defaults) {
      for (const hotkey of defaults) {
        aux.createEl("kbd", { cls: "suggestion-hotkey", text: SH().Rb(hotkey) });
      }
    }
    const palette = this.app.internalPlugins.getPluginById("command-palette").instance;
    const pinned = palette.options.pinned;
    if (pinned && pinned.contains(command.id)) {
      aux.createSpan({ cls: "suggestion-flair" }, (span) => {
        SH().tv(span, "lucide-pin");
      });
    }
  };

  // -- k9: slash-command plugin -------------------------------------------------
  function SlashCommandPlugin() {
    this.id = "slash-command";
    this.name = SH().gm.plugins.slashCommand.name();
    this.description = SH().gm.plugins.slashCommand.desc();
    this.defaultOn = false;
  }
  SlashCommandPlugin.prototype.init = function (app, manifest) {
    this.suggest = new SlashCommandSuggest(app);
  };
  SlashCommandPlugin.prototype.onEnable = function (app, manifest) {
    app.workspace.editorSuggest.addSuggest(this.suggest);
  };
  SlashCommandPlugin.prototype.onDisable = function (app, manifest) {
    app.workspace.editorSuggest.removeSuggest(this.suggest);
  };

  return { E9: SlashCommandSuggest, k9: SlashCommandPlugin };
}

let slashBuilt = null;
function slashClasses() {
  if (!slashBuilt) slashBuilt = buildSlashClasses();
  return slashBuilt;
}

function defineSlashCommandSuggest(host) {
  return slashClasses().E9;
}
function defineSlashCommandPlugin(host) {
  return slashClasses().k9;
}

// ---- s15-slides.js ----
// Own Basalt implementation of the Slides core plugin.
//
// The plugin registers a "slides:start" global command and a file-menu item for
// markdown files; the view splits the document on thematic breaks, renders each
// slide through the markdown pipeline and drives the bundled reveal.js deck.
// Reveal.js itself is still the third-party script loaded through the host
// script loader (M9); everything else is own code.

const SV = () => env();
const slidesT = () => SV().gm.plugins.slides;

let slidesCache = null;

function buildSlidesClasses() {
  const Component = SV().jm;
  const Scope = SV().Ng;

  // -- x9: slides presentation view ------------------------------------------
  function SlidesView(app) {
    const self = Component.call(this) || this;
    self.containerEl = null;
    self.revealCssEl = null;
    self.themeCssEl = null;
    self.deck = null;
    self.app = app;
    self.scope = new Scope();
    self.scope.register([], "Escape", self.close.bind(self));
    return self;
  }
  inherit(SlidesView, Component);

  SlidesView.prototype.openFile = async function (file) {
    this.destroy();
    this.app.keymap.pushScope(this.scope);
    const text = await this.app.vault.read(file);
    try {
      if (this.containerEl) this.containerEl.detach();
      const revealReady = SV().M9.promise;
      const isLight = this.app.vault.getConfig("theme") === "moonstone";
      const containerEl = (this.containerEl = activeDocument.body.createDiv("slides-container"));
      const themeCssEl = (this.themeCssEl = activeDocument.head.createEl("link", { prepend: true }));
      themeCssEl.setAttribute("rel", "stylesheet");
      themeCssEl.setAttribute("href", isLight ? "/lib/reveal/white.css" : "/lib/reveal/black.css");
      const revealCssEl = (this.revealCssEl = activeDocument.head.createEl("link", { prepend: true }));
      revealCssEl.setAttribute("rel", "stylesheet");
      revealCssEl.setAttribute("href", "/lib/reveal/reveal.css");
      const revealEl = containerEl.createDiv("reveal");
      const slidesEl = revealEl.createDiv("slides");
      revealEl.createDiv("slides-close-btn", (btn) => {
        SV().tv(btn, "lucide-x-square");
        btn.addEventListener("click", this.close.bind(this));
      });
      const doc = SV().Kx(text);
      const frontmatter = SV().$x(doc);
      const definitions = { definitions: SV().oT(doc) };
      const children = doc.children;
      const slides = [[]];
      for (let i = 0; i < children.length; i++) {
        const child = children[i];
        if (child.type === "thematicBreak") slides.push([]);
        else slides.last().push(child);
      }
      for (let i = 0; i < slides.length; i++) {
        const group = slides[i];
        if (group.length === 0) continue;
        doc.children = group;
        const html = SV().Zx(doc, definitions);
        slidesEl.createEl("section", {}, (section) => {
          section.appendChild(SV().xL(html));
        });
      }
      const promises = [];
      SV().fq.postProcess(this.app, {
        docId: randomHex(16),
        sourcePath: file.path,
        frontmatter,
        promises,
        addChild: (child) => this.addChild(child),
        getSectionInfo: () => null,
        replace: () => null,
        containerEl: slidesEl,
        el: slidesEl,
      });
      if (promises.length > 0) await Promise.all(promises);
      await revealReady;
      this.deck = new Reveal(revealEl, {
        embedded: true,
        keyboardCondition: "focused",
        controlsTutorial: false,
        overview: false,
      }).initialize();
      setTimeout(() => {
        revealEl.dispatchEvent(new PointerEvent("pointerdown"));
      }, 0);
    } catch (err) {
      console.error(err);
      this.close();
    }
  };

  SlidesView.prototype.close = function () {
    this.destroy();
  };

  SlidesView.prototype.destroy = function () {
    this.app.keymap.popScope(this.scope);
    const deck = this.deck;
    const containerEl = this.containerEl;
    const revealCssEl = this.revealCssEl;
    const themeCssEl = this.themeCssEl;
    if (containerEl) {
      containerEl.detach();
      this.containerEl = null;
    }
    if (revealCssEl) {
      revealCssEl.detach();
      this.revealCssEl = null;
    }
    if (themeCssEl) {
      themeCssEl.detach();
      this.themeCssEl = null;
    }
    if (deck) deck.destroy();
  };

  // -- S9: slides plugin -------------------------------------------------------
  function SlidesPlugin() {
    this.id = "slides";
    this.name = slidesT().name();
    this.description = slidesT().desc();
  }
  SlidesPlugin.prototype.init = function (app, manifest) {
    const self = this;
    this.app = app;
    manifest.registerGlobalCommand({
      id: "slides:start",
      name: slidesT().actionStart(),
      icon: "lucide-monitor",
      checkCallback: (checking) => {
        const file = self.app.workspace.getActiveFile();
        if (file && file.extension === "md") {
          if (!checking) new SlidesView(self.app).openFile(file);
          return true;
        }
        return false;
      },
    });
  };
  SlidesPlugin.prototype.onEnable = function (app, manifest) {
    manifest.registerEvent(app.workspace.on("file-menu", this.onFileMenu, this));
  };
  SlidesPlugin.prototype.onFileMenu = function (menu, file) {
    const self = this;
    if (file instanceof SV().$T && file.extension === "md") {
      menu.addItem((item) =>
        item
          .setSection("view")
          .setTitle(slidesT().actionStart())
          .setIcon("lucide-monitor")
          .onClick(() => new SlidesView(self.app).openFile(file)),
      );
    }
  };

  return { x9: SlidesView, S9: SlidesPlugin };
}

let slidesBuilt = null;
function slidesClasses() {
  if (!slidesBuilt) slidesBuilt = buildSlidesClasses();
  return slidesBuilt;
}

function defineSlidesView(host) {
  return slidesClasses().x9;
}
function defineSlidesPlugin(host) {
  return slidesClasses().S9;
}

// ---- s16-backoff.js ----
// s16 slice: exponential backoff with jitter — used by the sync socket retry loop.

/** Z9: delays grow as base * 2^(failures-1), optionally jittered, clamped to [min, max]. */
function defineBackoff() {
  function Backoff(min, max, base, jitter) {
    this.min = min || 0;
    this.max = max === undefined ? Number.MAX_VALUE : max;
    this.base = base || 1000;
    this.jitter = jitter === undefined ? true : jitter;
    this.count = 0;
    this.nextTs = Date.now();
  }

  Backoff.prototype.success = function () {
    this.count = 0;
    this.nextTs = Date.now() + this.getTimeout();
  };

  Backoff.prototype.fail = function () {
    this.count++;
    this.nextTs = Date.now() + this.getTimeout();
  };

  Backoff.prototype.getTimeout = function () {
    if (this.count === 0) return this.min;
    let timeout = this.base * Math.pow(2, this.count - 1);
    if (this.jitter) timeout *= 0.5 + 0.5 * Math.random();
    return Math.floor(Math.min(this.max, this.min + timeout));
  };

  Backoff.prototype.getNextTs = function () {
    return this.nextTs;
  };

  Backoff.prototype.isReady = function () {
    return Date.now() > this.nextTs;
  };

  return Backoff;
}

